insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (128, 9, 93, 102, 'سورة التوبة ٩٣ – ١٠٢', '«إنما السبيل على الذين يستأذنونك وهم أغنياء»، الأعراب، و«والسابقون الأولون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 128) = $j$[{"lbl": "الآيات ٩٣ – ٩٦", "q": "۞إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ وَهُمۡ أَغۡنِيَآءُۚ رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَعۡلَمُونَ ﴿٩٣﴾ يَعۡتَذِرُونَ إِلَيۡكُمۡ إِذَا رَجَعۡتُمۡ إِلَيۡهِمۡۚ قُل لَّا تَعۡتَذِرُواْ لَن نُّؤۡمِنَ لَكُمۡ قَدۡ نَبَّأَنَا ٱللَّهُ مِنۡ أَخۡبَارِكُمۡۚ وَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٩٤﴾ سَيَحۡلِفُونَ بِٱللَّهِ لَكُمۡ إِذَا ٱنقَلَبۡتُمۡ إِلَيۡهِمۡ لِتُعۡرِضُواْ عَنۡهُمۡۖ فَأَعۡرِضُواْ عَنۡهُمۡۖ إِنَّهُمۡ رِجۡسٞۖ وَمَأۡوَىٰهُمۡ جَهَنَّمُ جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ ﴿٩٥﴾ يَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡاْ عَنۡهُمۡۖ فَإِن تَرۡضَوۡاْ عَنۡهُمۡ فَإِنَّ ٱللَّهَ لَا يَرۡضَىٰ عَنِ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٩٦﴾", "w": [["إنما السبيل", "الطريق إلى المعاقبة."], ["أغنياء", "واجدون لأهبة الجهاد مع سلامة أبدانهم."], ["الخوالف", "النساء والأطفال والعجزة."], ["إذا رجعتم إليهم", "إذا عدتم إليهم من تبوك، وكانوا بضعاً وثمانين رجلاً."], ["لن نؤمن لكم", "لن نصدّقكم فيما تقولون."]], "m": "ما زال السياق في المخلّفين: إنما السبيل إلى عقاب المخلّفين على الذين يستأذنونك في التخلّف وهم أغنياء قادرون على النفقة والسير، رضوا بأن يكونوا مع الخوالف من النساء، وطبع الله على قلوبهم بسبب نفاقهم فهم لا يعلمون أن تخلّفهم لا يجديهم نفعاً، لا على الذين لا يجدون ما ينفقون فرجعوا يبكون. ثم أخبر عن المخلّفين من المنافقين: يعتذرون إليكم إذا رجعتم إلى المدينة، قل: لا تعتذروا لن نؤمن لكم، قد نبّأنا الله من أخباركم، وسيرى الله عملكم ورسوله إن تبتم فأخلصتم أو أصررتم، ثم تُردّون إلى عالم الغيب والشهادة فينبّئكم بما كنتم تعملون ويجزيكم الجزاء العادل. سيحلفون بالله لكم إذا انقلبتم إليهم لتعرضوا عنهم فلا تؤاخذوهم، فأعرضوا عنهم إنهم رجس، ومأواهم جهنم جزاءً بما كانوا يكسبون من الكفر والنفاق. يحلفون لكم معتذرين لترضوا عنهم، فإن ترضوا عنهم فلن ينفعهم رضاكم، فإن الله لا يرضى عن القوم الفاسقين، ومن سخط الله عليه أهلكه وعذّبه.", "h": ["لا سبيل إلى أذيّة المؤمنين الصادقين إذا تخلّفوا، فإنهم ما تخلّفوا إلا لعذر، وإنما السبيل على الأغنياء القادرين على السير إلى الجهاد وقعدوا عنه لنفاقهم.", "مشروعية الاعتذار، على شرط أن يكون المرء صادقاً في اعتذاره."], "k": "«سيحلفون بالله لكم لترضوا عنهم»… هل يهمّني رضا الناس عن أعذاري، أكثر من رضا الله عن عملي؟"}, {"lbl": "الآيات ٩٧ – ٩٩", "q": "ٱلۡأَعۡرَابُ أَشَدُّ كُفۡرٗا وَنِفَاقٗا وَأَجۡدَرُ أَلَّا يَعۡلَمُواْ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٩٧﴾ وَمِنَ ٱلۡأَعۡرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغۡرَمٗا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ﴿٩٨﴾ وَمِنَ ٱلۡأَعۡرَابِ مَن يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِۚ أَلَآ إِنَّهَا قُرۡبَةٞ لَّهُمۡۚ سَيُدۡخِلُهُمُ ٱللَّهُ فِي رَحۡمَتِهِۦٓۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٩٩﴾", "w": [["الأعراب", "جمع أعرابي، وهو من سكن البادية."], ["أشد كفراً ونفاقاً", "من كفار ومنافقي الحاضرة."], ["وأجدر", "أحق وأولى."], ["حدود ما أنزل الله", "شرائع الإسلام."], ["مغرماً", "غرامة وخسراناً."], ["الدوائر", "جمع دائرة: ما يحيط بالإنسان من مصيبة أو نكبة."], ["دائرة السوء", "المصيبة التي تسوؤهم ولا تسرّهم، وهي الهلاك."], ["قربات", "جمع قربة، وهي المنزلة المحمودة."], ["وصلوات الرسول", "دعاؤه لهم بالخير."]], "m": "ما زال السياق في الكشف عن المنافقين: الأعراب، سكان البادية، أشد كفراً ونفاقاً من كفار الحاضرة ومنافقيها، وأجدر ألّا يعلموا حدود ما أنزل الله على رسوله من الشرائع، لبعدهم عن مواطن العلم، والله عليم حكيم. ومن الأعراب من يتخذ ما ينفق في الجهاد غرامة وخسارة، لأنه لا يؤمن بالثواب الأخروي، ويتربّص بكم الدوائر متى تنزل بكم المصائب فيتخلّص منكم ومن الإنفاق لكم، عليهم دائرة السوء، دعاء عليهم جزاء تربّصهم، والله سميع لأقوالهم عليم بنياتهم. والأعراب ليسوا سواء: ومنهم من يؤمن بالله واليوم الآخر، ويتخذ ما ينفق قربات يتقرّب بها إلى الله، ووسيلة لدعاء الرسول، إذ كان ﷺ إذا أتاه المؤمن بصدقته دعا له، كقوله: «اللهم صلّ على آل أبي أوفى»، ألا إنها قربة لهم تقبّلها منهم، سيدخلهم الله في رحمته، الجنة، إن الله غفور رحيم، يطهّر أولياءه أولاً ثم ينعم عليهم بجواره.", "h": ["بيان أن سكان البادية يُحرمون من كثير من الآداب والمعارف، فلذا سكن البادية غير محمود إلا إذا كان فراراً من الفتن.", "من الأعراب المؤمن والكافر، والبر التقي والعاصي الفاجر، كسكان المدن، إلا أن كفار البادية ومنافقيها أشد كفراً ونفاقاً لتأثير البيئة.", "فضل النفقة في سبيل الله، والإخلاص فيها لله تعالى."], "k": "«ويتخذ ما ينفق قربات عند الله»… حين أعطي، هل أراه مغرماً يثقلني، أم قربة ترفعني؟"}, {"lbl": "الآيات ١٠٠ – ١٠٢", "q": "وَٱلسَّـٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحۡسَٰنٖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ وَأَعَدَّ لَهُمۡ جَنَّـٰتٖ تَجۡرِي تَحۡتَهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١٠٠﴾ وَمِمَّنۡ حَوۡلَكُم مِّنَ ٱلۡأَعۡرَابِ مُنَٰفِقُونَۖ وَمِنۡ أَهۡلِ ٱلۡمَدِينَةِ مَرَدُواْ عَلَى ٱلنِّفَاقِ لَا تَعۡلَمُهُمۡۖ نَحۡنُ نَعۡلَمُهُمۡۚ سَنُعَذِّبُهُم مَّرَّتَيۡنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٖ ﴿١٠١﴾ وَءَاخَرُونَ ٱعۡتَرَفُواْ بِذُنُوبِهِمۡ خَلَطُواْ عَمَلٗا صَٰلِحٗا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٠٢﴾", "w": [["والسابقون", "إلى الإيمان والهجرة والنصرة والجهاد."], ["اتبعوهم بإحسان", "في أعمالهم الصالحة."], ["رضي الله عنهم", "لإيمانهم وصالح أعمالهم."], ["ورضوا عنه", "بما أنعم عليهم من جلائل النعم وعظائم المنن."], ["وممن حولكم", "حول المدينة من قبائل العرب."], ["مردوا", "مرنوا عليه وحذقوه وعتوا فيه."], ["سنعذّبهم مرتين", "الأولى قد تكون فضيحتهم بين المسلمين، والثانية عذاب القبر."]], "m": "والسابقون الأولون من المهاجرين والأنصار إلى الإيمان والهجرة والنصرة والجهاد، والذين اتبعوهم بإحسان فكانت أعمالهم موافقة لما شرع الله وبيّن رسوله، رضي الله عنهم بإيمانهم وصالح أعمالهم، ورضوا عنه بما أنالهم من إنعام وتكريم، وأعد لهم جنات تجري تحتها الأنهار خالدين فيها أبداً، ذلك الفوز العظيم: النجاة من النار ودخول الجنة. وممن حولكم من الأعراب منافقون، ومن أهل المدينة مردوا على النفاق، لتمرّسهم فيه أصبحوا لا يُعرفون، لا تعلمهم نحن نعلمهم، سنعذّبهم مرتين في الدنيا: بفضحهم أو بما شاء، وفي قبورهم، ثم يُردّون بعد البعث إلى عذاب عظيم. وآخرون اعترفوا بذنوبهم، وهم أبو لبابة ونفر معه ستة أو سبعة، تخلّفوا عن تبوك بغير عذر، فلما سمعوا ما نزل في المتخلّفين ربطوا أنفسهم في سواري المسجد وقالوا: لن نحلّ أنفسنا حتى يحلّنا رسول الله ﷺ، خلطوا عملاً صالحاً من الإيمان والجهاد، وآخر سيئاً وهو التخلّف، عسى الله أن يتوب عليهم، إعلام بتوبته، إن الله غفور رحيم، فجاء رسول الله ﷺ فحلّ رباطهم.", "h": ["فضل السبق للخير والفوز بالأولية فيه.", "فضل أصحاب رسول الله ﷺ على غيرهم ممن جاء بعدهم.", "فضل التابعين لأصحاب رسول الله ﷺ إن أحسنوا المتابعة.", "علم ما في القلوب إلى الله تعالى، فلا يعلم أحد من الغيب إلا ما علّمه الله عز وجل.", "الرجاء لأهل التوحيد الذين خلطوا عملاً صالحاً وآخر سيئاً بأن يغفر الله لهم."], "k": "«خلطوا عملاً صالحاً وآخر سيئاً»… سيئتي لا تُبطل رجائي؛ فهل أعترف بها كما اعترفوا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 128;
insert into public.tdb_cards(topic, i, body) select 128, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩٣ – ٩٦", "q": "۞إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ وَهُمۡ أَغۡنِيَآءُۚ رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَعۡلَمُونَ ﴿٩٣﴾ يَعۡتَذِرُونَ إِلَيۡكُمۡ إِذَا رَجَعۡتُمۡ إِلَيۡهِمۡۚ قُل لَّا تَعۡتَذِرُواْ لَن نُّؤۡمِنَ لَكُمۡ قَدۡ نَبَّأَنَا ٱللَّهُ مِنۡ أَخۡبَارِكُمۡۚ وَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٩٤﴾ سَيَحۡلِفُونَ بِٱللَّهِ لَكُمۡ إِذَا ٱنقَلَبۡتُمۡ إِلَيۡهِمۡ لِتُعۡرِضُواْ عَنۡهُمۡۖ فَأَعۡرِضُواْ عَنۡهُمۡۖ إِنَّهُمۡ رِجۡسٞۖ وَمَأۡوَىٰهُمۡ جَهَنَّمُ جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ ﴿٩٥﴾ يَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡاْ عَنۡهُمۡۖ فَإِن تَرۡضَوۡاْ عَنۡهُمۡ فَإِنَّ ٱللَّهَ لَا يَرۡضَىٰ عَنِ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٩٦﴾", "w": [["إنما السبيل", "الطريق إلى المعاقبة."], ["أغنياء", "واجدون لأهبة الجهاد مع سلامة أبدانهم."], ["الخوالف", "النساء والأطفال والعجزة."], ["إذا رجعتم إليهم", "إذا عدتم إليهم من تبوك، وكانوا بضعاً وثمانين رجلاً."], ["لن نؤمن لكم", "لن نصدّقكم فيما تقولون."]], "m": "ما زال السياق في المخلّفين: إنما السبيل إلى عقاب المخلّفين على الذين يستأذنونك في التخلّف وهم أغنياء قادرون على النفقة والسير، رضوا بأن يكونوا مع الخوالف من النساء، وطبع الله على قلوبهم بسبب نفاقهم فهم لا يعلمون أن تخلّفهم لا يجديهم نفعاً، لا على الذين لا يجدون ما ينفقون فرجعوا يبكون. ثم أخبر عن المخلّفين من المنافقين: يعتذرون إليكم إذا رجعتم إلى المدينة، قل: لا تعتذروا لن نؤمن لكم، قد نبّأنا الله من أخباركم، وسيرى الله عملكم ورسوله إن تبتم فأخلصتم أو أصررتم، ثم تُردّون إلى عالم الغيب والشهادة فينبّئكم بما كنتم تعملون ويجزيكم الجزاء العادل. سيحلفون بالله لكم إذا انقلبتم إليهم لتعرضوا عنهم فلا تؤاخذوهم، فأعرضوا عنهم إنهم رجس، ومأواهم جهنم جزاءً بما كانوا يكسبون من الكفر والنفاق. يحلفون لكم معتذرين لترضوا عنهم، فإن ترضوا عنهم فلن ينفعهم رضاكم، فإن الله لا يرضى عن القوم الفاسقين، ومن سخط الله عليه أهلكه وعذّبه.", "h": ["لا سبيل إلى أذيّة المؤمنين الصادقين إذا تخلّفوا، فإنهم ما تخلّفوا إلا لعذر، وإنما السبيل على الأغنياء القادرين على السير إلى الجهاد وقعدوا عنه لنفاقهم.", "مشروعية الاعتذار، على شرط أن يكون المرء صادقاً في اعتذاره."], "k": "«سيحلفون بالله لكم لترضوا عنهم»… هل يهمّني رضا الناس عن أعذاري، أكثر من رضا الله عن عملي؟"}, {"lbl": "الآيات ٩٧ – ٩٩", "q": "ٱلۡأَعۡرَابُ أَشَدُّ كُفۡرٗا وَنِفَاقٗا وَأَجۡدَرُ أَلَّا يَعۡلَمُواْ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٩٧﴾ وَمِنَ ٱلۡأَعۡرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغۡرَمٗا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ﴿٩٨﴾ وَمِنَ ٱلۡأَعۡرَابِ مَن يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِۚ أَلَآ إِنَّهَا قُرۡبَةٞ لَّهُمۡۚ سَيُدۡخِلُهُمُ ٱللَّهُ فِي رَحۡمَتِهِۦٓۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٩٩﴾", "w": [["الأعراب", "جمع أعرابي، وهو من سكن البادية."], ["أشد كفراً ونفاقاً", "من كفار ومنافقي الحاضرة."], ["وأجدر", "أحق وأولى."], ["حدود ما أنزل الله", "شرائع الإسلام."], ["مغرماً", "غرامة وخسراناً."], ["الدوائر", "جمع دائرة: ما يحيط بالإنسان من مصيبة أو نكبة."], ["دائرة السوء", "المصيبة التي تسوؤهم ولا تسرّهم، وهي الهلاك."], ["قربات", "جمع قربة، وهي المنزلة المحمودة."], ["وصلوات الرسول", "دعاؤه لهم بالخير."]], "m": "ما زال السياق في الكشف عن المنافقين: الأعراب، سكان البادية، أشد كفراً ونفاقاً من كفار الحاضرة ومنافقيها، وأجدر ألّا يعلموا حدود ما أنزل الله على رسوله من الشرائع، لبعدهم عن مواطن العلم، والله عليم حكيم. ومن الأعراب من يتخذ ما ينفق في الجهاد غرامة وخسارة، لأنه لا يؤمن بالثواب الأخروي، ويتربّص بكم الدوائر متى تنزل بكم المصائب فيتخلّص منكم ومن الإنفاق لكم، عليهم دائرة السوء، دعاء عليهم جزاء تربّصهم، والله سميع لأقوالهم عليم بنياتهم. والأعراب ليسوا سواء: ومنهم من يؤمن بالله واليوم الآخر، ويتخذ ما ينفق قربات يتقرّب بها إلى الله، ووسيلة لدعاء الرسول، إذ كان ﷺ إذا أتاه المؤمن بصدقته دعا له، كقوله: «اللهم صلّ على آل أبي أوفى»، ألا إنها قربة لهم تقبّلها منهم، سيدخلهم الله في رحمته، الجنة، إن الله غفور رحيم، يطهّر أولياءه أولاً ثم ينعم عليهم بجواره.", "h": ["بيان أن سكان البادية يُحرمون من كثير من الآداب والمعارف، فلذا سكن البادية غير محمود إلا إذا كان فراراً من الفتن.", "من الأعراب المؤمن والكافر، والبر التقي والعاصي الفاجر، كسكان المدن، إلا أن كفار البادية ومنافقيها أشد كفراً ونفاقاً لتأثير البيئة.", "فضل النفقة في سبيل الله، والإخلاص فيها لله تعالى."], "k": "«ويتخذ ما ينفق قربات عند الله»… حين أعطي، هل أراه مغرماً يثقلني، أم قربة ترفعني؟"}, {"lbl": "الآيات ١٠٠ – ١٠٢", "q": "وَٱلسَّـٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحۡسَٰنٖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ وَأَعَدَّ لَهُمۡ جَنَّـٰتٖ تَجۡرِي تَحۡتَهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١٠٠﴾ وَمِمَّنۡ حَوۡلَكُم مِّنَ ٱلۡأَعۡرَابِ مُنَٰفِقُونَۖ وَمِنۡ أَهۡلِ ٱلۡمَدِينَةِ مَرَدُواْ عَلَى ٱلنِّفَاقِ لَا تَعۡلَمُهُمۡۖ نَحۡنُ نَعۡلَمُهُمۡۚ سَنُعَذِّبُهُم مَّرَّتَيۡنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٖ ﴿١٠١﴾ وَءَاخَرُونَ ٱعۡتَرَفُواْ بِذُنُوبِهِمۡ خَلَطُواْ عَمَلٗا صَٰلِحٗا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٠٢﴾", "w": [["والسابقون", "إلى الإيمان والهجرة والنصرة والجهاد."], ["اتبعوهم بإحسان", "في أعمالهم الصالحة."], ["رضي الله عنهم", "لإيمانهم وصالح أعمالهم."], ["ورضوا عنه", "بما أنعم عليهم من جلائل النعم وعظائم المنن."], ["وممن حولكم", "حول المدينة من قبائل العرب."], ["مردوا", "مرنوا عليه وحذقوه وعتوا فيه."], ["سنعذّبهم مرتين", "الأولى قد تكون فضيحتهم بين المسلمين، والثانية عذاب القبر."]], "m": "والسابقون الأولون من المهاجرين والأنصار إلى الإيمان والهجرة والنصرة والجهاد، والذين اتبعوهم بإحسان فكانت أعمالهم موافقة لما شرع الله وبيّن رسوله، رضي الله عنهم بإيمانهم وصالح أعمالهم، ورضوا عنه بما أنالهم من إنعام وتكريم، وأعد لهم جنات تجري تحتها الأنهار خالدين فيها أبداً، ذلك الفوز العظيم: النجاة من النار ودخول الجنة. وممن حولكم من الأعراب منافقون، ومن أهل المدينة مردوا على النفاق، لتمرّسهم فيه أصبحوا لا يُعرفون، لا تعلمهم نحن نعلمهم، سنعذّبهم مرتين في الدنيا: بفضحهم أو بما شاء، وفي قبورهم، ثم يُردّون بعد البعث إلى عذاب عظيم. وآخرون اعترفوا بذنوبهم، وهم أبو لبابة ونفر معه ستة أو سبعة، تخلّفوا عن تبوك بغير عذر، فلما سمعوا ما نزل في المتخلّفين ربطوا أنفسهم في سواري المسجد وقالوا: لن نحلّ أنفسنا حتى يحلّنا رسول الله ﷺ، خلطوا عملاً صالحاً من الإيمان والجهاد، وآخر سيئاً وهو التخلّف، عسى الله أن يتوب عليهم، إعلام بتوبته، إن الله غفور رحيم، فجاء رسول الله ﷺ فحلّ رباطهم.", "h": ["فضل السبق للخير والفوز بالأولية فيه.", "فضل أصحاب رسول الله ﷺ على غيرهم ممن جاء بعدهم.", "فضل التابعين لأصحاب رسول الله ﷺ إن أحسنوا المتابعة.", "علم ما في القلوب إلى الله تعالى، فلا يعلم أحد من الغيب إلا ما علّمه الله عز وجل.", "الرجاء لأهل التوحيد الذين خلطوا عملاً صالحاً وآخر سيئاً بأن يغفر الله لهم."], "k": "«خلطوا عملاً صالحاً وآخر سيئاً»… سيئتي لا تُبطل رجائي؛ فهل أعترف بها كما اعترفوا؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (129, 9, 103, 112, 'سورة التوبة ١٠٣ – ١١٢', '«خذ من أموالهم صدقة»، مسجد الضرار و«لمسجد أُسّس على التقوى»، و«إن الله اشترى من المؤمنين أنفسهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 129) = $j$[{"lbl": "الآيات ١٠٣ – ١٠٦", "q": "خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿١٠٣﴾ أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ هُوَ يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَأۡخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ ﴿١٠٤﴾ وَقُلِ ٱعۡمَلُواْ فَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٠٥﴾ وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمۡ وَإِمَّا يَتُوبُ عَلَيۡهِمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿١٠٦﴾", "w": [["صدقة", "مالاً يُتقرّب به إلى الله تعالى."], ["تطهّرهم وتزكّيهم بها", "تطهّرهم من ذنوبهم، وتزكّيهم أنت أيها الرسول بدعائك لهم."], ["وصلّ عليهم", "ادعُ لهم بخير."], ["سكن لهم", "رحمة وطمأنينة في نفوسهم."], ["مُرجَون لأمر الله", "مؤخَّرون لحكم الله وقضائه."], ["عليم حكيم", "عليم بخلقه نياتٍ وأعمالاً، حكيم في قضائه وشرعه."]], "m": "لما قال المتخلّفون التائبون: هذه أموالنا التي تخلّفنا بسببها صدقة فخذها يا رسول الله، فقال: «إني لم أُؤمر بذلك»، أنزل الله: خذ من أموالهم صدقة تطهّرهم من ذنوبهم ومن أوضار الشح، وتزكّيهم بقبولك لها، وصلّ عليهم فادعُ لهم، إن صلاتك سكن لهم ورحمة وطمأنينة، والله سميع لأقوالهم عليم بنياتهم. ألم يعلموا أن الله هو يقبل التوبة عن عباده ويأخذ الصدقات فيقبلها، وأن الله هو التواب الرحيم؟ وقل اعملوا الصالحات تطهيراً لنفوسكم، فسيرى الله عملكم ورسوله والمؤمنون، وستُردّون إلى عالم الغيب والشهادة فينبّئكم بما كنتم تعملون. وآخرون مُرجَون لأمر الله، الصنف الثالث من المتخلّفين: كعب بن مالك، ومرارة بن الربيع، وهلال بن أمية، لم يأتوا ليعتذروا كما فعل أبو لبابة ومن معه، فأمر الرسول ﷺ بمقاطعتهم حتى يحكم الله فيهم، إما يعذّبهم وإما يتوب عليهم، والله عليم حكيم، فبقوا كذلك حتى ضاقت بهم الأرض بما رحبت، ثم تاب الله عليهم كما في آخر السورة.", "h": ["الصدقة تكفّر الذنوب، وتطهّر الأرواح من رذيلة الشح والبخل.", "يُستحب لمن يأخذ صدقة امرئ مسلم أن يدعو له بمثل: آجرك الله على ما أعطيت، وبارك لك فيما أبقيت.", "ينبغي للتائب من الذنب الكبير أن يُكثر بعده من الصالحات، كالصدقات والصلوات.", "فضيلة الخوف والرجاء، فالخوف يحمل على ترك المعاصي، والرجاء يحمل على الإكثار من الطاعات."], "k": "«خذ من أموالهم صدقة تطهّرهم»… ما الذنب الذي أحتاج أن أتبعه بصدقة تطهّرني منه؟"}, {"lbl": "الآيات ١٠٧ – ١١٠", "q": "وَٱلَّذِينَ ٱتَّخَذُواْ مَسۡجِدٗا ضِرَارٗا وَكُفۡرٗا وَتَفۡرِيقَۢا بَيۡنَ ٱلۡمُؤۡمِنِينَ وَإِرۡصَادٗا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ وَلَيَحۡلِفُنَّ إِنۡ أَرَدۡنَآ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ ﴿١٠٧﴾ لَا تَقُمۡ فِيهِ أَبَدٗاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ ﴿١٠٨﴾ أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ أَم مَّنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٖ فَٱنۡهَارَ بِهِۦ فِي نَارِ جَهَنَّمَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٠٩﴾ لَا يَزَالُ بُنۡيَٰنُهُمُ ٱلَّذِي بَنَوۡاْ رِيبَةٗ فِي قُلُوبِهِمۡ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ ﴿١١٠﴾", "w": [["ضراراً", "مضارّة لأهل الإسلام بتفرقة المسلمين وإيجاد العداوات بينهم."], ["وإرصاداً", "انتظاراً وترقّباً."], ["إلا الحسنى", "إلا الخير والحال الأحسن."], ["لا تقم فيه أبداً", "لا تقم فيه للصلاة أبداً."], ["أُسّس على التقوى", "بُني على التقوى، وهو مسجد قباء."], ["فيه رجال", "هم بنو عمرو بن عوف."], ["على تقوى من الله", "على خوف منه."], ["ورضوان", "رجاء رضوان الله تعالى."], ["على شفا جرف هار", "على طرف جرف مشرف على السقوط، وهو مسجد الضرار."], ["ريبة في قلوبهم", "شكاً في نفوسهم."], ["إلا أن تقطّع قلوبهم", "تُفصل من صدورهم فيموتوا."]], "m": "ما زال السياق في فضح المنافقين: والذين اتخذوا مسجداً ضراراً وكفراً، اثنا عشر رجلاً من أهل المدينة أتوا النبي ﷺ وهو شاخص إلى تبوك فقالوا: بنينا مسجداً للعاجز والمريض والليلة المطيرة فصلّ لنا فيه، فقال: «إني على جناح سفر، وإن عدنا صلينا لكم فيه»، فلما عاد ونزل بذي أوان قرب المدينة نزل الوحي بشأنه، فبعث مالك بن الدخشم ومعن بن عدي فقال: «انطلقا إلى هذا المسجد الظالم أهله فاهدماه وحرّقاه»، ففعلا. بنوه ضراراً بمسجد قباء، وكفراً بالله ورسوله، وتفريقاً بين المؤمنين المجتمعين في قباء حتى يجدوا مجالاً للتشكيك، وإرصاداً لمن حارب الله ورسوله من قبل، وهو أبو عامر الراهب الفاسق الذي أمرهم ببنائه، وقال للنبي ﷺ: ما وجدت قوماً يقاتلونك إلا قاتلتك معهم، ثم ذهب إلى الروم يستعديهم فهلك. وليحلفنّ: إن أردنا إلا الحسنى، والله يشهد إنهم لكاذبون. لا تقم فيه أبداً، لمسجد أُسّس على التقوى من أول يوم، مسجده ﷺ ومسجد قباء، أحق أن تقوم فيه، فيه رجال يحبون أن يتطهّروا من الخبث الحسي والمعنوي، فكانوا يجمعون في الاستنجاء بين الحجارة والماء، والله يحب المطّهّرين. أفمن أسّس بنيانه على تقوى من الله ورضوان خير أم من أسّس بنيانه على شفا جرف هار فانهار به في نار جهنم؟ والله لا يهدي القوم الظالمين. لا يزال بنيانهم الذي بنوا ريبة في قلوبهم إلا أن تقطّع قلوبهم فيموتوا كافرين، والله عليم حكيم.", "h": ["بيان أكبر مؤامرة ضد الإسلام قام بها المنافقون بإرشاد الفاسق أبي عامر الراهب.", "بيان أن حب الشرف والسلطة سبب البلاء كل البلاء، فأبو عامر ترهّب لأجل الشرف على أهل المدينة، فلما فقده بالإسلام حارب من كان سبب حرمانه.", "لا يصح الاغترار بأقوال أهل النفاق، فإنها كذب كلها.", "أيّما مسجد بُني للإضرار والتفرقة بين المسلمين يجب هدمه، وتحرم الصلاة فيه.", "فضل التطهّر والمبالغة في الطهارتين الروحية والبدنية.", "التحذير من الظلم والإسراف فيه، فإنه يحرم صاحبه هداية الله فيهلك وهو ظالم فيخسر دنيا وأخرى."], "k": "«أفمن أسّس بنيانه على تقوى من الله ورضوان»… ما أبنيه اليوم من عمل أو بيت أو علاقة، على أي أساس أضعه؟"}, {"lbl": "الآيتان ١١١ – ١١٢", "q": "۞إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ فَيَقۡتُلُونَ وَيُقۡتَلُونَۖ وَعۡدًا عَلَيۡهِ حَقّٗا فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُواْ بِبَيۡعِكُمُ ٱلَّذِي بَايَعۡتُم بِهِۦۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١١١﴾ ٱلتَّـٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّـٰٓئِحُونَ ٱلرَّـٰكِعُونَ ٱلسَّـٰجِدُونَ ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ ﴿١١٢﴾", "w": [["الجنة", "دار السلام التي أعدّها الله تعالى للمتقين."], ["يقاتلون", "أي الكفار والمشركين."], ["وعداً", "وعدهم وعداً حقاً."], ["في التوراة", "مذكوراً في التوراة والإنجيل والقرآن."], ["ومن أوفى بعهده", "لا أحد أوفى بعهده من الله تعالى."], ["التائبون", "من الشرك والنفاق والمعاصي."], ["العابدون", "المطيعون لله في تذلّل وخشوع، مع حبهم لله وتعظيمهم له."], ["السائحون", "الصائمون، والخارجون في سبيل الله لطلب علم أو تعليمه أو جهاد لأعدائه."], ["الآمرون بالمعروف", "بعبادة الله تعالى وتوحيده فيها."], ["الناهون عن المنكر", "عن الشرك والمعاصي."], ["والحافظون لحدود الله", "القائمون عليها العاملون بها."], ["وبشّر المؤمنين", "أي بالجنة دار السلام."]], "m": "لما ذكر حال المتخلّفين ذكر فضل الجهاد ترغيباً فيه: إن الله اشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة، يقاتلون في سبيل الله أعداءه فيَقتلون ويُقتلون، وعداً عليه حقاً أثبته في التوراة والإنجيل والقرآن، ومن أوفى بعهده من الله؟ لا أحد، فاستبشروا ببيعكم الذي بايعتم به وافرحوا، وذلك هو الفوز العظيم. ثم ذكر أوصاف أهل البيع التسعة: التائبون من الشرك والمعاصي، العابدون المطيعون لله طاعة ملؤها المحبة والتعظيم والرهبة، الحامدون لله في السراء والضراء، السائحون: الصائمون كما في الحديث، والخارجون لطلب علم أو غزو أو تعليم أو دعوة، الراكعون الساجدون المقيمون الصلاة المكثرون من نوافلها كأنهم دائماً في ركوع وسجود، الآمرون بالمعروف من الإيمان والتوحيد والطاعة، والناهون عن المنكر من الكفر والشرك والمعصية، والحافظون لحدود الله بالقيام عليها وعملها بعد العلم بها، وبشّر المؤمنين أهل الإيمان الصادق بالنصر في الدنيا والجنة يوم القيامة.", "h": ["بيان فضل الله تعالى ومنّته على عباده المؤمنين، حيث وهبهم أرواحهم وأموالهم ثم اشتراها منهم بالجنة.", "فضل الجهاد والاستشهاد في سبيل الله.", "على المؤمن أن يُشعر نفسه أن بدنه وماله لله تعالى، وأن عليه رعايتهما وحفظهما، حتى إذا رُفعت راية الجهاد وطالب إمام المسلمين بالنفس والمال قدّمهما، إذ هما وديعة الله عنده.", "على المؤمن ألا يُدخل الضرر على نفسه ولا على ماله بحكم أنهما لله تعالى.", "على المؤمن أن يتعاهد نفسه ليرى هل هو متّصف بهذه الصفات التسع، فإن رأى نقصاً كمّله، وإن رأى كمالاً حمد الله عليه وحافظ عليه."], "k": "«التائبون العابدون الحامدون…»… أيّ الصفات التسع أنا فيها أضعف، فأبدأ بها اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 129;
insert into public.tdb_cards(topic, i, body) select 129, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠٣ – ١٠٦", "q": "خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿١٠٣﴾ أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ هُوَ يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَأۡخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ ﴿١٠٤﴾ وَقُلِ ٱعۡمَلُواْ فَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٠٥﴾ وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمۡ وَإِمَّا يَتُوبُ عَلَيۡهِمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿١٠٦﴾", "w": [["صدقة", "مالاً يُتقرّب به إلى الله تعالى."], ["تطهّرهم وتزكّيهم بها", "تطهّرهم من ذنوبهم، وتزكّيهم أنت أيها الرسول بدعائك لهم."], ["وصلّ عليهم", "ادعُ لهم بخير."], ["سكن لهم", "رحمة وطمأنينة في نفوسهم."], ["مُرجَون لأمر الله", "مؤخَّرون لحكم الله وقضائه."], ["عليم حكيم", "عليم بخلقه نياتٍ وأعمالاً، حكيم في قضائه وشرعه."]], "m": "لما قال المتخلّفون التائبون: هذه أموالنا التي تخلّفنا بسببها صدقة فخذها يا رسول الله، فقال: «إني لم أُؤمر بذلك»، أنزل الله: خذ من أموالهم صدقة تطهّرهم من ذنوبهم ومن أوضار الشح، وتزكّيهم بقبولك لها، وصلّ عليهم فادعُ لهم، إن صلاتك سكن لهم ورحمة وطمأنينة، والله سميع لأقوالهم عليم بنياتهم. ألم يعلموا أن الله هو يقبل التوبة عن عباده ويأخذ الصدقات فيقبلها، وأن الله هو التواب الرحيم؟ وقل اعملوا الصالحات تطهيراً لنفوسكم، فسيرى الله عملكم ورسوله والمؤمنون، وستُردّون إلى عالم الغيب والشهادة فينبّئكم بما كنتم تعملون. وآخرون مُرجَون لأمر الله، الصنف الثالث من المتخلّفين: كعب بن مالك، ومرارة بن الربيع، وهلال بن أمية، لم يأتوا ليعتذروا كما فعل أبو لبابة ومن معه، فأمر الرسول ﷺ بمقاطعتهم حتى يحكم الله فيهم، إما يعذّبهم وإما يتوب عليهم، والله عليم حكيم، فبقوا كذلك حتى ضاقت بهم الأرض بما رحبت، ثم تاب الله عليهم كما في آخر السورة.", "h": ["الصدقة تكفّر الذنوب، وتطهّر الأرواح من رذيلة الشح والبخل.", "يُستحب لمن يأخذ صدقة امرئ مسلم أن يدعو له بمثل: آجرك الله على ما أعطيت، وبارك لك فيما أبقيت.", "ينبغي للتائب من الذنب الكبير أن يُكثر بعده من الصالحات، كالصدقات والصلوات.", "فضيلة الخوف والرجاء، فالخوف يحمل على ترك المعاصي، والرجاء يحمل على الإكثار من الطاعات."], "k": "«خذ من أموالهم صدقة تطهّرهم»… ما الذنب الذي أحتاج أن أتبعه بصدقة تطهّرني منه؟"}, {"lbl": "الآيات ١٠٧ – ١١٠", "q": "وَٱلَّذِينَ ٱتَّخَذُواْ مَسۡجِدٗا ضِرَارٗا وَكُفۡرٗا وَتَفۡرِيقَۢا بَيۡنَ ٱلۡمُؤۡمِنِينَ وَإِرۡصَادٗا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ وَلَيَحۡلِفُنَّ إِنۡ أَرَدۡنَآ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ ﴿١٠٧﴾ لَا تَقُمۡ فِيهِ أَبَدٗاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ ﴿١٠٨﴾ أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ أَم مَّنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٖ فَٱنۡهَارَ بِهِۦ فِي نَارِ جَهَنَّمَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٠٩﴾ لَا يَزَالُ بُنۡيَٰنُهُمُ ٱلَّذِي بَنَوۡاْ رِيبَةٗ فِي قُلُوبِهِمۡ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ ﴿١١٠﴾", "w": [["ضراراً", "مضارّة لأهل الإسلام بتفرقة المسلمين وإيجاد العداوات بينهم."], ["وإرصاداً", "انتظاراً وترقّباً."], ["إلا الحسنى", "إلا الخير والحال الأحسن."], ["لا تقم فيه أبداً", "لا تقم فيه للصلاة أبداً."], ["أُسّس على التقوى", "بُني على التقوى، وهو مسجد قباء."], ["فيه رجال", "هم بنو عمرو بن عوف."], ["على تقوى من الله", "على خوف منه."], ["ورضوان", "رجاء رضوان الله تعالى."], ["على شفا جرف هار", "على طرف جرف مشرف على السقوط، وهو مسجد الضرار."], ["ريبة في قلوبهم", "شكاً في نفوسهم."], ["إلا أن تقطّع قلوبهم", "تُفصل من صدورهم فيموتوا."]], "m": "ما زال السياق في فضح المنافقين: والذين اتخذوا مسجداً ضراراً وكفراً، اثنا عشر رجلاً من أهل المدينة أتوا النبي ﷺ وهو شاخص إلى تبوك فقالوا: بنينا مسجداً للعاجز والمريض والليلة المطيرة فصلّ لنا فيه، فقال: «إني على جناح سفر، وإن عدنا صلينا لكم فيه»، فلما عاد ونزل بذي أوان قرب المدينة نزل الوحي بشأنه، فبعث مالك بن الدخشم ومعن بن عدي فقال: «انطلقا إلى هذا المسجد الظالم أهله فاهدماه وحرّقاه»، ففعلا. بنوه ضراراً بمسجد قباء، وكفراً بالله ورسوله، وتفريقاً بين المؤمنين المجتمعين في قباء حتى يجدوا مجالاً للتشكيك، وإرصاداً لمن حارب الله ورسوله من قبل، وهو أبو عامر الراهب الفاسق الذي أمرهم ببنائه، وقال للنبي ﷺ: ما وجدت قوماً يقاتلونك إلا قاتلتك معهم، ثم ذهب إلى الروم يستعديهم فهلك. وليحلفنّ: إن أردنا إلا الحسنى، والله يشهد إنهم لكاذبون. لا تقم فيه أبداً، لمسجد أُسّس على التقوى من أول يوم، مسجده ﷺ ومسجد قباء، أحق أن تقوم فيه، فيه رجال يحبون أن يتطهّروا من الخبث الحسي والمعنوي، فكانوا يجمعون في الاستنجاء بين الحجارة والماء، والله يحب المطّهّرين. أفمن أسّس بنيانه على تقوى من الله ورضوان خير أم من أسّس بنيانه على شفا جرف هار فانهار به في نار جهنم؟ والله لا يهدي القوم الظالمين. لا يزال بنيانهم الذي بنوا ريبة في قلوبهم إلا أن تقطّع قلوبهم فيموتوا كافرين، والله عليم حكيم.", "h": ["بيان أكبر مؤامرة ضد الإسلام قام بها المنافقون بإرشاد الفاسق أبي عامر الراهب.", "بيان أن حب الشرف والسلطة سبب البلاء كل البلاء، فأبو عامر ترهّب لأجل الشرف على أهل المدينة، فلما فقده بالإسلام حارب من كان سبب حرمانه.", "لا يصح الاغترار بأقوال أهل النفاق، فإنها كذب كلها.", "أيّما مسجد بُني للإضرار والتفرقة بين المسلمين يجب هدمه، وتحرم الصلاة فيه.", "فضل التطهّر والمبالغة في الطهارتين الروحية والبدنية.", "التحذير من الظلم والإسراف فيه، فإنه يحرم صاحبه هداية الله فيهلك وهو ظالم فيخسر دنيا وأخرى."], "k": "«أفمن أسّس بنيانه على تقوى من الله ورضوان»… ما أبنيه اليوم من عمل أو بيت أو علاقة، على أي أساس أضعه؟"}, {"lbl": "الآيتان ١١١ – ١١٢", "q": "۞إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ فَيَقۡتُلُونَ وَيُقۡتَلُونَۖ وَعۡدًا عَلَيۡهِ حَقّٗا فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُواْ بِبَيۡعِكُمُ ٱلَّذِي بَايَعۡتُم بِهِۦۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١١١﴾ ٱلتَّـٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّـٰٓئِحُونَ ٱلرَّـٰكِعُونَ ٱلسَّـٰجِدُونَ ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ ﴿١١٢﴾", "w": [["الجنة", "دار السلام التي أعدّها الله تعالى للمتقين."], ["يقاتلون", "أي الكفار والمشركين."], ["وعداً", "وعدهم وعداً حقاً."], ["في التوراة", "مذكوراً في التوراة والإنجيل والقرآن."], ["ومن أوفى بعهده", "لا أحد أوفى بعهده من الله تعالى."], ["التائبون", "من الشرك والنفاق والمعاصي."], ["العابدون", "المطيعون لله في تذلّل وخشوع، مع حبهم لله وتعظيمهم له."], ["السائحون", "الصائمون، والخارجون في سبيل الله لطلب علم أو تعليمه أو جهاد لأعدائه."], ["الآمرون بالمعروف", "بعبادة الله تعالى وتوحيده فيها."], ["الناهون عن المنكر", "عن الشرك والمعاصي."], ["والحافظون لحدود الله", "القائمون عليها العاملون بها."], ["وبشّر المؤمنين", "أي بالجنة دار السلام."]], "m": "لما ذكر حال المتخلّفين ذكر فضل الجهاد ترغيباً فيه: إن الله اشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة، يقاتلون في سبيل الله أعداءه فيَقتلون ويُقتلون، وعداً عليه حقاً أثبته في التوراة والإنجيل والقرآن، ومن أوفى بعهده من الله؟ لا أحد، فاستبشروا ببيعكم الذي بايعتم به وافرحوا، وذلك هو الفوز العظيم. ثم ذكر أوصاف أهل البيع التسعة: التائبون من الشرك والمعاصي، العابدون المطيعون لله طاعة ملؤها المحبة والتعظيم والرهبة، الحامدون لله في السراء والضراء، السائحون: الصائمون كما في الحديث، والخارجون لطلب علم أو غزو أو تعليم أو دعوة، الراكعون الساجدون المقيمون الصلاة المكثرون من نوافلها كأنهم دائماً في ركوع وسجود، الآمرون بالمعروف من الإيمان والتوحيد والطاعة، والناهون عن المنكر من الكفر والشرك والمعصية، والحافظون لحدود الله بالقيام عليها وعملها بعد العلم بها، وبشّر المؤمنين أهل الإيمان الصادق بالنصر في الدنيا والجنة يوم القيامة.", "h": ["بيان فضل الله تعالى ومنّته على عباده المؤمنين، حيث وهبهم أرواحهم وأموالهم ثم اشتراها منهم بالجنة.", "فضل الجهاد والاستشهاد في سبيل الله.", "على المؤمن أن يُشعر نفسه أن بدنه وماله لله تعالى، وأن عليه رعايتهما وحفظهما، حتى إذا رُفعت راية الجهاد وطالب إمام المسلمين بالنفس والمال قدّمهما، إذ هما وديعة الله عنده.", "على المؤمن ألا يُدخل الضرر على نفسه ولا على ماله بحكم أنهما لله تعالى.", "على المؤمن أن يتعاهد نفسه ليرى هل هو متّصف بهذه الصفات التسع، فإن رأى نقصاً كمّله، وإن رأى كمالاً حمد الله عليه وحافظ عليه."], "k": "«التائبون العابدون الحامدون…»… أيّ الصفات التسع أنا فيها أضعف، فأبدأ بها اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (130, 9, 113, 123, 'سورة التوبة ١١٣ – ١٢٣', '«ما كان للنبي والذين آمنوا أن يستغفروا للمشركين»، توبة الثلاثة الذين خُلّفوا، و«فلولا نفر من كل فرقة منهم طائفة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 130) = $j$[{"lbl": "الآيات ١١٣ – ١١٦", "q": "مَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ أَن يَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿١١٣﴾ وَمَا كَانَ ٱسۡتِغۡفَارُ إِبۡرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوۡعِدَةٖ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوّٞ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَٰهِيمَ لَأَوَّـٰهٌ حَلِيمٞ ﴿١١٤﴾ وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ ﴿١١٥﴾ إِنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ ﴿١١٦﴾", "w": [["أن يستغفروا للمشركين", "يسألوا الله تعالى لهم المغفرة."], ["أولي قربى", "أصحاب قرابة كالأبوّة والبنوّة والأخوّة."], ["موعدة", "وعد وعده به."], ["تبرّأ منه", "قال: إني بريء منك."], ["أوّاه حليم", "الأوّاه: كثير الدعاء والشكوى إلى الله تعالى، والحليم: الذي لا يغضب ولا يؤاخذ بالذنب."], ["ما يتقون", "ما يتقون الله تعالى فيه فلا يفعلونه أو لا يتركونه."], ["من ولي", "الولي: من يتولّى أمرك فيحفظك ويعينك."]], "m": "لما مات أبو طالب على الشرك بعد أن عرض عليه الرسول ﷺ كلمة التوحيد فأبى، وقال: هو على ملة عبد المطلب، قال ﷺ: «لأستغفرنّ لك ما لم أُنه عنك»، واستغفر بعض المؤمنين لأقربائهم الذين ماتوا على الشرك، فأنزل الله: ما كان للنبي والذين آمنوا أن يستغفروا للمشركين ولو كانوا أولي قربى من بعد ما تبيّن لهم أنهم أصحاب الجحيم، إذ ماتوا على الشرك. ولما قال بعضهم: إن إبراهيم استغفر لأبيه وهو مشرك، قال تعالى: وما كان استغفار إبراهيم لأبيه إلا عن موعدة وعدها إياه في قوله: «سأستغفر لك ربي»، فلما تبيّن له أنه عدو لله، مات على الشرك، تبرّأ منه، إن إبراهيم لأوّاه كثير الدعاء والتضرّع والتحسّر، حليم، ولذا واعد أباه بالاستغفار. وتساءل الذين استغفروا لأقاربهم متندّمين، فأخبرهم: وما كان الله ليضلّ قوماً بعد إذ هداهم حتى يبيّن لهم ما يتقون، وأنتم استغفرتم قبل أن يُبيّن لكم أنه حرام، إن الله بكل شيء عليم، فلا يضل إلا من يستحق الضلال. إن الله له ملك السماوات والأرض، يحيي بالإيمان ويميت بالكفر، ويحيي الأموات ويميت الأحياء، وما لكم من دون الله من ولي يتولّاكم إذا تخلّى عنكم ولا نصير.", "h": ["حرمة الاستغفار لمن مات على الشرك، لأن الله لا يغفر أن يُشرك به، فلذا لا يُطلب منه ما لا يفعله.", "وجوب الوفاء بالوعود والعهود.", "ليس من سنة الله تعالى في الناس أن يضل عباده قبل أن يبيّن لهم ما يجب عليهم عمله أو اتقاؤه.", "ليس للعبد من دون الله من ولي يتولّاه ولا نصير ينصره، ولذا وجبت ولاية الله بطاعته واللجوء إليه بالتوكل عليه."], "k": "«إن إبراهيم لأوّاه حليم»… هل لي حظ من كثرة الدعاء والشكوى إلى الله، والحلم على الناس؟"}, {"lbl": "الآيات ١١٧ – ١١٩", "q": "لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٖ مِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفٞ رَّحِيمٞ ﴿١١٧﴾ وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ ﴿١١٨﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَكُونُواْ مَعَ ٱلصَّـٰدِقِينَ ﴿١١٩﴾", "w": [["المهاجرين", "الذين هجروا ديارهم من مكة وغيرها ولحقوا برسول الله ﷺ بالمدينة."], ["الأنصار", "سكان المدينة من الأوس والخزرج، آمنوا ونصروا رسول الله ﷺ."], ["ساعة العسرة", "أيام الخروج إلى تبوك لشدة الحر والجوع والعطش."], ["يزيغ قلوب", "تميل عن الحق لشدة الحال وصعوبة الموقف."], ["الثلاثة الذين خُلّفوا", "كعب بن مالك، ومرارة بن الربيع، وهلال بن أمية."], ["بما رحبت", "على اتساعها ورحابتها."], ["أن لا ملجأ", "لا مكان للّجوء فيه والهرب إليه."]], "m": "في هذه الآيات إعلان عن شرف الرسول ﷺ وأصحابه البررة: لقد تاب الله على النبي والمهاجرين والأنصار، أدامها وقبلها، الذين اتبعوه في ساعة العسرة عند خروجه إلى تبوك في الحر الشديد والفاقة، من بعد ما كاد يزيغ قلوب فريق منهم، فقد عطشوا يوماً، قال عمر: كان أحدنا يذبح بعيره ويعصر فرثه فيشرب ماءه ويضع بعضه على كبده، فخطرت ببعضهم خواطر كادت تميل بالقلوب، فثبّتهم الله فلم يقولوا سوءاً ولم يعملوه، ثم تاب عليهم إنه بهم رؤوف رحيم. وعلى الثلاثة الذين خُلّفوا، أُرجئت توبتهم خمسين يوماً، حتى إذا ضاقت عليهم الأرض بما رحبت، وضاقت عليهم أنفسهم، وظنّوا أن لا ملجأ من الله إلا إليه، فصبروا على ألم المقاطعة التي أعلنها رسول الله ﷺ، إذ لم يتقدّموا ليعتذروا كما فعل المخلّفون خوفاً من الكذب، فآثروا الصدق، ثم تاب عليهم ليتوبوا، وجعلهم مثلاً للصدق، فقال: يا أيها الذين آمنوا اتقوا الله وكونوا مع الصادقين في نياتهم وأقوالهم وأعمالهم، تكونوا مع الصادقين في الآخرة: مع النبي ﷺ وأبي بكر وعمر وسائر النبيين والصديقين والشهداء والصالحين.", "h": ["بيان فضل أصحاب رسول الله ﷺ.", "بيان فضل غزوة العسرة، وهي غزوة تبوك، على غيرها من الغزوات.", "بيان فضل الله على المؤمنين بعصمة قلوبهم من الزيغ في حال الشدة.", "بيان فضل كعب بن مالك وصاحبيه في صبرهم وصدقهم ولجوئهم إلى الله تعالى حتى فرّج عنهم وتاب عليهم، وكانوا مثالاً للصدق.", "وجوب التقوى والصدق في النيات والأقوال والأحوال والأعمال."], "k": "«وكونوا مع الصادقين»… لو كان الصدق سيكلّفني ما كلّف كعباً، فهل أختاره كما اختاره؟"}, {"lbl": "الآيات ١٢٠ – ١٢٢", "q": "مَا كَانَ لِأَهۡلِ ٱلۡمَدِينَةِ وَمَنۡ حَوۡلَهُم مِّنَ ٱلۡأَعۡرَابِ أَن يَتَخَلَّفُواْ عَن رَّسُولِ ٱللَّهِ وَلَا يَرۡغَبُواْ بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦۚ ذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأٞ وَلَا نَصَبٞ وَلَا مَخۡمَصَةٞ فِي سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوۡطِئٗا يَغِيظُ ٱلۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُوّٖ نَّيۡلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٞ صَٰلِحٌۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ﴿١٢٠﴾ وَلَا يُنفِقُونَ نَفَقَةٗ صَغِيرَةٗ وَلَا كَبِيرَةٗ وَلَا يَقۡطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمۡ لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٢١﴾ ۞وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةٗۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ ﴿١٢٢﴾", "w": [["ظمأ", "عطش."], ["ولا نصب", "ولا تعب."], ["ولا مخمصة", "ولا مجاعة شديدة."], ["يغيظ الكفار", "يصيبهم بغيظ في نفوسهم يحزنهم."], ["نيلاً", "منالاً من أسر أو قتل أو هزيمة للعدو."], ["وادياً", "الوادي: مسيل الماء بين جبلين أو مرتفعين."], ["لينفروا كافة", "يخرجوا للغزو والجهاد جميعاً."], ["طائفة", "جماعة معدودة."], ["ليتفقّهوا في الدين", "ليعلموا أحكام الدين وأسرار شرائعه."], ["ولينذروا قومهم", "ليخوّفوهم عذاب النار بترك العمل بشرع الله."], ["يحذرون", "عذاب الله تعالى بالعلم والعمل."]], "m": "ما زال السياق في آثار غزوة تبوك: ما كان لأهل المدينة من المهاجرين والأنصار، ومن حولهم من الأعراب كمزينة وجهينة وغفار وأشجع وأسلم، أن يتخلّفوا عن رسول الله إذا دعا بالنفير العام، عتاب شديد للمتخلّفين، ولا يرغبوا بأنفسهم عن نفسه فيطلبوا الراحة دونه، ذلك بأنهم لا يصيبهم ظمأ ولا نصب ولا مخمصة في سبيل الله، ولا يطؤون أرضاً من أرض العدو يغيظ الكفار، ولا ينالون من عدو نيلاً من أسر أو قتل أو هزيمة، إلا كُتب لهم به عمل صالح، إن الله لا يضيع أجر المحسنين، ولا ينفقون نفقة صغيرة ولا كبيرة، ولا يقطعون وادياً ذاهبين أو راجعين، إلا كُتب لهم ليجزيهم الله أحسن ما كانوا يعملون. ولما رأى المسلمون نتائج التخلّف قالوا: لن نتخلّف بعد اليوم عن غزو ما حيينا، فأرشدهم الله إلى الأمثل: وما كان المؤمنون لينفروا كافة، فلولا نفر من كل قبيلة طائفة، وبقيت طائفة مع رسول الله ﷺ يتفقّهون في الدين بصحبته، فإذا رجع الغزاة علّموهم ما فاتهم، كما يشاهد الغزاة ضعف الكفار وفساد قلوبهم فينذرون قومهم إذا رجعوا إليهم لعلهم يحذرون، وفي هذا خير للجميع.", "h": ["وجوب إيثار رسول الله ﷺ على النفس بكل خير، بل بالحياة كلها.", "بيان فضل السير في سبيل الله وما فيه من الأجر العظيم.", "فضل الإحسان وأهله.", "تساوي فضل طلب العلم والجهاد، على شرط النية الصالحة في الكل، فطالب العلم لا ينال هذا الأجر إلا إذا كان يتعلّم ليعمل ويعلّم مجاناً في سبيل الله، والمجاهد لا يناله إلا إذا كان لإعلاء كلمة الله خاصة.", "حاجة الأمة إلى الجهاد والمجاهدين كحاجتها إلى العلم والعلماء سواء بسواء."], "k": "«ليتفقّهوا في الدين ولينذروا قومهم»… ما الذي تعلّمته من ديني هذا الأسبوع، ولمن أوصلته؟"}, {"lbl": "الآية ١٢٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلۡكُفَّارِ وَلۡيَجِدُواْ فِيكُمۡ غِلۡظَةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ ﴿١٢٣﴾", "w": [["آمنوا", "بالله ورسوله ووعد الله ووعيده."], ["الذين يلونكم", "يلون بلادكم وحدودها."], ["من الكفار", "«مِن» بيانية، أي الكافرين."], ["وليجدوا فيكم غلظة", "قوة بأس وشدة مراس ليرهبوكم وينهزموا أمامكم."], ["مع المتقين", "بنصره وتأييده، والمتقون: الذين اتقوا الشرك والمعاصي، والخروج عن السنن الإلهية في النصر والهزيمة."]], "m": "لما طهُرت الجزيرة من الشرك وأصبحت دار إسلام في أخريات حياة الرسول ﷺ بعد تبوك، أمر الله المؤمنين أن يواصلوا الجهاد بعد وفاة نبيه، وأرشدهم إلى طريقته: أن يبدؤوا بأقرب كافر منهم، المتاخم لحدودهم كالأردن أو الشام أو العراق مثلاً، فيعسكروا على مقربة منه ويدعوه إلى إحدى ثلاث: الدخول في الإسلام، أو قبول حماية المسلمين بدفع الجزية مقابل حمايتهم وحكمهم بالعدل والرحمة، أو القتال حتى يحكم الله، فإذا ضُمّت أرضه وأصبحت لهم حدود أخرى فعلوا كذلك، حتى لا تكون فتنة ويكون الدين كله لله: يا أيها الذين آمنوا قاتلوا الذين يلونكم من الكفار، وليجدوا فيكم غلظة، قوة بأس وشدة مراس، واعلموا أن الله مع المتقين بنصره وتأييده، على شرط أن يتقوه في أمره ونهيه.", "h": ["وجوب الجهاد واستمراريته إلى ألا تبقى فتنة أو شرك أو اضطهاد لمؤمن، ويكون الدين والحكم كلاهما لله تعالى.", "مشروعية البداءة في الجهاد بأقرب الكفار إلى بلاد المسلمين، من باب: الأقربون أولى.", "إذا اتسعت بلاد الإسلام تعيّن على أهل كل ناحية قتال من يليهم، الأقرب فالأقرب.", "وعد الله بالنصر والتأييد لأهل التقوى العامة والخاصة."], "k": "«واعلموا أن الله مع المتقين»… معيّة الله مشروطة بالتقوى؛ فهل أستحقها في معاركي اليومية مع نفسي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 130;
insert into public.tdb_cards(topic, i, body) select 130, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١٣ – ١١٦", "q": "مَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ أَن يَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿١١٣﴾ وَمَا كَانَ ٱسۡتِغۡفَارُ إِبۡرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوۡعِدَةٖ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوّٞ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَٰهِيمَ لَأَوَّـٰهٌ حَلِيمٞ ﴿١١٤﴾ وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ ﴿١١٥﴾ إِنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ ﴿١١٦﴾", "w": [["أن يستغفروا للمشركين", "يسألوا الله تعالى لهم المغفرة."], ["أولي قربى", "أصحاب قرابة كالأبوّة والبنوّة والأخوّة."], ["موعدة", "وعد وعده به."], ["تبرّأ منه", "قال: إني بريء منك."], ["أوّاه حليم", "الأوّاه: كثير الدعاء والشكوى إلى الله تعالى، والحليم: الذي لا يغضب ولا يؤاخذ بالذنب."], ["ما يتقون", "ما يتقون الله تعالى فيه فلا يفعلونه أو لا يتركونه."], ["من ولي", "الولي: من يتولّى أمرك فيحفظك ويعينك."]], "m": "لما مات أبو طالب على الشرك بعد أن عرض عليه الرسول ﷺ كلمة التوحيد فأبى، وقال: هو على ملة عبد المطلب، قال ﷺ: «لأستغفرنّ لك ما لم أُنه عنك»، واستغفر بعض المؤمنين لأقربائهم الذين ماتوا على الشرك، فأنزل الله: ما كان للنبي والذين آمنوا أن يستغفروا للمشركين ولو كانوا أولي قربى من بعد ما تبيّن لهم أنهم أصحاب الجحيم، إذ ماتوا على الشرك. ولما قال بعضهم: إن إبراهيم استغفر لأبيه وهو مشرك، قال تعالى: وما كان استغفار إبراهيم لأبيه إلا عن موعدة وعدها إياه في قوله: «سأستغفر لك ربي»، فلما تبيّن له أنه عدو لله، مات على الشرك، تبرّأ منه، إن إبراهيم لأوّاه كثير الدعاء والتضرّع والتحسّر، حليم، ولذا واعد أباه بالاستغفار. وتساءل الذين استغفروا لأقاربهم متندّمين، فأخبرهم: وما كان الله ليضلّ قوماً بعد إذ هداهم حتى يبيّن لهم ما يتقون، وأنتم استغفرتم قبل أن يُبيّن لكم أنه حرام، إن الله بكل شيء عليم، فلا يضل إلا من يستحق الضلال. إن الله له ملك السماوات والأرض، يحيي بالإيمان ويميت بالكفر، ويحيي الأموات ويميت الأحياء، وما لكم من دون الله من ولي يتولّاكم إذا تخلّى عنكم ولا نصير.", "h": ["حرمة الاستغفار لمن مات على الشرك، لأن الله لا يغفر أن يُشرك به، فلذا لا يُطلب منه ما لا يفعله.", "وجوب الوفاء بالوعود والعهود.", "ليس من سنة الله تعالى في الناس أن يضل عباده قبل أن يبيّن لهم ما يجب عليهم عمله أو اتقاؤه.", "ليس للعبد من دون الله من ولي يتولّاه ولا نصير ينصره، ولذا وجبت ولاية الله بطاعته واللجوء إليه بالتوكل عليه."], "k": "«إن إبراهيم لأوّاه حليم»… هل لي حظ من كثرة الدعاء والشكوى إلى الله، والحلم على الناس؟"}, {"lbl": "الآيات ١١٧ – ١١٩", "q": "لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٖ مِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفٞ رَّحِيمٞ ﴿١١٧﴾ وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ ﴿١١٨﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَكُونُواْ مَعَ ٱلصَّـٰدِقِينَ ﴿١١٩﴾", "w": [["المهاجرين", "الذين هجروا ديارهم من مكة وغيرها ولحقوا برسول الله ﷺ بالمدينة."], ["الأنصار", "سكان المدينة من الأوس والخزرج، آمنوا ونصروا رسول الله ﷺ."], ["ساعة العسرة", "أيام الخروج إلى تبوك لشدة الحر والجوع والعطش."], ["يزيغ قلوب", "تميل عن الحق لشدة الحال وصعوبة الموقف."], ["الثلاثة الذين خُلّفوا", "كعب بن مالك، ومرارة بن الربيع، وهلال بن أمية."], ["بما رحبت", "على اتساعها ورحابتها."], ["أن لا ملجأ", "لا مكان للّجوء فيه والهرب إليه."]], "m": "في هذه الآيات إعلان عن شرف الرسول ﷺ وأصحابه البررة: لقد تاب الله على النبي والمهاجرين والأنصار، أدامها وقبلها، الذين اتبعوه في ساعة العسرة عند خروجه إلى تبوك في الحر الشديد والفاقة، من بعد ما كاد يزيغ قلوب فريق منهم، فقد عطشوا يوماً، قال عمر: كان أحدنا يذبح بعيره ويعصر فرثه فيشرب ماءه ويضع بعضه على كبده، فخطرت ببعضهم خواطر كادت تميل بالقلوب، فثبّتهم الله فلم يقولوا سوءاً ولم يعملوه، ثم تاب عليهم إنه بهم رؤوف رحيم. وعلى الثلاثة الذين خُلّفوا، أُرجئت توبتهم خمسين يوماً، حتى إذا ضاقت عليهم الأرض بما رحبت، وضاقت عليهم أنفسهم، وظنّوا أن لا ملجأ من الله إلا إليه، فصبروا على ألم المقاطعة التي أعلنها رسول الله ﷺ، إذ لم يتقدّموا ليعتذروا كما فعل المخلّفون خوفاً من الكذب، فآثروا الصدق، ثم تاب عليهم ليتوبوا، وجعلهم مثلاً للصدق، فقال: يا أيها الذين آمنوا اتقوا الله وكونوا مع الصادقين في نياتهم وأقوالهم وأعمالهم، تكونوا مع الصادقين في الآخرة: مع النبي ﷺ وأبي بكر وعمر وسائر النبيين والصديقين والشهداء والصالحين.", "h": ["بيان فضل أصحاب رسول الله ﷺ.", "بيان فضل غزوة العسرة، وهي غزوة تبوك، على غيرها من الغزوات.", "بيان فضل الله على المؤمنين بعصمة قلوبهم من الزيغ في حال الشدة.", "بيان فضل كعب بن مالك وصاحبيه في صبرهم وصدقهم ولجوئهم إلى الله تعالى حتى فرّج عنهم وتاب عليهم، وكانوا مثالاً للصدق.", "وجوب التقوى والصدق في النيات والأقوال والأحوال والأعمال."], "k": "«وكونوا مع الصادقين»… لو كان الصدق سيكلّفني ما كلّف كعباً، فهل أختاره كما اختاره؟"}, {"lbl": "الآيات ١٢٠ – ١٢٢", "q": "مَا كَانَ لِأَهۡلِ ٱلۡمَدِينَةِ وَمَنۡ حَوۡلَهُم مِّنَ ٱلۡأَعۡرَابِ أَن يَتَخَلَّفُواْ عَن رَّسُولِ ٱللَّهِ وَلَا يَرۡغَبُواْ بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦۚ ذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأٞ وَلَا نَصَبٞ وَلَا مَخۡمَصَةٞ فِي سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوۡطِئٗا يَغِيظُ ٱلۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُوّٖ نَّيۡلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٞ صَٰلِحٌۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ﴿١٢٠﴾ وَلَا يُنفِقُونَ نَفَقَةٗ صَغِيرَةٗ وَلَا كَبِيرَةٗ وَلَا يَقۡطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمۡ لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٢١﴾ ۞وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةٗۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ ﴿١٢٢﴾", "w": [["ظمأ", "عطش."], ["ولا نصب", "ولا تعب."], ["ولا مخمصة", "ولا مجاعة شديدة."], ["يغيظ الكفار", "يصيبهم بغيظ في نفوسهم يحزنهم."], ["نيلاً", "منالاً من أسر أو قتل أو هزيمة للعدو."], ["وادياً", "الوادي: مسيل الماء بين جبلين أو مرتفعين."], ["لينفروا كافة", "يخرجوا للغزو والجهاد جميعاً."], ["طائفة", "جماعة معدودة."], ["ليتفقّهوا في الدين", "ليعلموا أحكام الدين وأسرار شرائعه."], ["ولينذروا قومهم", "ليخوّفوهم عذاب النار بترك العمل بشرع الله."], ["يحذرون", "عذاب الله تعالى بالعلم والعمل."]], "m": "ما زال السياق في آثار غزوة تبوك: ما كان لأهل المدينة من المهاجرين والأنصار، ومن حولهم من الأعراب كمزينة وجهينة وغفار وأشجع وأسلم، أن يتخلّفوا عن رسول الله إذا دعا بالنفير العام، عتاب شديد للمتخلّفين، ولا يرغبوا بأنفسهم عن نفسه فيطلبوا الراحة دونه، ذلك بأنهم لا يصيبهم ظمأ ولا نصب ولا مخمصة في سبيل الله، ولا يطؤون أرضاً من أرض العدو يغيظ الكفار، ولا ينالون من عدو نيلاً من أسر أو قتل أو هزيمة، إلا كُتب لهم به عمل صالح، إن الله لا يضيع أجر المحسنين، ولا ينفقون نفقة صغيرة ولا كبيرة، ولا يقطعون وادياً ذاهبين أو راجعين، إلا كُتب لهم ليجزيهم الله أحسن ما كانوا يعملون. ولما رأى المسلمون نتائج التخلّف قالوا: لن نتخلّف بعد اليوم عن غزو ما حيينا، فأرشدهم الله إلى الأمثل: وما كان المؤمنون لينفروا كافة، فلولا نفر من كل قبيلة طائفة، وبقيت طائفة مع رسول الله ﷺ يتفقّهون في الدين بصحبته، فإذا رجع الغزاة علّموهم ما فاتهم، كما يشاهد الغزاة ضعف الكفار وفساد قلوبهم فينذرون قومهم إذا رجعوا إليهم لعلهم يحذرون، وفي هذا خير للجميع.", "h": ["وجوب إيثار رسول الله ﷺ على النفس بكل خير، بل بالحياة كلها.", "بيان فضل السير في سبيل الله وما فيه من الأجر العظيم.", "فضل الإحسان وأهله.", "تساوي فضل طلب العلم والجهاد، على شرط النية الصالحة في الكل، فطالب العلم لا ينال هذا الأجر إلا إذا كان يتعلّم ليعمل ويعلّم مجاناً في سبيل الله، والمجاهد لا يناله إلا إذا كان لإعلاء كلمة الله خاصة.", "حاجة الأمة إلى الجهاد والمجاهدين كحاجتها إلى العلم والعلماء سواء بسواء."], "k": "«ليتفقّهوا في الدين ولينذروا قومهم»… ما الذي تعلّمته من ديني هذا الأسبوع، ولمن أوصلته؟"}, {"lbl": "الآية ١٢٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلۡكُفَّارِ وَلۡيَجِدُواْ فِيكُمۡ غِلۡظَةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ ﴿١٢٣﴾", "w": [["آمنوا", "بالله ورسوله ووعد الله ووعيده."], ["الذين يلونكم", "يلون بلادكم وحدودها."], ["من الكفار", "«مِن» بيانية، أي الكافرين."], ["وليجدوا فيكم غلظة", "قوة بأس وشدة مراس ليرهبوكم وينهزموا أمامكم."], ["مع المتقين", "بنصره وتأييده، والمتقون: الذين اتقوا الشرك والمعاصي، والخروج عن السنن الإلهية في النصر والهزيمة."]], "m": "لما طهُرت الجزيرة من الشرك وأصبحت دار إسلام في أخريات حياة الرسول ﷺ بعد تبوك، أمر الله المؤمنين أن يواصلوا الجهاد بعد وفاة نبيه، وأرشدهم إلى طريقته: أن يبدؤوا بأقرب كافر منهم، المتاخم لحدودهم كالأردن أو الشام أو العراق مثلاً، فيعسكروا على مقربة منه ويدعوه إلى إحدى ثلاث: الدخول في الإسلام، أو قبول حماية المسلمين بدفع الجزية مقابل حمايتهم وحكمهم بالعدل والرحمة، أو القتال حتى يحكم الله، فإذا ضُمّت أرضه وأصبحت لهم حدود أخرى فعلوا كذلك، حتى لا تكون فتنة ويكون الدين كله لله: يا أيها الذين آمنوا قاتلوا الذين يلونكم من الكفار، وليجدوا فيكم غلظة، قوة بأس وشدة مراس، واعلموا أن الله مع المتقين بنصره وتأييده، على شرط أن يتقوه في أمره ونهيه.", "h": ["وجوب الجهاد واستمراريته إلى ألا تبقى فتنة أو شرك أو اضطهاد لمؤمن، ويكون الدين والحكم كلاهما لله تعالى.", "مشروعية البداءة في الجهاد بأقرب الكفار إلى بلاد المسلمين، من باب: الأقربون أولى.", "إذا اتسعت بلاد الإسلام تعيّن على أهل كل ناحية قتال من يليهم، الأقرب فالأقرب.", "وعد الله بالنصر والتأييد لأهل التقوى العامة والخاصة."], "k": "«واعلموا أن الله مع المتقين»… معيّة الله مشروطة بالتقوى؛ فهل أستحقها في معاركي اليومية مع نفسي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (131, 9, 124, 129, 'سورة التوبة ١٢٤ – ١٢٩', '«فأما الذين آمنوا فزادتهم إيماناً»، و«لقد جاءكم رسول من أنفسكم… حسبي الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 131) = $j$[{"lbl": "الآيات ١٢٤ – ١٢٧", "q": "وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ فَمِنۡهُم مَّن يَقُولُ أَيُّكُمۡ زَادَتۡهُ هَٰذِهِۦٓ إِيمَٰنٗاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَزَادَتۡهُمۡ إِيمَٰنٗا وَهُمۡ يَسۡتَبۡشِرُونَ ﴿١٢٤﴾ وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ وَمَاتُواْ وَهُمۡ كَٰفِرُونَ ﴿١٢٥﴾ أَوَلَا يَرَوۡنَ أَنَّهُمۡ يُفۡتَنُونَ فِي كُلِّ عَامٖ مَّرَّةً أَوۡ مَرَّتَيۡنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمۡ يَذَّكَّرُونَ ﴿١٢٦﴾ وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ يَرَىٰكُم مِّنۡ أَحَدٖ ثُمَّ ٱنصَرَفُواْۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ﴿١٢٧﴾", "w": [["سورة", "قطعة من القرآن، سواء كانت آيات من سورة أو سورة بكاملها."], ["زادته إيماناً", "قوّت إيمانه وزادت فيه، لأنها كالغيث النافع."], ["يستبشرون", "فرحين بفضل الله تعالى عليهم."], ["في قلوبهم مرض", "شك ونفاق وشرك."], ["فزادتهم رجساً", "نجساً إلى نجس قلوبهم ونفوسهم."], ["يُفتنون", "يُمتحنون."], ["ولا هم يذّكّرون", "لا يتّعظون لموت قلوبهم."], ["صرف الله قلوبهم", "دعاء عليهم بألّا يرجعوا إلى الحق بعد انصرافهم عنه."], ["لا يفقهون", "لا يفهمون أسرار الخطاب لظلمة قلوبهم وخبث نفوسهم."]], "m": "وإذا ما أُنزلت سورة فمن المنافقين من يقول تهكّماً وازدراءً: أيّكم زادته هذه إيماناً؟ فأما الذين آمنوا بحق وصدق فزادتهم إيماناً، لأنها نزلت بأحكام أو أخبار لم تكن عندهم فآمنوا بها، وقوي يقينهم، وهم يستبشرون فرحين بما نزل وبإيمانهم. وأما الذين في قلوبهم مرض، شك ونفاق، فزادتهم رجساً إلى رجسهم، شكاً إلى شكّهم ونفاقاً إلى نفاقهم، وماتوا وهم كافرون. أوَلا يرون أنهم يُفتنون في كل عام مرة أو مرتين، يُختبرون بالتكاليف والفضائح، ثم لا يتوبون ولا هم يذّكّرون؟ وإذا ما أُنزلت سورة وهم في المجلس نظر بعضهم إلى بعض، وقالوا في سرّية: هيّا نقوم من هذا المجلس الذي نُعيّر فيه، هل يراكم من أحد من أصحاب محمد؟ فإن لم يرهم أحد انصرفوا متسلّلين، صرف الله قلوبهم عن الهدى، بأنهم قوم لا يفقهون أسرار الآيات، وعلّة ذلك ظلمة قلوبهم بالشك والشرك والنفاق.", "h": ["تقرير مبدأ زيادة الإيمان ونقصانه، زيادته بالطاعة ونقصانه بالعصيان.", "جواز الفرح بالإيمان وصالح الأعمال.", "مريض القلب يزداد مرضاً، وصحيحه يزداد صحة، سنة من سنن الله في العباد.", "كشف أغوار المنافقين وفضيحتهم في آخر آية من سورة التوبة تتحدّث عنهم.", "يُستحب ألا يقال: انصرفنا من الصلاة أو الدرس، ولكن يقال: انقضت الصلاة أو الدرس."], "k": "«فأما الذين آمنوا فزادتهم إيماناً»… هل تزيدني الآية حين أسمعها، أم تمرّ على قلبي كما جاءت؟"}, {"lbl": "الآيتان ١٢٨ – ١٢٩", "q": "لَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ رَءُوفٞ رَّحِيمٞ ﴿١٢٨﴾ فَإِن تَوَلَّوۡاْ فَقُلۡ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴿١٢٩﴾", "w": [["من أنفسكم", "من جنسكم، عربي قرشي هاشمي، تعرفون نسبه وصدقه وأمانته."], ["عزيز عليه", "شاقّ صعب."], ["ما عنتّم", "ما يشقّ ويصعب تحمّله."], ["حريص عليكم", "على هدايتكم وما فيه خيركم وسعادتكم."], ["رؤوف", "شفيق."], ["رحيم", "يرقّ ويعطف ويرحم."], ["فإن تولّوا", "أعرضوا عن دين الله وما جئت به من الهدى."], ["حسبي الله", "كافيّ الله."], ["لا إله إلا هو", "لا معبود بحق إلا هو."], ["توكلت", "فوّضت أمري إليه واعتمدت عليه."], ["رب العرش العظيم", "عرش الله تعالى لا أعظم منه إلا خالقه، إذ كرسيّه وسع السماوات والأرض، ونسبة الكرسي إلى العرش كحلقة ملقاة في فلاة."]], "m": "لقد جاءكم أيها العرب، والبشرية عامة، رسول عظيم من أنفسكم، عدناني قرشي هاشمي تعرفون نسبه وصدقه وأمانته، عزيز عليه ما عنتّم، يشقّ عليه ما يشقّ عليكم ويؤلمه ما يؤلمكم لأنه منكم، حريص على هدايتكم وإكمالكم وإسعادكم، بالمؤمنين منكم ومن سائر الناس رؤوف رحيم، شفوق عطوف يحب رحمتهم وإيصال الخير لهم، فآمنوا به واتبعوا النور الذي جاء به تهتدوا وتسعدوا. فإن تولّوا وأعرضوا عن دعوتك فلا تأسَ، وقل: حسبي الله يكفيني كل ما يهمّني، لا إله إلا هو، فإني أعبده وأدعو إلى عبادته، عليه توكّلت في شأني كله، وهو رب العرش العظيم، ما شاء كان وما لم يشأ لم يكن.", "h": ["بيان منّة الله تعالى على العرب خاصة، وعلى البشرية عامة، ببعثه خاتم أنبيائه محمد ﷺ.", "بيان كمال أخلاقه ﷺ.", "وجوب التوكل على الله تعالى والاعتماد عليه في كل شيء يقوم به العبد.", "عظمة عرش الرحمن عز وجل."], "k": "«حريص عليكم بالمؤمنين رؤوف رحيم»… نبي يحرص عليّ هذا الحرص؛ فبماذا أقابل حرصه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 131;
insert into public.tdb_cards(topic, i, body) select 131, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢٤ – ١٢٧", "q": "وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ فَمِنۡهُم مَّن يَقُولُ أَيُّكُمۡ زَادَتۡهُ هَٰذِهِۦٓ إِيمَٰنٗاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَزَادَتۡهُمۡ إِيمَٰنٗا وَهُمۡ يَسۡتَبۡشِرُونَ ﴿١٢٤﴾ وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ وَمَاتُواْ وَهُمۡ كَٰفِرُونَ ﴿١٢٥﴾ أَوَلَا يَرَوۡنَ أَنَّهُمۡ يُفۡتَنُونَ فِي كُلِّ عَامٖ مَّرَّةً أَوۡ مَرَّتَيۡنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمۡ يَذَّكَّرُونَ ﴿١٢٦﴾ وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ يَرَىٰكُم مِّنۡ أَحَدٖ ثُمَّ ٱنصَرَفُواْۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ﴿١٢٧﴾", "w": [["سورة", "قطعة من القرآن، سواء كانت آيات من سورة أو سورة بكاملها."], ["زادته إيماناً", "قوّت إيمانه وزادت فيه، لأنها كالغيث النافع."], ["يستبشرون", "فرحين بفضل الله تعالى عليهم."], ["في قلوبهم مرض", "شك ونفاق وشرك."], ["فزادتهم رجساً", "نجساً إلى نجس قلوبهم ونفوسهم."], ["يُفتنون", "يُمتحنون."], ["ولا هم يذّكّرون", "لا يتّعظون لموت قلوبهم."], ["صرف الله قلوبهم", "دعاء عليهم بألّا يرجعوا إلى الحق بعد انصرافهم عنه."], ["لا يفقهون", "لا يفهمون أسرار الخطاب لظلمة قلوبهم وخبث نفوسهم."]], "m": "وإذا ما أُنزلت سورة فمن المنافقين من يقول تهكّماً وازدراءً: أيّكم زادته هذه إيماناً؟ فأما الذين آمنوا بحق وصدق فزادتهم إيماناً، لأنها نزلت بأحكام أو أخبار لم تكن عندهم فآمنوا بها، وقوي يقينهم، وهم يستبشرون فرحين بما نزل وبإيمانهم. وأما الذين في قلوبهم مرض، شك ونفاق، فزادتهم رجساً إلى رجسهم، شكاً إلى شكّهم ونفاقاً إلى نفاقهم، وماتوا وهم كافرون. أوَلا يرون أنهم يُفتنون في كل عام مرة أو مرتين، يُختبرون بالتكاليف والفضائح، ثم لا يتوبون ولا هم يذّكّرون؟ وإذا ما أُنزلت سورة وهم في المجلس نظر بعضهم إلى بعض، وقالوا في سرّية: هيّا نقوم من هذا المجلس الذي نُعيّر فيه، هل يراكم من أحد من أصحاب محمد؟ فإن لم يرهم أحد انصرفوا متسلّلين، صرف الله قلوبهم عن الهدى، بأنهم قوم لا يفقهون أسرار الآيات، وعلّة ذلك ظلمة قلوبهم بالشك والشرك والنفاق.", "h": ["تقرير مبدأ زيادة الإيمان ونقصانه، زيادته بالطاعة ونقصانه بالعصيان.", "جواز الفرح بالإيمان وصالح الأعمال.", "مريض القلب يزداد مرضاً، وصحيحه يزداد صحة، سنة من سنن الله في العباد.", "كشف أغوار المنافقين وفضيحتهم في آخر آية من سورة التوبة تتحدّث عنهم.", "يُستحب ألا يقال: انصرفنا من الصلاة أو الدرس، ولكن يقال: انقضت الصلاة أو الدرس."], "k": "«فأما الذين آمنوا فزادتهم إيماناً»… هل تزيدني الآية حين أسمعها، أم تمرّ على قلبي كما جاءت؟"}, {"lbl": "الآيتان ١٢٨ – ١٢٩", "q": "لَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ رَءُوفٞ رَّحِيمٞ ﴿١٢٨﴾ فَإِن تَوَلَّوۡاْ فَقُلۡ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴿١٢٩﴾", "w": [["من أنفسكم", "من جنسكم، عربي قرشي هاشمي، تعرفون نسبه وصدقه وأمانته."], ["عزيز عليه", "شاقّ صعب."], ["ما عنتّم", "ما يشقّ ويصعب تحمّله."], ["حريص عليكم", "على هدايتكم وما فيه خيركم وسعادتكم."], ["رؤوف", "شفيق."], ["رحيم", "يرقّ ويعطف ويرحم."], ["فإن تولّوا", "أعرضوا عن دين الله وما جئت به من الهدى."], ["حسبي الله", "كافيّ الله."], ["لا إله إلا هو", "لا معبود بحق إلا هو."], ["توكلت", "فوّضت أمري إليه واعتمدت عليه."], ["رب العرش العظيم", "عرش الله تعالى لا أعظم منه إلا خالقه، إذ كرسيّه وسع السماوات والأرض، ونسبة الكرسي إلى العرش كحلقة ملقاة في فلاة."]], "m": "لقد جاءكم أيها العرب، والبشرية عامة، رسول عظيم من أنفسكم، عدناني قرشي هاشمي تعرفون نسبه وصدقه وأمانته، عزيز عليه ما عنتّم، يشقّ عليه ما يشقّ عليكم ويؤلمه ما يؤلمكم لأنه منكم، حريص على هدايتكم وإكمالكم وإسعادكم، بالمؤمنين منكم ومن سائر الناس رؤوف رحيم، شفوق عطوف يحب رحمتهم وإيصال الخير لهم، فآمنوا به واتبعوا النور الذي جاء به تهتدوا وتسعدوا. فإن تولّوا وأعرضوا عن دعوتك فلا تأسَ، وقل: حسبي الله يكفيني كل ما يهمّني، لا إله إلا هو، فإني أعبده وأدعو إلى عبادته، عليه توكّلت في شأني كله، وهو رب العرش العظيم، ما شاء كان وما لم يشأ لم يكن.", "h": ["بيان منّة الله تعالى على العرب خاصة، وعلى البشرية عامة، ببعثه خاتم أنبيائه محمد ﷺ.", "بيان كمال أخلاقه ﷺ.", "وجوب التوكل على الله تعالى والاعتماد عليه في كل شيء يقوم به العبد.", "عظمة عرش الرحمن عز وجل."], "k": "«حريص عليكم بالمؤمنين رؤوف رحيم»… نبي يحرص عليّ هذا الحرص؛ فبماذا أقابل حرصه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (132, 10, 1, 10, 'سورة يونس ١ – ١٠', '«أكان للناس عجباً أن أوحينا إلى رجل منهم»، و«دعواهم فيها سبحانك اللهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 132) = $j$[{"lbl": "الآيتان ١ – ٢", "q": "الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ ﴿١﴾ أَكَانَ لِلنَّاسِ عَجَبًا أَنۡ أَوۡحَيۡنَآ إِلَىٰ رَجُلٖ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓاْ أَنَّ لَهُمۡ قَدَمَ صِدۡقٍ عِندَ رَبِّهِمۡۗ قَالَ ٱلۡكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٞ مُّبِينٌ ﴿٢﴾", "w": [["الر", "هذه السورة الرابعة من السور المفتتحة بالحروف المقطعة، تُكتب: الر، وتُقرأ: ألف لام را."], ["الكتاب", "القرآن العظيم."], ["الحكيم", "القائل بالحكمة، والقرآن مشتمل على الحِكَم، فهو حكيم ومحكم أيضاً."], ["عجباً", "العجب: ما يُتعجّب منه."], ["قدم صدق", "أجراً حسناً بما قدّموا في حياتهم من الإيمان وصالح الأعمال."], ["إن هذا", "أي القرآن."], ["لسحر مبين", "بيّن ظاهر لا خفاء فيه، في كذبهم وادّعائهم الباطل."]], "m": "السورة مكية، تُعنى بقضية الوحي وإثباته: الر، تلك آيات الكتاب الحكيم، القرآن المحكم آياته المشتمل على الحكم الكثيرة حتى لكأنه الحكيم الذي يضع كل شيء في موضعه. أكان للناس من أهل مكة عجباً أن أوحينا إلى رجل منهم، محمد عبدنا ورسولنا من قريش، أن أنذر الناس عاقبة الشرك والكفر والعصيان، وبشّر الذين آمنوا أن لهم قدم صدق عند ربهم، الجزاء الحسن لما قدّموا من الإيمان وصالح الأعمال يتلقّونه يوم يلقونه؟ فلما أنذر وبشّر ﷺ قال الكافرون: إن هذا لساحر مبين، لمجرد دفع الحق وعدم قبوله، وإنما هي المجاحدة والعناد والمكابرة.", "h": ["تقرير عقيدة الوحي بشهادة الكتاب الموحى به.", "إثبات نبوة محمد ﷺ وتقريرها بالوحي إليه.", "بيان مهمة الرسول ﷺ، وهي النذارة والبشارة.", "بشرى أهل الإيمان والعمل الصالح بما أُعدّ لهم عند ربهم."], "k": "«أن لهم قدم صدق عند ربهم»… ماذا قدّمت اليوم ليكون لي قدم صدق هناك؟"}, {"lbl": "الآيات ٣ – ٦", "q": "إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُدَبِّرُ ٱلۡأَمۡرَۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا تَذَكَّرُونَ ﴿٣﴾ إِلَيۡهِ مَرۡجِعُكُمۡ جَمِيعٗاۖ وَعۡدَ ٱللَّهِ حَقًّاۚ إِنَّهُۥ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ بِٱلۡقِسۡطِۚ وَٱلَّذِينَ كَفَرُواْ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ ﴿٤﴾ هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ﴿٥﴾ إِنَّ فِي ٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَّقُونَ ﴿٦﴾", "w": [["إن ربكم الله", "معبودكم الحق الذي يجب أن تعبدوه وحده هو الله."], ["خلق السماوات والأرض", "أوجدها من العدم حيث كانت عدماً."], ["في ستة أيام", "هي الأحد والاثنين والثلاثاء والأربعاء والخميس والجمعة."], ["ما من شفيع إلا من بعد إذنه", "لا يشفع أحد يوم القيامة إلا من بعد أن يأذن له."], ["أفلا تذكّرون", "أتستمرّون في جحودكم وعنادكم فلا تذكّرون؟"], ["ثم يعيده", "بعد الفناء والبلى، وذلك يوم القيامة."], ["شراب من حميم", "من ماء أُحمي عليه وغلى حتى أصبح حميماً يشوي الوجوه."], ["جعل الشمس ضياء", "جعلها تضيء على الأرض."], ["والقمر نوراً", "جعل القمر ينير الأرض."], ["وقدّره منازل", "قدّر القمر منازل، والشمس كذلك."], ["لتعلموا", "قدّرهما منازل ليعلم الناس عدد السنين والحساب."], ["يتقون", "مساخط الله وعذابه، وذلك بطاعته وطاعة رسوله."]], "m": "هذه الآيات في تقرير الألوهية بعد تقرير الوحي: إن ربكم الله الذي خلق السماوات والأرض في ستة أيام بمقدار أيامنا هذه، ثم استوى على العرش استواء يليق بجلاله، يدبّر الأمر، هذا الإله الحق لا الأصنام التي لم تخلق شيئاً، ما من شفيع إلا من بعد إذنه لعظمته، فكيف تُعبد الأصنام رجاء شفاعتها؟ ذلكم الله ربكم فاعبدوه، أفلا تذكّرون؟ إليه مرجعكم جميعاً بعد الموت، وعد الله حقاً، إنه يبدأ الخلق ثم يعيده، ليجزي الذين آمنوا وعملوا الصالحات بالقسط والعدل، فهذه الدار دار عمل والآخرة دار جزاء، والقادر على البدء قادر على الإعادة، والذين كفروا لهم شراب من حميم وعذاب أليم بما كانوا يكفرون، وبهذا تقرّر مبدأ البعث بعد مبدأي التوحيد والوحي، إذ عليها تدور السور المكية. هو الذي جعل الشمس ضياء والقمر نوراً وقدّره منازل لتعلموا عدد السنين والحساب، إذ حياتكم تحتاج إلى ذلك، ما خلق الله ذلك إلا بالحق، لا عبثاً، ليأمر وينهى ثم يجزي، يفصّل الآيات لقوم يعلمون. إن في اختلاف الليل والنهار بالطول والقصر والضياء والظلام، وما خلق الله في السماوات والأرض من أفلاك وكواكب ورياح وأمطار، وإنسان وحيوان وبحار وأنهار وجبال، لآيات دالة على الخالق المعبود بحق، فيُعبد بحبه غاية الحب وتعظيمه غاية التعظيم، لقوم يتقون، إذ هم الذين يبصرونها لصفاء أرواحهم.", "h": ["تقرير ألوهية الله تعالى، وأنه الإله الحق.", "تقرير عقيدة البعث والجزاء في الدار الآخرة.", "بيان الحكمة في خلق الشمس والقمر وتقدير منازلهما.", "مشروعية تعلّم الحساب وعلم الفلك لما هو نافع للمسلمين."], "k": "«إن في اختلاف الليل والنهار… لآيات لقوم يتقون»… متى تأمّلت آخر مرة غروباً أو قمراً فذكرت ربي؟"}, {"lbl": "الآيات ٧ – ١٠", "q": "إِنَّ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا وَرَضُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَٱطۡمَأَنُّواْ بِهَا وَٱلَّذِينَ هُمۡ عَنۡ ءَايَٰتِنَا غَٰفِلُونَ ﴿٧﴾ أُوْلَـٰٓئِكَ مَأۡوَىٰهُمُ ٱلنَّارُ بِمَا كَانُواْ يَكۡسِبُونَ ﴿٨﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ فِي جَنَّـٰتِ ٱلنَّعِيمِ ﴿٩﴾ دَعۡوَىٰهُمۡ فِيهَا سُبۡحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمۡ فِيهَا سَلَٰمٞۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٠﴾", "w": [["لا يرجون لقاءنا", "لا ينتظرون ولا يؤمّلون لقاء الله تعالى يوم القيامة."], ["ورضوا بالحياة الدنيا", "بدلاً عن الآخرة، فلم يفكّروا في الدار الآخرة."], ["واطمأنّوا بها", "سكنوا إليها وركنوا، فلم يروا غيرها حياة يُعمل لها."], ["غافلون", "لا ينظرون إليها ولا يفكّرون فيها."], ["مأواهم النار", "النار هي المأوى الذي يأوون إليه، وليس لهم سواها."], ["يهديهم ربهم بإيمانهم", "يجعل لهم بإيمانهم نوراً يهتدون به إلى الجنة."], ["دعواهم فيها سبحانك اللهم", "يطلبون ما شاؤوا بكلمة: سبحانك اللهم."], ["وآخر دعواهم أن الحمد لله", "آخر دعائهم: الحمد لله رب العالمين."]], "m": "بعد تقرير الوحي والألوهية ذكر الجزاء: إن الذين لا يرجون لقاءنا، ورضوا بالحياة الدنيا بدلاً من الآخرة، واطمأنّوا بها فلم يروا غيرها حياة يُعمل لها، والذين هم عن آياتنا غافلون لا ينظرون فيها، أولئك مأواهم النار بما كانوا يكسبون من الشرك والمعاصي. إن الذين آمنوا وعملوا الصالحات يهديهم ربهم بإيمانهم، فيجعل لهم نوراً يهتدون به إلى الجنة، تجري من تحتهم الأنهار في جنات النعيم، دعواهم فيها: سبحانك اللهم، يطلبون بها ما شاؤوا، وتحيّتهم فيها: سلام، وآخر دعواهم: أن الحمد لله رب العالمين.", "h": ["التحذير من نسيان الآخرة، والإقبال على الدنيا والجري وراء زخارفها.", "التحذير من الغفلة بعدم التفكّر في الآيات الكونية والقرآنية، إذ هذا التفكّر هو سبيل الهداية والنجاة من الغواية.", "الإيمان والعمل الصالح مفتاح الجنة، والطريق الهادي إليها.", "نعيم الجنة روحاني وجسماني، وهو حاصل ثلاث كلمات: سبحانك اللهم، وسلام، والحمد لله رب العالمين."], "k": "«ورضوا بالحياة الدنيا واطمأنّوا بها»… هل اطمأنّ قلبي إلى الدنيا حتى نسيت أنها ممرّ؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 132;
insert into public.tdb_cards(topic, i, body) select 132, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١ – ٢", "q": "الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ ﴿١﴾ أَكَانَ لِلنَّاسِ عَجَبًا أَنۡ أَوۡحَيۡنَآ إِلَىٰ رَجُلٖ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓاْ أَنَّ لَهُمۡ قَدَمَ صِدۡقٍ عِندَ رَبِّهِمۡۗ قَالَ ٱلۡكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٞ مُّبِينٌ ﴿٢﴾", "w": [["الر", "هذه السورة الرابعة من السور المفتتحة بالحروف المقطعة، تُكتب: الر، وتُقرأ: ألف لام را."], ["الكتاب", "القرآن العظيم."], ["الحكيم", "القائل بالحكمة، والقرآن مشتمل على الحِكَم، فهو حكيم ومحكم أيضاً."], ["عجباً", "العجب: ما يُتعجّب منه."], ["قدم صدق", "أجراً حسناً بما قدّموا في حياتهم من الإيمان وصالح الأعمال."], ["إن هذا", "أي القرآن."], ["لسحر مبين", "بيّن ظاهر لا خفاء فيه، في كذبهم وادّعائهم الباطل."]], "m": "السورة مكية، تُعنى بقضية الوحي وإثباته: الر، تلك آيات الكتاب الحكيم، القرآن المحكم آياته المشتمل على الحكم الكثيرة حتى لكأنه الحكيم الذي يضع كل شيء في موضعه. أكان للناس من أهل مكة عجباً أن أوحينا إلى رجل منهم، محمد عبدنا ورسولنا من قريش، أن أنذر الناس عاقبة الشرك والكفر والعصيان، وبشّر الذين آمنوا أن لهم قدم صدق عند ربهم، الجزاء الحسن لما قدّموا من الإيمان وصالح الأعمال يتلقّونه يوم يلقونه؟ فلما أنذر وبشّر ﷺ قال الكافرون: إن هذا لساحر مبين، لمجرد دفع الحق وعدم قبوله، وإنما هي المجاحدة والعناد والمكابرة.", "h": ["تقرير عقيدة الوحي بشهادة الكتاب الموحى به.", "إثبات نبوة محمد ﷺ وتقريرها بالوحي إليه.", "بيان مهمة الرسول ﷺ، وهي النذارة والبشارة.", "بشرى أهل الإيمان والعمل الصالح بما أُعدّ لهم عند ربهم."], "k": "«أن لهم قدم صدق عند ربهم»… ماذا قدّمت اليوم ليكون لي قدم صدق هناك؟"}, {"lbl": "الآيات ٣ – ٦", "q": "إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُدَبِّرُ ٱلۡأَمۡرَۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا تَذَكَّرُونَ ﴿٣﴾ إِلَيۡهِ مَرۡجِعُكُمۡ جَمِيعٗاۖ وَعۡدَ ٱللَّهِ حَقًّاۚ إِنَّهُۥ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ بِٱلۡقِسۡطِۚ وَٱلَّذِينَ كَفَرُواْ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ ﴿٤﴾ هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ﴿٥﴾ إِنَّ فِي ٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَّقُونَ ﴿٦﴾", "w": [["إن ربكم الله", "معبودكم الحق الذي يجب أن تعبدوه وحده هو الله."], ["خلق السماوات والأرض", "أوجدها من العدم حيث كانت عدماً."], ["في ستة أيام", "هي الأحد والاثنين والثلاثاء والأربعاء والخميس والجمعة."], ["ما من شفيع إلا من بعد إذنه", "لا يشفع أحد يوم القيامة إلا من بعد أن يأذن له."], ["أفلا تذكّرون", "أتستمرّون في جحودكم وعنادكم فلا تذكّرون؟"], ["ثم يعيده", "بعد الفناء والبلى، وذلك يوم القيامة."], ["شراب من حميم", "من ماء أُحمي عليه وغلى حتى أصبح حميماً يشوي الوجوه."], ["جعل الشمس ضياء", "جعلها تضيء على الأرض."], ["والقمر نوراً", "جعل القمر ينير الأرض."], ["وقدّره منازل", "قدّر القمر منازل، والشمس كذلك."], ["لتعلموا", "قدّرهما منازل ليعلم الناس عدد السنين والحساب."], ["يتقون", "مساخط الله وعذابه، وذلك بطاعته وطاعة رسوله."]], "m": "هذه الآيات في تقرير الألوهية بعد تقرير الوحي: إن ربكم الله الذي خلق السماوات والأرض في ستة أيام بمقدار أيامنا هذه، ثم استوى على العرش استواء يليق بجلاله، يدبّر الأمر، هذا الإله الحق لا الأصنام التي لم تخلق شيئاً، ما من شفيع إلا من بعد إذنه لعظمته، فكيف تُعبد الأصنام رجاء شفاعتها؟ ذلكم الله ربكم فاعبدوه، أفلا تذكّرون؟ إليه مرجعكم جميعاً بعد الموت، وعد الله حقاً، إنه يبدأ الخلق ثم يعيده، ليجزي الذين آمنوا وعملوا الصالحات بالقسط والعدل، فهذه الدار دار عمل والآخرة دار جزاء، والقادر على البدء قادر على الإعادة، والذين كفروا لهم شراب من حميم وعذاب أليم بما كانوا يكفرون، وبهذا تقرّر مبدأ البعث بعد مبدأي التوحيد والوحي، إذ عليها تدور السور المكية. هو الذي جعل الشمس ضياء والقمر نوراً وقدّره منازل لتعلموا عدد السنين والحساب، إذ حياتكم تحتاج إلى ذلك، ما خلق الله ذلك إلا بالحق، لا عبثاً، ليأمر وينهى ثم يجزي، يفصّل الآيات لقوم يعلمون. إن في اختلاف الليل والنهار بالطول والقصر والضياء والظلام، وما خلق الله في السماوات والأرض من أفلاك وكواكب ورياح وأمطار، وإنسان وحيوان وبحار وأنهار وجبال، لآيات دالة على الخالق المعبود بحق، فيُعبد بحبه غاية الحب وتعظيمه غاية التعظيم، لقوم يتقون، إذ هم الذين يبصرونها لصفاء أرواحهم.", "h": ["تقرير ألوهية الله تعالى، وأنه الإله الحق.", "تقرير عقيدة البعث والجزاء في الدار الآخرة.", "بيان الحكمة في خلق الشمس والقمر وتقدير منازلهما.", "مشروعية تعلّم الحساب وعلم الفلك لما هو نافع للمسلمين."], "k": "«إن في اختلاف الليل والنهار… لآيات لقوم يتقون»… متى تأمّلت آخر مرة غروباً أو قمراً فذكرت ربي؟"}, {"lbl": "الآيات ٧ – ١٠", "q": "إِنَّ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا وَرَضُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَٱطۡمَأَنُّواْ بِهَا وَٱلَّذِينَ هُمۡ عَنۡ ءَايَٰتِنَا غَٰفِلُونَ ﴿٧﴾ أُوْلَـٰٓئِكَ مَأۡوَىٰهُمُ ٱلنَّارُ بِمَا كَانُواْ يَكۡسِبُونَ ﴿٨﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ فِي جَنَّـٰتِ ٱلنَّعِيمِ ﴿٩﴾ دَعۡوَىٰهُمۡ فِيهَا سُبۡحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمۡ فِيهَا سَلَٰمٞۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٠﴾", "w": [["لا يرجون لقاءنا", "لا ينتظرون ولا يؤمّلون لقاء الله تعالى يوم القيامة."], ["ورضوا بالحياة الدنيا", "بدلاً عن الآخرة، فلم يفكّروا في الدار الآخرة."], ["واطمأنّوا بها", "سكنوا إليها وركنوا، فلم يروا غيرها حياة يُعمل لها."], ["غافلون", "لا ينظرون إليها ولا يفكّرون فيها."], ["مأواهم النار", "النار هي المأوى الذي يأوون إليه، وليس لهم سواها."], ["يهديهم ربهم بإيمانهم", "يجعل لهم بإيمانهم نوراً يهتدون به إلى الجنة."], ["دعواهم فيها سبحانك اللهم", "يطلبون ما شاؤوا بكلمة: سبحانك اللهم."], ["وآخر دعواهم أن الحمد لله", "آخر دعائهم: الحمد لله رب العالمين."]], "m": "بعد تقرير الوحي والألوهية ذكر الجزاء: إن الذين لا يرجون لقاءنا، ورضوا بالحياة الدنيا بدلاً من الآخرة، واطمأنّوا بها فلم يروا غيرها حياة يُعمل لها، والذين هم عن آياتنا غافلون لا ينظرون فيها، أولئك مأواهم النار بما كانوا يكسبون من الشرك والمعاصي. إن الذين آمنوا وعملوا الصالحات يهديهم ربهم بإيمانهم، فيجعل لهم نوراً يهتدون به إلى الجنة، تجري من تحتهم الأنهار في جنات النعيم، دعواهم فيها: سبحانك اللهم، يطلبون بها ما شاؤوا، وتحيّتهم فيها: سلام، وآخر دعواهم: أن الحمد لله رب العالمين.", "h": ["التحذير من نسيان الآخرة، والإقبال على الدنيا والجري وراء زخارفها.", "التحذير من الغفلة بعدم التفكّر في الآيات الكونية والقرآنية، إذ هذا التفكّر هو سبيل الهداية والنجاة من الغواية.", "الإيمان والعمل الصالح مفتاح الجنة، والطريق الهادي إليها.", "نعيم الجنة روحاني وجسماني، وهو حاصل ثلاث كلمات: سبحانك اللهم، وسلام، والحمد لله رب العالمين."], "k": "«ورضوا بالحياة الدنيا واطمأنّوا بها»… هل اطمأنّ قلبي إلى الدنيا حتى نسيت أنها ممرّ؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (133, 10, 11, 20, 'سورة يونس ١١ – ٢٠', '«ولو يعجّل الله للناس الشر»، «ائت بقرآن غير هذا»، و«وما كان الناس إلا أمة واحدة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 133) = $j$[{"lbl": "الآيات ١١ – ١٤", "q": "۞وَلَوۡ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسۡتِعۡجَالَهُم بِٱلۡخَيۡرِ لَقُضِيَ إِلَيۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ ﴿١١﴾ وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوۡ قَاعِدًا أَوۡ قَآئِمٗا فَلَمَّا كَشَفۡنَا عَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ يَدۡعُنَآ إِلَىٰ ضُرّٖ مَّسَّهُۥۚ كَذَٰلِكَ زُيِّنَ لِلۡمُسۡرِفِينَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٢﴾ وَلَقَدۡ أَهۡلَكۡنَا ٱلۡقُرُونَ مِن قَبۡلِكُمۡ لَمَّا ظَلَمُواْ وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَمَا كَانُواْ لِيُؤۡمِنُواْۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ ﴿١٣﴾ ثُمَّ جَعَلۡنَٰكُمۡ خَلَـٰٓئِفَ فِي ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَيۡفَ تَعۡمَلُونَ ﴿١٤﴾", "w": [["الشر", "كل ما فيه ضرر في العقل أو الجسم أو المال والولد، والخير عكسه."], ["لقُضي إليهم أجلهم", "لهلكوا وماتوا."], ["فنذر", "فنترك."], ["في طغيانهم يعمهون", "في ظلمهم وكفرهم يتردّدون، لا يخرجون منه كالعميان."], ["الضر", "المرض، وكل ما يضرّ في جسمه أو ماله أو ولده."], ["للمسرفين", "المسرفين في الظلم والشر."], ["القرون", "أهل القرون."], ["بالبيّنات", "بالحجج والآيات على صدقهم في دعوتهم."], ["خلائف", "تخلفونهم بعد هلاكهم."]], "m": "كان المشركون في مكة في هيجان واضطراب حتى طالبوا بنزول العذاب، فنزل: ولو يعجّل الله للناس الشر عند سؤالهم إياه، كاستعجالهم الخير، لقُضي إليهم أجلهم فهلكوا الهلاك العام، فنذر الذين لا يؤمنون بلقائنا في طغيانهم يعمهون حيارى لا يعرفون مخرجاً. وإذا مسّ الإنسان الكافر الضر من مرض وفقر دعا ربه على الفور لجنبه أو قاعداً أو قائماً: يا رباه، فلما كشفنا عنه ضره مرّ كأن لم يدعنا إلى ضر مسّه، واستمر في كفره وغيّه، كذلك زُيّن للمسرفين ما كانوا يعملون، فيرون ظلمهم عدلاً وشرّهم خيراً. ولقد أهلكنا القرون من قبلكم يا أهل مكة لما ظلموا بالشرك، وجاءتهم رسلهم بالبيّنات وما كانوا ليؤمنوا، كعاد وثمود وأصحاب مدين، كذلك نجزي القوم المجرمين في كل زمان ومكان، ثم جعلناكم خلائف في الأرض من بعدهم لننظر كيف تعملون، فإن كان خيراً جزيناكم به، وإن كان سوءاً جزيناكم به.", "h": ["من مظاهر رحمة الله بعباده أنه لا يعجّل لهم ما يطلبون من العذاب كما يعجّل لهم الخير.", "بيان أن الإنسان الكافر يعرف الله عند الشدة ويدعوه ويضرع إليه، فإذا نجّاه عاد إلى الكفر به كأن لم يكن يعرفه.", "استمرار المشركين على إسرافهم في الكفر والشر والفساد مزيّن لهم حسب سنة الله تعالى، فمثلهم مثل الكافر يدعو عند الشدة وينسى عند الفرج.", "وعيد الله لأهل الإجرام بالعذاب العاجل أو الآجل إن لم يتوبوا.", "كل الناس أفراداً وأمماً ممهَلون مراقَبون في أعمالهم وسلوكهم، ومجزيّون بأعمالهم."], "k": "«مرّ كأن لم يدعنا إلى ضر مسّه»… كم مرة فرّج الله عني ثم نسيت أني دعوته؟"}, {"lbl": "الآيات ١٥ – ١٨", "q": "وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَاتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا ٱئۡتِ بِقُرۡءَانٍ غَيۡرِ هَٰذَآ أَوۡ بَدِّلۡهُۚ قُلۡ مَا يَكُونُ لِيٓ أَنۡ أُبَدِّلَهُۥ مِن تِلۡقَآيِٕ نَفۡسِيٓۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۖ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ ﴿١٥﴾ قُل لَّوۡ شَآءَ ٱللَّهُ مَا تَلَوۡتُهُۥ عَلَيۡكُمۡ وَلَآ أَدۡرَىٰكُم بِهِۦۖ فَقَدۡ لَبِثۡتُ فِيكُمۡ عُمُرٗا مِّن قَبۡلِهِۦٓۚ أَفَلَا تَعۡقِلُونَ ﴿١٦﴾ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡمُجۡرِمُونَ ﴿١٧﴾ وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡ وَيَقُولُونَ هَـٰٓؤُلَآءِ شُفَعَـٰٓؤُنَا عِندَ ٱللَّهِۚ قُلۡ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعۡلَمُ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿١٨﴾", "w": [["لا يرجون لقاءنا", "المنكرون للبعث، إذ به يتم اللقاء مع الله تعالى."], ["ائت بقرآن غير هذا", "خالٍ من عيب آلهتنا وانتقاصها."], ["أو بدّله", "أبقه ولكن ضع مكان آية فيها ما يسوؤنا آية لا إساءة فيها."], ["ولا أدراكم به", "ولا أعلمكم به."], ["عمراً", "أربعين سنة."], ["سبحانه", "تنزيهاً له."]], "m": "ما زال السياق في تقرير أصول الدين الثلاثة: التوحيد والوحي والبعث: وإذا تُتلى عليهم آياتنا بيّنات قال الذين لا يرجون لقاءنا: ائت بقرآن غير هذا خالٍ من عيب آلهتنا، أو بدّله فاجعل مكان آية تسوؤنا آية لا إساءة فيها، تحدّياً أو استهزاءً، فعلّمه الله الرد: قل ما يكون لي أن أبدّله من تلقاء نفسي، فأنا عبد الله ورسوله، إن أتبع إلا ما يوحى إليّ، إني أخاف إن عصيت ربي بتبديل كلامه عذاب يوم عظيم. قل لو شاء الله ما تلوته عليكم ولا أدراكم به، فالأمر أمره، فقد لبثت فيكم عمراً أربعين سنة قبل أن آتيكم به، أفلا تعقلون؟ فمن أظلم ممن افترى على الله كذباً بنسبة الشريك إليه، أو كذّب بآياته؟ لا أحد أظلم منهما، إنه لا يفلح المجرمون. ويعبدون من دون الله من الأصنام ما لا يضرّهم ولا ينفعهم، ويقولون: هؤلاء شفعاؤنا عند الله، قل: أتنبّئون الله بما لا يعلم في السماوات ولا في الأرض؟ إذ لو كان هناك من يشفع عنده لعلمه، سبحانه وتعالى عما يشركون.", "h": ["من الدعوة إلى الله تعالى تلاوة آياته القرآنية على الناس تذكيراً وتعليماً.", "بيان ما كان عليه المشركون من تعنّت وجحود ومكابرة.", "كون النبي ﷺ عاش أربعين سنة لم يُعرف فيها بعلم ولا معرفة، ثم برز فيها فتفوّق وفاق كل أحد، دليل على أنه نبي يوحى إليه قطعاً.", "لا أحد أظلم من أحد رجلين: رجل يكذب على الله تعالى، وآخر يكذّب الله تعالى.", "إبطال دعوى المشركين أن آلهتهم تشفع لهم عند الله يوم القيامة.", "بيان سبب عبادة المشركين لآلهتهم، وهو رجاؤهم شفاعتها لهم."], "k": "«ائت بقرآن غير هذا أو بدّله»… هل أتمنّى أحياناً لو كان حكمٌ في الدين غير ما هو عليه؟"}, {"lbl": "الآيتان ١٩ – ٢٠", "q": "وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةٗ وَٰحِدَةٗ فَٱخۡتَلَفُواْۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡ فِيمَا فِيهِ يَخۡتَلِفُونَ ﴿١٩﴾ وَيَقُولُونَ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا ٱلۡغَيۡبُ لِلَّهِ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ ﴿٢٠﴾", "w": [["أمة واحدة", "على دين واحد هو الإسلام."], ["فاختلفوا", "تفرّقوا، بأن بقي بعض على التوحيد وبعض على الشرك."], ["كلمة سبقت", "بإبقائهم إلى آجالهم ومجازاتهم يوم القيامة."], ["آية", "خارقة كناقة صالح ﵇."], ["إنما الغيب لله", "علم الآية متى تأتي من الغيب، والغيب لله وحده، فلا أنا ولا أنتم تعلمون، إذاً فانتظروا إني معكم من المنتظرين."]], "m": "يخبر الله رسوله بحقيقة تاريخية تساعد على الصبر: وما كان الناس إلا أمة واحدة على دين التوحيد، دين الفطرة، ثم أحدثت لهم شياطين الجن والإنس البدع والأهواء والشرك، فاختلفوا: فمنهم من ثبت على التوحيد ومنهم من كفر، ولولا كلمة سبقت من ربك ألّا يعجّل العذاب للأمم والأفراد بكفرهم، بل يؤخّرهم إلى آجالهم ليجزيهم يوم القيامة، لقُضي بينهم فيما فيه يختلفون، فأهلك الكافر وأنجى المؤمن. ويقولون: لولا أُنزل عليه آية خارقة من ربه نستدل بها على رسالته، وقد يريدون بالآية العذاب، فقل: إنما الغيب لله، فهو وحده يعلم متى يأتيكم، فانتظروا إني معكم من المنتظرين، ولم تطل مدة الانتظار، فنزل بهم العذاب ببدر.", "h": ["الأصل هو التوحيد، والشرك طارئ.", "الشر والشرك هما اللذان يُحدثان الخلاف في الأمة والتفرّق فيها، أما التوحيد والخير فلا يترتّب عليهما خلاف ولا حرب ولا فرقة.", "بيان علّة بقاء أهل الظلم والشرك يظلمون ويفسدون إلى آجالهم.", "الغيب كله لله، فلا أحد يعلم الغيب إلا الله، ومن علّمه الله شيئاً منه، وهذا خاص بالرسل لإقامة الحجة على أممهم."], "k": "«وما كان الناس إلا أمة واحدة»… الخلاف يولد من الهوى؛ فهل أكون سبب جمع أم سبب فرقة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 133;
insert into public.tdb_cards(topic, i, body) select 133, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١ – ١٤", "q": "۞وَلَوۡ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسۡتِعۡجَالَهُم بِٱلۡخَيۡرِ لَقُضِيَ إِلَيۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ ﴿١١﴾ وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوۡ قَاعِدًا أَوۡ قَآئِمٗا فَلَمَّا كَشَفۡنَا عَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ يَدۡعُنَآ إِلَىٰ ضُرّٖ مَّسَّهُۥۚ كَذَٰلِكَ زُيِّنَ لِلۡمُسۡرِفِينَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٢﴾ وَلَقَدۡ أَهۡلَكۡنَا ٱلۡقُرُونَ مِن قَبۡلِكُمۡ لَمَّا ظَلَمُواْ وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَمَا كَانُواْ لِيُؤۡمِنُواْۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ ﴿١٣﴾ ثُمَّ جَعَلۡنَٰكُمۡ خَلَـٰٓئِفَ فِي ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَيۡفَ تَعۡمَلُونَ ﴿١٤﴾", "w": [["الشر", "كل ما فيه ضرر في العقل أو الجسم أو المال والولد، والخير عكسه."], ["لقُضي إليهم أجلهم", "لهلكوا وماتوا."], ["فنذر", "فنترك."], ["في طغيانهم يعمهون", "في ظلمهم وكفرهم يتردّدون، لا يخرجون منه كالعميان."], ["الضر", "المرض، وكل ما يضرّ في جسمه أو ماله أو ولده."], ["للمسرفين", "المسرفين في الظلم والشر."], ["القرون", "أهل القرون."], ["بالبيّنات", "بالحجج والآيات على صدقهم في دعوتهم."], ["خلائف", "تخلفونهم بعد هلاكهم."]], "m": "كان المشركون في مكة في هيجان واضطراب حتى طالبوا بنزول العذاب، فنزل: ولو يعجّل الله للناس الشر عند سؤالهم إياه، كاستعجالهم الخير، لقُضي إليهم أجلهم فهلكوا الهلاك العام، فنذر الذين لا يؤمنون بلقائنا في طغيانهم يعمهون حيارى لا يعرفون مخرجاً. وإذا مسّ الإنسان الكافر الضر من مرض وفقر دعا ربه على الفور لجنبه أو قاعداً أو قائماً: يا رباه، فلما كشفنا عنه ضره مرّ كأن لم يدعنا إلى ضر مسّه، واستمر في كفره وغيّه، كذلك زُيّن للمسرفين ما كانوا يعملون، فيرون ظلمهم عدلاً وشرّهم خيراً. ولقد أهلكنا القرون من قبلكم يا أهل مكة لما ظلموا بالشرك، وجاءتهم رسلهم بالبيّنات وما كانوا ليؤمنوا، كعاد وثمود وأصحاب مدين، كذلك نجزي القوم المجرمين في كل زمان ومكان، ثم جعلناكم خلائف في الأرض من بعدهم لننظر كيف تعملون، فإن كان خيراً جزيناكم به، وإن كان سوءاً جزيناكم به.", "h": ["من مظاهر رحمة الله بعباده أنه لا يعجّل لهم ما يطلبون من العذاب كما يعجّل لهم الخير.", "بيان أن الإنسان الكافر يعرف الله عند الشدة ويدعوه ويضرع إليه، فإذا نجّاه عاد إلى الكفر به كأن لم يكن يعرفه.", "استمرار المشركين على إسرافهم في الكفر والشر والفساد مزيّن لهم حسب سنة الله تعالى، فمثلهم مثل الكافر يدعو عند الشدة وينسى عند الفرج.", "وعيد الله لأهل الإجرام بالعذاب العاجل أو الآجل إن لم يتوبوا.", "كل الناس أفراداً وأمماً ممهَلون مراقَبون في أعمالهم وسلوكهم، ومجزيّون بأعمالهم."], "k": "«مرّ كأن لم يدعنا إلى ضر مسّه»… كم مرة فرّج الله عني ثم نسيت أني دعوته؟"}, {"lbl": "الآيات ١٥ – ١٨", "q": "وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَاتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا ٱئۡتِ بِقُرۡءَانٍ غَيۡرِ هَٰذَآ أَوۡ بَدِّلۡهُۚ قُلۡ مَا يَكُونُ لِيٓ أَنۡ أُبَدِّلَهُۥ مِن تِلۡقَآيِٕ نَفۡسِيٓۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۖ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ ﴿١٥﴾ قُل لَّوۡ شَآءَ ٱللَّهُ مَا تَلَوۡتُهُۥ عَلَيۡكُمۡ وَلَآ أَدۡرَىٰكُم بِهِۦۖ فَقَدۡ لَبِثۡتُ فِيكُمۡ عُمُرٗا مِّن قَبۡلِهِۦٓۚ أَفَلَا تَعۡقِلُونَ ﴿١٦﴾ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡمُجۡرِمُونَ ﴿١٧﴾ وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡ وَيَقُولُونَ هَـٰٓؤُلَآءِ شُفَعَـٰٓؤُنَا عِندَ ٱللَّهِۚ قُلۡ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعۡلَمُ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿١٨﴾", "w": [["لا يرجون لقاءنا", "المنكرون للبعث، إذ به يتم اللقاء مع الله تعالى."], ["ائت بقرآن غير هذا", "خالٍ من عيب آلهتنا وانتقاصها."], ["أو بدّله", "أبقه ولكن ضع مكان آية فيها ما يسوؤنا آية لا إساءة فيها."], ["ولا أدراكم به", "ولا أعلمكم به."], ["عمراً", "أربعين سنة."], ["سبحانه", "تنزيهاً له."]], "m": "ما زال السياق في تقرير أصول الدين الثلاثة: التوحيد والوحي والبعث: وإذا تُتلى عليهم آياتنا بيّنات قال الذين لا يرجون لقاءنا: ائت بقرآن غير هذا خالٍ من عيب آلهتنا، أو بدّله فاجعل مكان آية تسوؤنا آية لا إساءة فيها، تحدّياً أو استهزاءً، فعلّمه الله الرد: قل ما يكون لي أن أبدّله من تلقاء نفسي، فأنا عبد الله ورسوله، إن أتبع إلا ما يوحى إليّ، إني أخاف إن عصيت ربي بتبديل كلامه عذاب يوم عظيم. قل لو شاء الله ما تلوته عليكم ولا أدراكم به، فالأمر أمره، فقد لبثت فيكم عمراً أربعين سنة قبل أن آتيكم به، أفلا تعقلون؟ فمن أظلم ممن افترى على الله كذباً بنسبة الشريك إليه، أو كذّب بآياته؟ لا أحد أظلم منهما، إنه لا يفلح المجرمون. ويعبدون من دون الله من الأصنام ما لا يضرّهم ولا ينفعهم، ويقولون: هؤلاء شفعاؤنا عند الله، قل: أتنبّئون الله بما لا يعلم في السماوات ولا في الأرض؟ إذ لو كان هناك من يشفع عنده لعلمه، سبحانه وتعالى عما يشركون.", "h": ["من الدعوة إلى الله تعالى تلاوة آياته القرآنية على الناس تذكيراً وتعليماً.", "بيان ما كان عليه المشركون من تعنّت وجحود ومكابرة.", "كون النبي ﷺ عاش أربعين سنة لم يُعرف فيها بعلم ولا معرفة، ثم برز فيها فتفوّق وفاق كل أحد، دليل على أنه نبي يوحى إليه قطعاً.", "لا أحد أظلم من أحد رجلين: رجل يكذب على الله تعالى، وآخر يكذّب الله تعالى.", "إبطال دعوى المشركين أن آلهتهم تشفع لهم عند الله يوم القيامة.", "بيان سبب عبادة المشركين لآلهتهم، وهو رجاؤهم شفاعتها لهم."], "k": "«ائت بقرآن غير هذا أو بدّله»… هل أتمنّى أحياناً لو كان حكمٌ في الدين غير ما هو عليه؟"}, {"lbl": "الآيتان ١٩ – ٢٠", "q": "وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةٗ وَٰحِدَةٗ فَٱخۡتَلَفُواْۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡ فِيمَا فِيهِ يَخۡتَلِفُونَ ﴿١٩﴾ وَيَقُولُونَ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا ٱلۡغَيۡبُ لِلَّهِ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ ﴿٢٠﴾", "w": [["أمة واحدة", "على دين واحد هو الإسلام."], ["فاختلفوا", "تفرّقوا، بأن بقي بعض على التوحيد وبعض على الشرك."], ["كلمة سبقت", "بإبقائهم إلى آجالهم ومجازاتهم يوم القيامة."], ["آية", "خارقة كناقة صالح ﵇."], ["إنما الغيب لله", "علم الآية متى تأتي من الغيب، والغيب لله وحده، فلا أنا ولا أنتم تعلمون، إذاً فانتظروا إني معكم من المنتظرين."]], "m": "يخبر الله رسوله بحقيقة تاريخية تساعد على الصبر: وما كان الناس إلا أمة واحدة على دين التوحيد، دين الفطرة، ثم أحدثت لهم شياطين الجن والإنس البدع والأهواء والشرك، فاختلفوا: فمنهم من ثبت على التوحيد ومنهم من كفر، ولولا كلمة سبقت من ربك ألّا يعجّل العذاب للأمم والأفراد بكفرهم، بل يؤخّرهم إلى آجالهم ليجزيهم يوم القيامة، لقُضي بينهم فيما فيه يختلفون، فأهلك الكافر وأنجى المؤمن. ويقولون: لولا أُنزل عليه آية خارقة من ربه نستدل بها على رسالته، وقد يريدون بالآية العذاب، فقل: إنما الغيب لله، فهو وحده يعلم متى يأتيكم، فانتظروا إني معكم من المنتظرين، ولم تطل مدة الانتظار، فنزل بهم العذاب ببدر.", "h": ["الأصل هو التوحيد، والشرك طارئ.", "الشر والشرك هما اللذان يُحدثان الخلاف في الأمة والتفرّق فيها، أما التوحيد والخير فلا يترتّب عليهما خلاف ولا حرب ولا فرقة.", "بيان علّة بقاء أهل الظلم والشرك يظلمون ويفسدون إلى آجالهم.", "الغيب كله لله، فلا أحد يعلم الغيب إلا الله، ومن علّمه الله شيئاً منه، وهذا خاص بالرسل لإقامة الحجة على أممهم."], "k": "«وما كان الناس إلا أمة واحدة»… الخلاف يولد من الهوى؛ فهل أكون سبب جمع أم سبب فرقة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (134, 10, 21, 33, 'سورة يونس ٢١ – ٣٣', '«إنما بغيكم على أنفسكم»، مثل الحياة الدنيا، «للذين أحسنوا الحسنى وزيادة»، و«فماذا بعد الحق إلا الضلال»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 134) = $j$[{"lbl": "الآيات ٢١ – ٢٣", "q": "وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ مِّنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرٞ فِيٓ ءَايَاتِنَاۚ قُلِ ٱللَّهُ أَسۡرَعُ مَكۡرًاۚ إِنَّ رُسُلَنَا يَكۡتُبُونَ مَا تَمۡكُرُونَ ﴿٢١﴾ هُوَ ٱلَّذِي يُسَيِّرُكُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ وَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ ﴿٢٢﴾ فَلَمَّآ أَنجَىٰهُمۡ إِذَا هُمۡ يَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۗ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغۡيُكُمۡ عَلَىٰٓ أَنفُسِكُمۖ مَّتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ إِلَيۡنَا مَرۡجِعُكُمۡ فَنُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٢٣﴾", "w": [["رحمة", "مطر بعد قحط، أو صحة بعد مرض، أو غنى بعد فاقة."], ["مكر في آياتنا", "استهزاء بها وتكذيب."], ["إن رسلنا", "الحفظة من الملائكة."], ["يسيّركم", "يجعلكم تسيرون بما خلق لكم من مراكب وما يسّر لكم من أسباب."], ["بريح طيبة", "مناسبة لسير السفن موافقة لغرضهم."], ["ريح عاصف", "شديدة تعصف بالشجر فتقتلعه والبناء فتهدمه."], ["وأُحيط بهم", "أحدق بهم الهلاك من كل جهة."], ["يبغون بغير الحق", "يظلمون مجانبين للحق والاعتدال."]], "m": "ما زال السياق في دعوة أهل مكة إلى التوحيد: وإذا أذقنا الناس رحمة من بعد ضراء مسّتهم، المطر بعد الجفاف، والغنى بعد الفاقة، والصحة بعد المرض، إذا لهم مكر في آياتنا بالاستهزاء والتكذيب، قل الله أسرع مكراً فسيريكم عاقبة مكره بإذلالكم في الدنيا وعذابكم في الآخرة، إن رسلنا الحفظة يكتبون ما تمكرون. ثم أراهم ضعفهم وحاجتهم إليه: هو الذي يسيّركم في البر على الإبل والخيل، وفي البحر على السفن، حتى إذا كنتم في الفلك وجرين بهم بريح طيبة وفرحوا بها، جاءتها ريح عاصف تضطرب لها السفن، وجاءهم الموج من كل مكان، وظنّوا أنهم أُحيط بهم، دعوا الله مخلصين له الدين: يا رب نجّنا، لئن أنجيتنا من هذه لنكوننّ من الشاكرين الموحّدين لك، فلما أنجاهم إذا هم يبغون في الأرض بغير الحق شركاً وظلماً، فعادوا لما كانوا عليه. يا أيها الناس الباغون في أي زمان ومكان، إنما بغيكم عائد على أنفسكم، تتأثّم به وتخبث وتصبح أهلاً لعذاب الله، متاع الحياة الدنيا، ثم إلينا مرجعكم فننبّئكم بما كنتم تعملون ونجزيكم الجزاء العادل.", "h": ["من مكر مكر الله به، والله أسرع مكراً وأكبر أثراً وضرراً.", "بيان ضعف الإنسان وفقره إلى الله، وحاجته إليه عز وجل في حفظ حياته وبقائه.", "إخلاص العبد الدعاء في حال الشدة آية أن التوحيد أصل والشرك طارئ.", "المشركون الأولون أحسن حالاً من جهلة هذه الأمة، إذ يشركون في الرخاء ويخلصون في الشدة، أما جهّال المسلمين اليوم فشركهم دائم في الرخاء والشدة على السواء.", "بغي الإنسان عائد على نفسه كمكره ونكثه، وفي الحديث: «ثلاث على أصحابها رواجع: البغي والمكر والنكث».", "تقرير مبدأ البعث والجزاء يوم القيامة."], "k": "«دعوا الله مخلصين له الدين»… لماذا أخلص في الشدة وأتفرّق في الرخاء؟"}, {"lbl": "الآيتان ٢٤ – ٢٥", "q": "إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا يَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّيَّنَتۡ وَظَنَّ أَهۡلُهَآ أَنَّهُمۡ قَٰدِرُونَ عَلَيۡهَآ أَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارٗا فَجَعَلۡنَٰهَا حَصِيدٗا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَتَفَكَّرُونَ ﴿٢٤﴾ وَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٢٥﴾", "w": [["مثل الحياة الدنيا", "صفتها المنطبقة عليها المتّفقة معها."], ["ماء", "مطر."], ["فاختلط به", "بسببه اشتبك نبات الأرض بعضه ببعض."], ["مما يأكل الناس", "كالبُرّ وسائر الحبوب والفواكه والخضر."], ["والأنعام", "من الكلأ والعشب."], ["زخرفها", "نضرتها وبهجتها."], ["وازّيّنت", "تجمّلت بالزهور."], ["قادرون عليها", "متمكّنون من تحصيل حاصلاتها الزراعية."], ["أتاها أمرنا", "قضاؤنا بإهلاكها وتدميرها عقوبة لأصحابها."], ["حصيداً", "كأنها محصودة بالمنجل، ليس فيها شيء قائم."], ["كأن لم تغن بالأمس", "كأن لم تكن موجودة غانية بالأمس."], ["نفصّل الآيات", "نبيّنها."], ["والله يدعو إلى دار السلام", "دار السلام: الجنة، والله يدعو إليها عباده ليأخذوا بالأهبة لدخولها، وهي الإيمان والعمل الصالح وترك الشرك والمعاصي."]], "m": "ما زال السياق يعرض الهدايات على الناس، فضرب مثلاً للحياة الدنيا التي يتكالب عليها الغافلون ويبيعون آخرتهم بها: إنما مثلها في نضارتها الغارّة وجمالها الخادع كماء نزل من السماء فاختلط به نبات الأرض مما يأكل الناس والأنعام، فنما وازدهر وأثمر، حتى إذا أخذت الأرض زخرفها وازّيّنت، وظن أهلها أنهم قادرون عليها فائزون بها، أتاها قضاؤنا فجأة ليلاً أو نهاراً، فجعلناها حصيداً هشيماً تذروه الرياح كأن لم تغن بالأمس، عاقبهم بجائحة لأنهم ظلموا فأمسوا يائسين حزينين، كذلك نفصّل الآيات لقوم يتفكّرون، فهلّا يتنبّه الغافلون! والله يدعو إلى دار السلام، الجنة، الخالية من الكدر والتنغيص، فلا مرض ولا هرم ولا موت ولا حزن، ودعاة الضلالة يدعون إلى الدنيا دار الكدر والهم والحزن، فأي الدعوتين تُجاب؟ ويهدي من يشاء إلى صراط مستقيم.", "h": ["بيان الصورة الحقيقية للحياة الدنيا في نضرتها وسرعة زوالها.", "التحذير من الاغترار بالدنيا والركون إليها.", "التحذير من الذنوب فإنها سبب الشقاء وسلب النعم.", "فضيلة التفكّر وأهله.", "فضل الله على عباده ورحمته بهم، إذ يدعوهم إلى داره لإكرامهم والإنعام عليهم."], "k": "«والله يدعو إلى دار السلام»… دعوتان تطرقان قلبي كل يوم: دعوة الدنيا ودعوة دار السلام؛ فأيّهما أجيب؟"}, {"lbl": "الآيات ٢٦ – ٣٠", "q": "۞لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ وَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرٞ وَلَا ذِلَّةٌۚ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢٦﴾ وَٱلَّذِينَ كَسَبُواْ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةِۭ بِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّةٞۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنۡ عَاصِمٖۖ كَأَنَّمَآ أُغۡشِيَتۡ وُجُوهُهُمۡ قِطَعٗا مِّنَ ٱلَّيۡلِ مُظۡلِمًاۚ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢٧﴾ وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُواْ مَكَانَكُمۡ أَنتُمۡ وَشُرَكَآؤُكُمۡۚ فَزَيَّلۡنَا بَيۡنَهُمۡۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمۡ إِيَّانَا تَعۡبُدُونَ ﴿٢٨﴾ فَكَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنَنَا وَبَيۡنَكُمۡ إِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَٰفِلِينَ ﴿٢٩﴾ هُنَالِكَ تَبۡلُواْ كُلُّ نَفۡسٖ مَّآ أَسۡلَفَتۡۚ وَرُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٣٠﴾", "w": [["الحسنى وزيادة", "الحسنى: الجنة، والزيادة: النظر إلى وجه الله الكريم."], ["ولا يرهق وجوههم", "لا يغشى وجوههم."], ["قتر", "غبرة من الكآبة والحزن."], ["السيئات", "جمع سيئة: ما يسيء إلى النفس من ذنوب الشرك والمعاصي."], ["مكانكم", "الزموا مكانكم لا تفارقوه."], ["تبلو كل نفس", "تختبر."], ["ما أسلفت", "ما قدّمت."], ["وضلّ عنهم ما كانوا يفترون", "غاب عنهم ما كانوا يكذبون."]], "m": "بعد أن ذكر أنه يدعو إلى دار السلام، ذكر جزاء من أجاب ومن لم يجب: للذين أحسنوا فآمنوا ووحّدوا الله وعبدوه بما شرع الحسنى، وهي الجنة، وزيادة، النظر إلى وجهه الكريم، ولا يرهق وجوههم إذا بُعثوا قتر ولا ذلة، أولئك أصحاب الجنة هم فيها خالدون. والذين كسبوا سيئات الشرك والمعاصي فدسّوا نفوسهم جزاء سيئة بمثلها، وترهقهم ذلة، ما لهم من الله من عاصم، كأنما أُغشيت وجوههم قطعاً من الليل مظلماً لسوادها، أولئك أصحاب النار هم فيها خالدون. ثم عرض حشر الناس تقريراً للإيمان باليوم الآخر: ويوم نحشرهم جميعاً ثم نقول للذين أشركوا: مكانكم أنتم وشركاؤكم لا تبرحوا، ففرّقنا بينهم، وقال شركاؤهم: ما كنتم إيانا تعبدون، ما كنا نسمعكم ولا نبصركم ولا أمرناكم بعبادتنا، وهذا قول كل من عُبد من دون الله، فكفى بالله شهيداً بيننا وبينكم إن كنا عن عبادتكم لغافلين. هنالك في ذلك الموقف الرهيب تبلو كل نفس ما أسلفت، تعرف هل هو ضار أو نافع، ورُدّوا إلى الله مولاهم الحق الذي طالما كفروا به، وضلّ عنهم ما كانوا يفترون من الأصنام التي سمّوها آلهة، وندموا يوم لا ينفع الندم.", "h": ["بيان فضل الحسنة وما تعقبه من نيل الحسنى.", "بيان سوء السيئة وما تورثه من حسرة وندامة، وما توجبه من خسران.", "تقرير معتقد البعث والجزاء بعرض صادق واضح له.", "تبرّؤ ما عُبد من دون الله من عابديه، سواء كان المعبود ملكاً أو إنساناً أو جاناً أو شجراً أو حجراً، الكل يتبرّأ من عابديه ويستشهد الله تعالى عليه."], "k": "«هنالك تبلو كل نفس ما أسلفت»… لو اختُبر ما أسلفته اليوم، فهل يسرّني أم يسوؤني؟"}, {"lbl": "الآيات ٣١ – ٣٣", "q": "قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أَمَّن يَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَمَن يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَمَن يُدَبِّرُ ٱلۡأَمۡرَۚ فَسَيَقُولُونَ ٱللَّهُۚ فَقُلۡ أَفَلَا تَتَّقُونَ ﴿٣١﴾ فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلۡحَقُّۖ فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ ﴿٣٢﴾ كَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓاْ أَنَّهُمۡ لَا يُؤۡمِنُونَ ﴿٣٣﴾", "w": [["من السماء", "بالغيث والمطر."], ["والأرض", "بالنبات والحبوب والثمار."], ["أمّن يملك السمع والأبصار", "يملك أسماعكم وأبصاركم، إن شاء أبقاها لكم وإن شاء سلبها منكم."], ["ومن يخرج الحي من الميت", "الجسم الحي من جسم ميت، والعكس كذلك."], ["ومن يدبّر الأمر", "أمر الخلائق كلها بالحياة والموت، والصحة والمرض، والعطاء والمنع."], ["أفلا تتقون", "الله، فلا تشركوا به شيئاً ولا تعصوه في أمره ونهيه."], ["فأنّى تُصرفون", "كيف تُصرفون عن الحق بعد معرفته؟ والحق أنه لا إله إلا الله."], ["أنهم لا يؤمنون", "لبلوغهم حداً لا يتمكّنون معه من التوبة البتة."]], "m": "ما زال السياق في تقرير التوحيد: قل لهم يا رسولنا: من يرزقكم من السماء بالمطر والأرض بالحبوب والثمار؟ أمّن يملك السمع والأبصار، إن شاء أمتعكم بها وإن شاء سلبكم إياها فأنتم عمي صم؟ ومن يخرج الحي من الميت، كالنخلة من النواة، ويخرج الميت من الحي، كالنواة من النخلة؟ ومن يدبّر الأمر في السماء والأرض، من تعاقب الليل والنهار، ونزول الأمطار، والحياة والموت، والغنى والفقر، والحرب والسلم؟ فسيقولون: الله، إذ لا جواب لهم غيره، فقل: أفلا تتقونه بتوحيده وعدم الإشراك به؟ فذلكم الله ربكم الحق الذي لا رب لكم سواه، فماذا بعد الحق إلا الضلال؟ فكيف تُصرفون عنه بعد معرفته؟ إنه أمر يدعو إلى العجب! كذلك حقّت كلمة ربك على الذين فسقوا أنهم لا يؤمنون، فالعبد إذا توغّل في الشر والفساد بالإدمان عليه بلغ حداً لا يتأتّى له الرجوع منه فيهلك على فسقه.", "h": ["مشركو العرب كانوا يشركون في الألوهية ويوحّدون في الربوبية.", "ليس بنافع أن يوحّد العبد في الربوبية ويشرك في الألوهية.", "ليس بعد الحق إلا الضلال، فلا واسطة بينهما، فمن لم يكن على حق فهو على ضلال."], "k": "«فماذا بعد الحق إلا الضلال»… أمر عرفت أنه الحق؛ فلماذا ما زلت أتردّد في اتباعه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 134;
insert into public.tdb_cards(topic, i, body) select 134, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢١ – ٢٣", "q": "وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ مِّنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرٞ فِيٓ ءَايَاتِنَاۚ قُلِ ٱللَّهُ أَسۡرَعُ مَكۡرًاۚ إِنَّ رُسُلَنَا يَكۡتُبُونَ مَا تَمۡكُرُونَ ﴿٢١﴾ هُوَ ٱلَّذِي يُسَيِّرُكُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ وَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ ﴿٢٢﴾ فَلَمَّآ أَنجَىٰهُمۡ إِذَا هُمۡ يَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۗ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغۡيُكُمۡ عَلَىٰٓ أَنفُسِكُمۖ مَّتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ إِلَيۡنَا مَرۡجِعُكُمۡ فَنُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٢٣﴾", "w": [["رحمة", "مطر بعد قحط، أو صحة بعد مرض، أو غنى بعد فاقة."], ["مكر في آياتنا", "استهزاء بها وتكذيب."], ["إن رسلنا", "الحفظة من الملائكة."], ["يسيّركم", "يجعلكم تسيرون بما خلق لكم من مراكب وما يسّر لكم من أسباب."], ["بريح طيبة", "مناسبة لسير السفن موافقة لغرضهم."], ["ريح عاصف", "شديدة تعصف بالشجر فتقتلعه والبناء فتهدمه."], ["وأُحيط بهم", "أحدق بهم الهلاك من كل جهة."], ["يبغون بغير الحق", "يظلمون مجانبين للحق والاعتدال."]], "m": "ما زال السياق في دعوة أهل مكة إلى التوحيد: وإذا أذقنا الناس رحمة من بعد ضراء مسّتهم، المطر بعد الجفاف، والغنى بعد الفاقة، والصحة بعد المرض، إذا لهم مكر في آياتنا بالاستهزاء والتكذيب، قل الله أسرع مكراً فسيريكم عاقبة مكره بإذلالكم في الدنيا وعذابكم في الآخرة، إن رسلنا الحفظة يكتبون ما تمكرون. ثم أراهم ضعفهم وحاجتهم إليه: هو الذي يسيّركم في البر على الإبل والخيل، وفي البحر على السفن، حتى إذا كنتم في الفلك وجرين بهم بريح طيبة وفرحوا بها، جاءتها ريح عاصف تضطرب لها السفن، وجاءهم الموج من كل مكان، وظنّوا أنهم أُحيط بهم، دعوا الله مخلصين له الدين: يا رب نجّنا، لئن أنجيتنا من هذه لنكوننّ من الشاكرين الموحّدين لك، فلما أنجاهم إذا هم يبغون في الأرض بغير الحق شركاً وظلماً، فعادوا لما كانوا عليه. يا أيها الناس الباغون في أي زمان ومكان، إنما بغيكم عائد على أنفسكم، تتأثّم به وتخبث وتصبح أهلاً لعذاب الله، متاع الحياة الدنيا، ثم إلينا مرجعكم فننبّئكم بما كنتم تعملون ونجزيكم الجزاء العادل.", "h": ["من مكر مكر الله به، والله أسرع مكراً وأكبر أثراً وضرراً.", "بيان ضعف الإنسان وفقره إلى الله، وحاجته إليه عز وجل في حفظ حياته وبقائه.", "إخلاص العبد الدعاء في حال الشدة آية أن التوحيد أصل والشرك طارئ.", "المشركون الأولون أحسن حالاً من جهلة هذه الأمة، إذ يشركون في الرخاء ويخلصون في الشدة، أما جهّال المسلمين اليوم فشركهم دائم في الرخاء والشدة على السواء.", "بغي الإنسان عائد على نفسه كمكره ونكثه، وفي الحديث: «ثلاث على أصحابها رواجع: البغي والمكر والنكث».", "تقرير مبدأ البعث والجزاء يوم القيامة."], "k": "«دعوا الله مخلصين له الدين»… لماذا أخلص في الشدة وأتفرّق في الرخاء؟"}, {"lbl": "الآيتان ٢٤ – ٢٥", "q": "إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا يَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّيَّنَتۡ وَظَنَّ أَهۡلُهَآ أَنَّهُمۡ قَٰدِرُونَ عَلَيۡهَآ أَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارٗا فَجَعَلۡنَٰهَا حَصِيدٗا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَتَفَكَّرُونَ ﴿٢٤﴾ وَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٢٥﴾", "w": [["مثل الحياة الدنيا", "صفتها المنطبقة عليها المتّفقة معها."], ["ماء", "مطر."], ["فاختلط به", "بسببه اشتبك نبات الأرض بعضه ببعض."], ["مما يأكل الناس", "كالبُرّ وسائر الحبوب والفواكه والخضر."], ["والأنعام", "من الكلأ والعشب."], ["زخرفها", "نضرتها وبهجتها."], ["وازّيّنت", "تجمّلت بالزهور."], ["قادرون عليها", "متمكّنون من تحصيل حاصلاتها الزراعية."], ["أتاها أمرنا", "قضاؤنا بإهلاكها وتدميرها عقوبة لأصحابها."], ["حصيداً", "كأنها محصودة بالمنجل، ليس فيها شيء قائم."], ["كأن لم تغن بالأمس", "كأن لم تكن موجودة غانية بالأمس."], ["نفصّل الآيات", "نبيّنها."], ["والله يدعو إلى دار السلام", "دار السلام: الجنة، والله يدعو إليها عباده ليأخذوا بالأهبة لدخولها، وهي الإيمان والعمل الصالح وترك الشرك والمعاصي."]], "m": "ما زال السياق يعرض الهدايات على الناس، فضرب مثلاً للحياة الدنيا التي يتكالب عليها الغافلون ويبيعون آخرتهم بها: إنما مثلها في نضارتها الغارّة وجمالها الخادع كماء نزل من السماء فاختلط به نبات الأرض مما يأكل الناس والأنعام، فنما وازدهر وأثمر، حتى إذا أخذت الأرض زخرفها وازّيّنت، وظن أهلها أنهم قادرون عليها فائزون بها، أتاها قضاؤنا فجأة ليلاً أو نهاراً، فجعلناها حصيداً هشيماً تذروه الرياح كأن لم تغن بالأمس، عاقبهم بجائحة لأنهم ظلموا فأمسوا يائسين حزينين، كذلك نفصّل الآيات لقوم يتفكّرون، فهلّا يتنبّه الغافلون! والله يدعو إلى دار السلام، الجنة، الخالية من الكدر والتنغيص، فلا مرض ولا هرم ولا موت ولا حزن، ودعاة الضلالة يدعون إلى الدنيا دار الكدر والهم والحزن، فأي الدعوتين تُجاب؟ ويهدي من يشاء إلى صراط مستقيم.", "h": ["بيان الصورة الحقيقية للحياة الدنيا في نضرتها وسرعة زوالها.", "التحذير من الاغترار بالدنيا والركون إليها.", "التحذير من الذنوب فإنها سبب الشقاء وسلب النعم.", "فضيلة التفكّر وأهله.", "فضل الله على عباده ورحمته بهم، إذ يدعوهم إلى داره لإكرامهم والإنعام عليهم."], "k": "«والله يدعو إلى دار السلام»… دعوتان تطرقان قلبي كل يوم: دعوة الدنيا ودعوة دار السلام؛ فأيّهما أجيب؟"}, {"lbl": "الآيات ٢٦ – ٣٠", "q": "۞لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ وَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرٞ وَلَا ذِلَّةٌۚ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢٦﴾ وَٱلَّذِينَ كَسَبُواْ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةِۭ بِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّةٞۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنۡ عَاصِمٖۖ كَأَنَّمَآ أُغۡشِيَتۡ وُجُوهُهُمۡ قِطَعٗا مِّنَ ٱلَّيۡلِ مُظۡلِمًاۚ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢٧﴾ وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُواْ مَكَانَكُمۡ أَنتُمۡ وَشُرَكَآؤُكُمۡۚ فَزَيَّلۡنَا بَيۡنَهُمۡۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمۡ إِيَّانَا تَعۡبُدُونَ ﴿٢٨﴾ فَكَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنَنَا وَبَيۡنَكُمۡ إِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَٰفِلِينَ ﴿٢٩﴾ هُنَالِكَ تَبۡلُواْ كُلُّ نَفۡسٖ مَّآ أَسۡلَفَتۡۚ وَرُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٣٠﴾", "w": [["الحسنى وزيادة", "الحسنى: الجنة، والزيادة: النظر إلى وجه الله الكريم."], ["ولا يرهق وجوههم", "لا يغشى وجوههم."], ["قتر", "غبرة من الكآبة والحزن."], ["السيئات", "جمع سيئة: ما يسيء إلى النفس من ذنوب الشرك والمعاصي."], ["مكانكم", "الزموا مكانكم لا تفارقوه."], ["تبلو كل نفس", "تختبر."], ["ما أسلفت", "ما قدّمت."], ["وضلّ عنهم ما كانوا يفترون", "غاب عنهم ما كانوا يكذبون."]], "m": "بعد أن ذكر أنه يدعو إلى دار السلام، ذكر جزاء من أجاب ومن لم يجب: للذين أحسنوا فآمنوا ووحّدوا الله وعبدوه بما شرع الحسنى، وهي الجنة، وزيادة، النظر إلى وجهه الكريم، ولا يرهق وجوههم إذا بُعثوا قتر ولا ذلة، أولئك أصحاب الجنة هم فيها خالدون. والذين كسبوا سيئات الشرك والمعاصي فدسّوا نفوسهم جزاء سيئة بمثلها، وترهقهم ذلة، ما لهم من الله من عاصم، كأنما أُغشيت وجوههم قطعاً من الليل مظلماً لسوادها، أولئك أصحاب النار هم فيها خالدون. ثم عرض حشر الناس تقريراً للإيمان باليوم الآخر: ويوم نحشرهم جميعاً ثم نقول للذين أشركوا: مكانكم أنتم وشركاؤكم لا تبرحوا، ففرّقنا بينهم، وقال شركاؤهم: ما كنتم إيانا تعبدون، ما كنا نسمعكم ولا نبصركم ولا أمرناكم بعبادتنا، وهذا قول كل من عُبد من دون الله، فكفى بالله شهيداً بيننا وبينكم إن كنا عن عبادتكم لغافلين. هنالك في ذلك الموقف الرهيب تبلو كل نفس ما أسلفت، تعرف هل هو ضار أو نافع، ورُدّوا إلى الله مولاهم الحق الذي طالما كفروا به، وضلّ عنهم ما كانوا يفترون من الأصنام التي سمّوها آلهة، وندموا يوم لا ينفع الندم.", "h": ["بيان فضل الحسنة وما تعقبه من نيل الحسنى.", "بيان سوء السيئة وما تورثه من حسرة وندامة، وما توجبه من خسران.", "تقرير معتقد البعث والجزاء بعرض صادق واضح له.", "تبرّؤ ما عُبد من دون الله من عابديه، سواء كان المعبود ملكاً أو إنساناً أو جاناً أو شجراً أو حجراً، الكل يتبرّأ من عابديه ويستشهد الله تعالى عليه."], "k": "«هنالك تبلو كل نفس ما أسلفت»… لو اختُبر ما أسلفته اليوم، فهل يسرّني أم يسوؤني؟"}, {"lbl": "الآيات ٣١ – ٣٣", "q": "قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أَمَّن يَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَمَن يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَمَن يُدَبِّرُ ٱلۡأَمۡرَۚ فَسَيَقُولُونَ ٱللَّهُۚ فَقُلۡ أَفَلَا تَتَّقُونَ ﴿٣١﴾ فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلۡحَقُّۖ فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ ﴿٣٢﴾ كَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓاْ أَنَّهُمۡ لَا يُؤۡمِنُونَ ﴿٣٣﴾", "w": [["من السماء", "بالغيث والمطر."], ["والأرض", "بالنبات والحبوب والثمار."], ["أمّن يملك السمع والأبصار", "يملك أسماعكم وأبصاركم، إن شاء أبقاها لكم وإن شاء سلبها منكم."], ["ومن يخرج الحي من الميت", "الجسم الحي من جسم ميت، والعكس كذلك."], ["ومن يدبّر الأمر", "أمر الخلائق كلها بالحياة والموت، والصحة والمرض، والعطاء والمنع."], ["أفلا تتقون", "الله، فلا تشركوا به شيئاً ولا تعصوه في أمره ونهيه."], ["فأنّى تُصرفون", "كيف تُصرفون عن الحق بعد معرفته؟ والحق أنه لا إله إلا الله."], ["أنهم لا يؤمنون", "لبلوغهم حداً لا يتمكّنون معه من التوبة البتة."]], "m": "ما زال السياق في تقرير التوحيد: قل لهم يا رسولنا: من يرزقكم من السماء بالمطر والأرض بالحبوب والثمار؟ أمّن يملك السمع والأبصار، إن شاء أمتعكم بها وإن شاء سلبكم إياها فأنتم عمي صم؟ ومن يخرج الحي من الميت، كالنخلة من النواة، ويخرج الميت من الحي، كالنواة من النخلة؟ ومن يدبّر الأمر في السماء والأرض، من تعاقب الليل والنهار، ونزول الأمطار، والحياة والموت، والغنى والفقر، والحرب والسلم؟ فسيقولون: الله، إذ لا جواب لهم غيره، فقل: أفلا تتقونه بتوحيده وعدم الإشراك به؟ فذلكم الله ربكم الحق الذي لا رب لكم سواه، فماذا بعد الحق إلا الضلال؟ فكيف تُصرفون عنه بعد معرفته؟ إنه أمر يدعو إلى العجب! كذلك حقّت كلمة ربك على الذين فسقوا أنهم لا يؤمنون، فالعبد إذا توغّل في الشر والفساد بالإدمان عليه بلغ حداً لا يتأتّى له الرجوع منه فيهلك على فسقه.", "h": ["مشركو العرب كانوا يشركون في الألوهية ويوحّدون في الربوبية.", "ليس بنافع أن يوحّد العبد في الربوبية ويشرك في الألوهية.", "ليس بعد الحق إلا الضلال، فلا واسطة بينهما، فمن لم يكن على حق فهو على ضلال."], "k": "«فماذا بعد الحق إلا الضلال»… أمر عرفت أنه الحق؛ فلماذا ما زلت أتردّد في اتباعه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (135, 10, 34, 48, 'سورة يونس ٣٤ – ٤٨', '«أفمن يهدي إلى الحق أحق أن يُتّبع»، «فأتوا بسورة مثله»، و«إن الله لا يظلم الناس شيئاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 135) = $j$[{"lbl": "الآيات ٣٤ – ٣٦", "q": "قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۚ قُلِ ٱللَّهُ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۖ فَأَنَّىٰ تُؤۡفَكُونَ ﴿٣٤﴾ قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَهۡدِيٓ إِلَى ٱلۡحَقِّۚ قُلِ ٱللَّهُ يَهۡدِي لِلۡحَقِّۗ أَفَمَن يَهۡدِيٓ إِلَى ٱلۡحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّيٓ إِلَّآ أَن يُهۡدَىٰۖ فَمَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ ﴿٣٥﴾ وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَفۡعَلُونَ ﴿٣٦﴾", "w": [["من شركائكم", "جمع شريك، وهو من أشركوه في عبادة الله تعالى."], ["من يبدأ الخلق", "ينشئ الإنسان والحيوان أول ما ينشئه، فذلك بدء خلقه."], ["فأنّى تؤفكون", "كيف تُصرفون عن الحق بعد معرفته؟"], ["أمّن لا يهدّي", "أي لا يهتدي."], ["كيف تحكمون", "هذا الحكم الفاسد، وهو اتباع من لا يصح اتباعه لأنه لا يهدي."]], "m": "ما زال السياق في حجاج المشركين: قل هل من شركائكم التي تعبدونها من يبدأ خلق إنسان من العدم ثم يميته ثم يعيده؟ والجواب: لا يوجد، قل الله يبدأ الخلق ثم يعيده، فأنّى تؤفكون عن الحق بعد الإقرار به؟ قل هل من شركائكم من يهدي إلى الحق؟ لا، لأنها لا تتكلّم ولا تعلم، قل الله يهدي للحق بواسطة نبيه ووحيه وآياته، أفمن يهدي إلى الحق أحق أن يُتّبع، أمّن لا يهتدي إلا أن يُهدى؟ فما لكم كيف تحكمون هذا الحكم الفاسد باتباع من لا يهدي؟ وما يتّبع أكثرهم في عبادة أصنامهم إلا ظناً، لا يقين عندهم أنها آلهة، إن الظن لا يغني من الحق شيئاً، والمطلوب في العقيدة العلم لا الظن، إن الله عليم بما يفعلون، وعيد شديد على إصرارهم وعنادهم.", "h": ["تقرير التوحيد بإبطال الآلهة المزعومة، حيث اعترف عابدوها بأنها لا تبدأ خلقاً ولا تعيده، ولا تهدي إلى الحق، والله يبدأ الخلق ثم يعيده ويهدي إلى الحق.", "إبطال الأحكام الفاسدة وعدم إقرارها، ووجوب تصحيحها.", "لا يُقبل الظن في العقائد، بل لا بد من العلم اليقيني فيها.", "كراهية القول بالظن والعمل به، وفي الحديث: «إياكم والظن فإن الظن أكذب الحديث»."], "k": "«إن الظن لا يغني من الحق شيئاً»… كم من حكم أصدرته على الناس بظن لا بعلم؟"}, {"lbl": "الآيات ٣٧ – ٣٩", "q": "وَمَا كَانَ هَٰذَا ٱلۡقُرۡءَانُ أَن يُفۡتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٣٧﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِسُورَةٖ مِّثۡلِهِۦ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ ﴿٣٨﴾ بَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّـٰلِمِينَ ﴿٣٩﴾", "w": [["أن يُفترى من دون الله", "لم يكن هذا القرآن افتراءً من غير الله."], ["وتفصيل الكتاب", "بيان ما فرض الله تعالى على هذه الأمة وما أحل لها وما حرّم عليها."], ["أم يقولون افتراه", "بل يقولون اختلقه من نفسه وتقوّله من عنده."], ["بما لم يحيطوا بعلمه", "بما توعّدهم الله تعالى به من العذاب."], ["ولما يأتهم تأويله", "ولما يأتهم بعد ما يؤول إليه ذلك الوعيد من العذاب."], ["كذلك كذّب الذين من قبلهم", "كتكذيب هؤلاء بوعد الله لهم كذّب الذين من قبلهم."]], "m": "هذه الآيات في تقرير الوحي وإثبات النبوة: وما كان هذا القرآن العظيم أن يُختلق من غير الله، ولكن تصديق الذي بين يديه من التوراة والإنجيل، وتفصيل ما كتبه الله على هذه الأمة من الفرائض والشرائع، لا ريب فيه أنه من رب العالمين، ومن مقتضى ربوبيته إنزال كتاب فيه تبيان كل ما يحتاج إليه العبد في كماله البدني والروحي والعقلي والخلقي. أم يقولون افتراه محمد؟ قول في غاية السخف، قل متحدّياً: فأتوا بسورة مثله، وادعوا لمعونتكم من استطعتم من دون الله إن كنتم صادقين. بل القضية أنهم كذّبوا بما لم يحيطوا بعلمه من وعيد الله بالعذاب، ولما يأتهم ما يؤول إليه، إذ لو رأوه ما كذّبوا، كذلك كذّب الذين من قبلهم حتى ذاقوا بأسنا، فانظر كيف كان عاقبة الظالمين: أُهلك قوم نوح بالغرق، وقوم هود بالريح، وقوم صالح بالصيحة، وقوم شعيب بالرجفة، فإن استمرّ هؤلاء حلّ بهم ما حلّ بغيرهم.", "h": ["تقرير عقيدة الوحي، وإثبات نبوة محمد ﷺ.", "من أدلة أن القرآن كلام الله: تصديقه للكتب السالفة وعدم التناقض معها، إذ هما من مصدر واحد.", "من أدلّته كذلك: بلاغته وإعجازه، وعجزهم عن الإتيان بسورة مثله.", "استمرار المشركين في العناد والمجاحدة علّته أنهم لم يذوقوا ما توعّدهم الله به من العذاب، إذ لو ذاقوا لآمنوا، ولكن لا ينفعهم حينئذ الإيمان."], "k": "«بل كذّبوا بما لم يحيطوا بعلمه»… هل أرفض شيئاً من الدين لمجرد أني لم أفهمه بعد؟"}, {"lbl": "الآيات ٤٠ – ٤٤", "q": "وَمِنۡهُم مَّن يُؤۡمِنُ بِهِۦ وَمِنۡهُم مَّن لَّا يُؤۡمِنُ بِهِۦۚ وَرَبُّكَ أَعۡلَمُ بِٱلۡمُفۡسِدِينَ ﴿٤٠﴾ وَإِن كَذَّبُوكَ فَقُل لِّي عَمَلِي وَلَكُمۡ عَمَلُكُمۡۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعۡمَلُ وَأَنَا۠ بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ ﴿٤١﴾ وَمِنۡهُم مَّن يَسۡتَمِعُونَ إِلَيۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُواْ لَا يَعۡقِلُونَ ﴿٤٢﴾ وَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ أَفَأَنتَ تَهۡدِي ٱلۡعُمۡيَ وَلَوۡ كَانُواْ لَا يُبۡصِرُونَ ﴿٤٣﴾ إِنَّ ٱللَّهَ لَا يَظۡلِمُ ٱلنَّاسَ شَيۡـٔٗا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٤٤﴾", "w": [["ومنهم من يؤمن به", "من أهل مكة المكذّبين بالقرآن من يؤمن به مستقبلاً."], ["ومنهم من يستمعون إليك", "أي إذا قرأت القرآن."], ["ومنهم من ينظر إليك", "يبصر ويشاهد آيات النبوة وأعلام صدقك، ولا يهتدي إلى معرفة أنك رسول الله لأن الله حرمه ذلك."]], "m": "ما زال السياق في تقرير النبوة، يسلّي الله رسوله ويصبّره: ومنهم من يؤمن بالقرآن وبالنبي، ومنهم من لا يؤمن به، وهذا إخبار بالغيب تم كما أخبر، وربك أعلم بالمفسدين الذين يصدّون الناس عن الإيمان، تهديد لهم. وإن كذّبوك فلا تحفل بهم، وقل: لي عملي ولكم عملكم، أنتم بريئون مما أعمل وأنا بريء مما تعملون. ومنهم من يستمعون إليك إذا قرأت القرآن أو دعوت، ولا ينتفعون، أفأنت تسمع الصم ولو كانوا لا يعقلون؟ ومنهم من ينظر إليك بعين مفتّحة ويرى علامات النبوة في حالك ومقالك، أفأنت تهدي العمي ولو كانوا لا يبصرون؟ إن الله لا يظلم الناس شيئاً، ولكن الناس أنفسهم يظلمون، فمن توغّل في البغض لشيء صار غير قادر على الانتفاع بما يسمع منه أو يبصر فيه، ولذا قيل: حبك الشيء يُعمي ويُصمّ، والبغض كذلك، والاسترسال في الشر مدة يحرم صاحبه التوبة.", "h": ["إخبار القرآن بالغيب وصدقه في ذلك.", "تقرير معنى آية: «فإنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور».", "تعليم رسول الله ﷺ طريق الحجاج والرد على الخصوم المشركين.", "انتفاء الظلم عن الله تعالى، وإثباته للإنسان لنفسه."], "k": "«ومنهم من يستمعون إليك»… أسمع كثيراً من المواعظ؛ فهل أسمع بأذني فقط، أم بقلبي؟"}, {"lbl": "الآيات ٤٥ – ٤٨", "q": "وَيَوۡمَ يَحۡشُرُهُمۡ كَأَن لَّمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيۡنَهُمۡۚ قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِ وَمَا كَانُواْ مُهۡتَدِينَ ﴿٤٥﴾ وَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفۡعَلُونَ ﴿٤٦﴾ وَلِكُلِّ أُمَّةٖ رَّسُولٞۖ فَإِذَا جَآءَ رَسُولُهُمۡ قُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ ﴿٤٧﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤٨﴾", "w": [["يحشرهم", "يبعثهم من قبورهم ويجمعهم لساحة فصل القضاء."], ["كأن لم يلبثوا", "أي في الدنيا أحياء في دورهم، وأمواتاً في قبورهم."], ["أو نتوفّينّك", "نميتك قبل ذلك."], ["فإذا جاء رسولهم", "أي في عرصات القيامة."], ["بالقسط", "بالعدل."], ["متى هذا الوعد", "أي بالعذاب يوم القيامة."]], "m": "ما زال السياق في تقرير البعث والجزاء: ويوم يحشرهم من قبورهم كأن لم يلبثوا في الدنيا أحياء ثم في قبورهم أمواتاً إلا ساعة من النهار، يتعارفون بينهم ساعة ثم يحول بينهم هول الموقف، قد خسر الذين كذّبوا بلقاء الله فلم يعملوا بمحابّه، خسروا أنفسهم وأهليهم في جهنم، وما كانوا مهتدين في حياتهم. وإما نرينّك بعض الذي نعدهم من العذاب في الدنيا فذاك، أو نتوفّينّك قبل ذلك، فإلينا مرجعهم بعد موتهم فنحاسبهم ونجازيهم، ثم الله شهيد على ما يفعلون، وشهادته كافية في وجوب تعذيبهم. ولكل أمة رسول أُرسل إليها فأطاع من أطاع وعصى من عصى، فإذا جاء رسولهم في عرصات القيامة قُضي بينهم بالعدل وهم لا يُظلمون، لا بنقص حسنات المحسنين ولا بزيادة سيئات المسيئين. ويقول المشركون استعجالاً: متى هذا الوعد إن كنتم صادقين؟", "h": ["تقرير مبدأ المعاد والدار الآخرة.", "الإعلان عن خسران منكري البعث يوم القيامة.", "تسلية الرسول ﷺ وحمله على الصبر حتى يؤدّي رسالته، بإعلامه أنه سيعذّب أعداءه.", "بيان كيفية الحساب يوم القيامة: بأن يأتي الرسول وأمته ثم يجري الحساب بينهم، فينجّي الله المؤمنين ويعذّب الكافرين."], "k": "«كأن لم يلبثوا إلا ساعة من النهار»… عمري كله سيبدو ساعة؛ فكيف أنفق ما بقي منها؟"}]$j$::jsonb then 0 else 1 end;
