insert into public.tdb_cards(topic, i, body) select 135, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٤ – ٣٦", "q": "قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۚ قُلِ ٱللَّهُ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۖ فَأَنَّىٰ تُؤۡفَكُونَ ﴿٣٤﴾ قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَهۡدِيٓ إِلَى ٱلۡحَقِّۚ قُلِ ٱللَّهُ يَهۡدِي لِلۡحَقِّۗ أَفَمَن يَهۡدِيٓ إِلَى ٱلۡحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّيٓ إِلَّآ أَن يُهۡدَىٰۖ فَمَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ ﴿٣٥﴾ وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَفۡعَلُونَ ﴿٣٦﴾", "w": [["من شركائكم", "جمع شريك، وهو من أشركوه في عبادة الله تعالى."], ["من يبدأ الخلق", "ينشئ الإنسان والحيوان أول ما ينشئه، فذلك بدء خلقه."], ["فأنّى تؤفكون", "كيف تُصرفون عن الحق بعد معرفته؟"], ["أمّن لا يهدّي", "أي لا يهتدي."], ["كيف تحكمون", "هذا الحكم الفاسد، وهو اتباع من لا يصح اتباعه لأنه لا يهدي."]], "m": "ما زال السياق في حجاج المشركين: قل هل من شركائكم التي تعبدونها من يبدأ خلق إنسان من العدم ثم يميته ثم يعيده؟ والجواب: لا يوجد، قل الله يبدأ الخلق ثم يعيده، فأنّى تؤفكون عن الحق بعد الإقرار به؟ قل هل من شركائكم من يهدي إلى الحق؟ لا، لأنها لا تتكلّم ولا تعلم، قل الله يهدي للحق بواسطة نبيه ووحيه وآياته، أفمن يهدي إلى الحق أحق أن يُتّبع، أمّن لا يهتدي إلا أن يُهدى؟ فما لكم كيف تحكمون هذا الحكم الفاسد باتباع من لا يهدي؟ وما يتّبع أكثرهم في عبادة أصنامهم إلا ظناً، لا يقين عندهم أنها آلهة، إن الظن لا يغني من الحق شيئاً، والمطلوب في العقيدة العلم لا الظن، إن الله عليم بما يفعلون، وعيد شديد على إصرارهم وعنادهم.", "h": ["تقرير التوحيد بإبطال الآلهة المزعومة، حيث اعترف عابدوها بأنها لا تبدأ خلقاً ولا تعيده، ولا تهدي إلى الحق، والله يبدأ الخلق ثم يعيده ويهدي إلى الحق.", "إبطال الأحكام الفاسدة وعدم إقرارها، ووجوب تصحيحها.", "لا يُقبل الظن في العقائد، بل لا بد من العلم اليقيني فيها.", "كراهية القول بالظن والعمل به، وفي الحديث: «إياكم والظن فإن الظن أكذب الحديث»."], "k": "«إن الظن لا يغني من الحق شيئاً»… كم من حكم أصدرته على الناس بظن لا بعلم؟"}, {"lbl": "الآيات ٣٧ – ٣٩", "q": "وَمَا كَانَ هَٰذَا ٱلۡقُرۡءَانُ أَن يُفۡتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٣٧﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِسُورَةٖ مِّثۡلِهِۦ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ ﴿٣٨﴾ بَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّـٰلِمِينَ ﴿٣٩﴾", "w": [["أن يُفترى من دون الله", "لم يكن هذا القرآن افتراءً من غير الله."], ["وتفصيل الكتاب", "بيان ما فرض الله تعالى على هذه الأمة وما أحل لها وما حرّم عليها."], ["أم يقولون افتراه", "بل يقولون اختلقه من نفسه وتقوّله من عنده."], ["بما لم يحيطوا بعلمه", "بما توعّدهم الله تعالى به من العذاب."], ["ولما يأتهم تأويله", "ولما يأتهم بعد ما يؤول إليه ذلك الوعيد من العذاب."], ["كذلك كذّب الذين من قبلهم", "كتكذيب هؤلاء بوعد الله لهم كذّب الذين من قبلهم."]], "m": "هذه الآيات في تقرير الوحي وإثبات النبوة: وما كان هذا القرآن العظيم أن يُختلق من غير الله، ولكن تصديق الذي بين يديه من التوراة والإنجيل، وتفصيل ما كتبه الله على هذه الأمة من الفرائض والشرائع، لا ريب فيه أنه من رب العالمين، ومن مقتضى ربوبيته إنزال كتاب فيه تبيان كل ما يحتاج إليه العبد في كماله البدني والروحي والعقلي والخلقي. أم يقولون افتراه محمد؟ قول في غاية السخف، قل متحدّياً: فأتوا بسورة مثله، وادعوا لمعونتكم من استطعتم من دون الله إن كنتم صادقين. بل القضية أنهم كذّبوا بما لم يحيطوا بعلمه من وعيد الله بالعذاب، ولما يأتهم ما يؤول إليه، إذ لو رأوه ما كذّبوا، كذلك كذّب الذين من قبلهم حتى ذاقوا بأسنا، فانظر كيف كان عاقبة الظالمين: أُهلك قوم نوح بالغرق، وقوم هود بالريح، وقوم صالح بالصيحة، وقوم شعيب بالرجفة، فإن استمرّ هؤلاء حلّ بهم ما حلّ بغيرهم.", "h": ["تقرير عقيدة الوحي، وإثبات نبوة محمد ﷺ.", "من أدلة أن القرآن كلام الله: تصديقه للكتب السالفة وعدم التناقض معها، إذ هما من مصدر واحد.", "من أدلّته كذلك: بلاغته وإعجازه، وعجزهم عن الإتيان بسورة مثله.", "استمرار المشركين في العناد والمجاحدة علّته أنهم لم يذوقوا ما توعّدهم الله به من العذاب، إذ لو ذاقوا لآمنوا، ولكن لا ينفعهم حينئذ الإيمان."], "k": "«بل كذّبوا بما لم يحيطوا بعلمه»… هل أرفض شيئاً من الدين لمجرد أني لم أفهمه بعد؟"}, {"lbl": "الآيات ٤٠ – ٤٤", "q": "وَمِنۡهُم مَّن يُؤۡمِنُ بِهِۦ وَمِنۡهُم مَّن لَّا يُؤۡمِنُ بِهِۦۚ وَرَبُّكَ أَعۡلَمُ بِٱلۡمُفۡسِدِينَ ﴿٤٠﴾ وَإِن كَذَّبُوكَ فَقُل لِّي عَمَلِي وَلَكُمۡ عَمَلُكُمۡۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعۡمَلُ وَأَنَا۠ بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ ﴿٤١﴾ وَمِنۡهُم مَّن يَسۡتَمِعُونَ إِلَيۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُواْ لَا يَعۡقِلُونَ ﴿٤٢﴾ وَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ أَفَأَنتَ تَهۡدِي ٱلۡعُمۡيَ وَلَوۡ كَانُواْ لَا يُبۡصِرُونَ ﴿٤٣﴾ إِنَّ ٱللَّهَ لَا يَظۡلِمُ ٱلنَّاسَ شَيۡـٔٗا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٤٤﴾", "w": [["ومنهم من يؤمن به", "من أهل مكة المكذّبين بالقرآن من يؤمن به مستقبلاً."], ["ومنهم من يستمعون إليك", "أي إذا قرأت القرآن."], ["ومنهم من ينظر إليك", "يبصر ويشاهد آيات النبوة وأعلام صدقك، ولا يهتدي إلى معرفة أنك رسول الله لأن الله حرمه ذلك."]], "m": "ما زال السياق في تقرير النبوة، يسلّي الله رسوله ويصبّره: ومنهم من يؤمن بالقرآن وبالنبي، ومنهم من لا يؤمن به، وهذا إخبار بالغيب تم كما أخبر، وربك أعلم بالمفسدين الذين يصدّون الناس عن الإيمان، تهديد لهم. وإن كذّبوك فلا تحفل بهم، وقل: لي عملي ولكم عملكم، أنتم بريئون مما أعمل وأنا بريء مما تعملون. ومنهم من يستمعون إليك إذا قرأت القرآن أو دعوت، ولا ينتفعون، أفأنت تسمع الصم ولو كانوا لا يعقلون؟ ومنهم من ينظر إليك بعين مفتّحة ويرى علامات النبوة في حالك ومقالك، أفأنت تهدي العمي ولو كانوا لا يبصرون؟ إن الله لا يظلم الناس شيئاً، ولكن الناس أنفسهم يظلمون، فمن توغّل في البغض لشيء صار غير قادر على الانتفاع بما يسمع منه أو يبصر فيه، ولذا قيل: حبك الشيء يُعمي ويُصمّ، والبغض كذلك، والاسترسال في الشر مدة يحرم صاحبه التوبة.", "h": ["إخبار القرآن بالغيب وصدقه في ذلك.", "تقرير معنى آية: «فإنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور».", "تعليم رسول الله ﷺ طريق الحجاج والرد على الخصوم المشركين.", "انتفاء الظلم عن الله تعالى، وإثباته للإنسان لنفسه."], "k": "«ومنهم من يستمعون إليك»… أسمع كثيراً من المواعظ؛ فهل أسمع بأذني فقط، أم بقلبي؟"}, {"lbl": "الآيات ٤٥ – ٤٨", "q": "وَيَوۡمَ يَحۡشُرُهُمۡ كَأَن لَّمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيۡنَهُمۡۚ قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِ وَمَا كَانُواْ مُهۡتَدِينَ ﴿٤٥﴾ وَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفۡعَلُونَ ﴿٤٦﴾ وَلِكُلِّ أُمَّةٖ رَّسُولٞۖ فَإِذَا جَآءَ رَسُولُهُمۡ قُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ ﴿٤٧﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤٨﴾", "w": [["يحشرهم", "يبعثهم من قبورهم ويجمعهم لساحة فصل القضاء."], ["كأن لم يلبثوا", "أي في الدنيا أحياء في دورهم، وأمواتاً في قبورهم."], ["أو نتوفّينّك", "نميتك قبل ذلك."], ["فإذا جاء رسولهم", "أي في عرصات القيامة."], ["بالقسط", "بالعدل."], ["متى هذا الوعد", "أي بالعذاب يوم القيامة."]], "m": "ما زال السياق في تقرير البعث والجزاء: ويوم يحشرهم من قبورهم كأن لم يلبثوا في الدنيا أحياء ثم في قبورهم أمواتاً إلا ساعة من النهار، يتعارفون بينهم ساعة ثم يحول بينهم هول الموقف، قد خسر الذين كذّبوا بلقاء الله فلم يعملوا بمحابّه، خسروا أنفسهم وأهليهم في جهنم، وما كانوا مهتدين في حياتهم. وإما نرينّك بعض الذي نعدهم من العذاب في الدنيا فذاك، أو نتوفّينّك قبل ذلك، فإلينا مرجعهم بعد موتهم فنحاسبهم ونجازيهم، ثم الله شهيد على ما يفعلون، وشهادته كافية في وجوب تعذيبهم. ولكل أمة رسول أُرسل إليها فأطاع من أطاع وعصى من عصى، فإذا جاء رسولهم في عرصات القيامة قُضي بينهم بالعدل وهم لا يُظلمون، لا بنقص حسنات المحسنين ولا بزيادة سيئات المسيئين. ويقول المشركون استعجالاً: متى هذا الوعد إن كنتم صادقين؟", "h": ["تقرير مبدأ المعاد والدار الآخرة.", "الإعلان عن خسران منكري البعث يوم القيامة.", "تسلية الرسول ﷺ وحمله على الصبر حتى يؤدّي رسالته، بإعلامه أنه سيعذّب أعداءه.", "بيان كيفية الحساب يوم القيامة: بأن يأتي الرسول وأمته ثم يجري الحساب بينهم، فينجّي الله المؤمنين ويعذّب الكافرين."], "k": "«كأن لم يلبثوا إلا ساعة من النهار»… عمري كله سيبدو ساعة؛ فكيف أنفق ما بقي منها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (136, 10, 49, 67, 'سورة يونس ٤٩ – ٦٧', '«قد جاءتكم موعظة من ربكم وشفاء لما في الصدور»، «ألا إن أولياء الله لا خوف عليهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 136) = $j$[{"lbl": "الآيات ٤٩ – ٥٣", "q": "قُل لَّآ أَمۡلِكُ لِنَفۡسِي ضَرّٗا وَلَا نَفۡعًا إِلَّا مَا شَآءَ ٱللَّهُۗ لِكُلِّ أُمَّةٍ أَجَلٌۚ إِذَا جَآءَ أَجَلُهُمۡ فَلَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ ﴿٤٩﴾ قُلۡ أَرَءَيۡتُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُهُۥ بَيَٰتًا أَوۡ نَهَارٗا مَّاذَا يَسۡتَعۡجِلُ مِنۡهُ ٱلۡمُجۡرِمُونَ ﴿٥٠﴾ أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓۚ ءَآلۡـَٰٔنَ وَقَدۡ كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ ﴿٥١﴾ ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ٱلۡخُلۡدِ هَلۡ تُجۡزَوۡنَ إِلَّا بِمَا كُنتُمۡ تَكۡسِبُونَ ﴿٥٢﴾ ۞وَيَسۡتَنۢبِـُٔونَكَ أَحَقٌّ هُوَۖ قُلۡ إِي وَرَبِّيٓ إِنَّهُۥ لَحَقّٞۖ وَمَآ أَنتُم بِمُعۡجِزِينَ ﴿٥٣﴾", "w": [["لنفسي ضراً", "لا أقدر على دفع الضر إذا لم يدفعه الله تعالى."], ["ولا نفعاً", "لا أقدر أن أجلب لنفسي نفعاً إذا لم يُرده الله تعالى لي."], ["ولا يستقدمون", "أي عليه ساعة."], ["قل أرأيتم", "قل لهم: أخبروني."], ["بياتاً", "ليلاً."], ["أثمّ إذا ما وقع", "أي حلّ العذاب."], ["عذاب الخلد", "الذي يخلدون فيه فلا يخرجون منه."], ["ويستنبئونك", "ويستخبرونك."]], "m": "طالب المشركون بالعذاب فقالوا: متى هذا الوعد؟ فأمر الله رسوله أن يقول: لا أملك لنفسي ضراً أدفعه ولا نفعاً أجلبه إلا ما شاء الله، فكيف أعلم الغيب وأعرف متى يأتيكم العذاب، أو أقدر على تعجيله؟ لكل أمة أجل محدّد لهلاكها، إذا جاء أجلهم فلا يستأخرون ساعة ولا يستقدمون، فلا معنى لمطالبتكم بالعذاب. قل: أخبروني إن أتاكم عذابه بياتاً أو نهاراً، أتطيقونه؟ ماذا يستعجل منه المجرمون؟ إنكم تستعجلون أمراً عظيماً. أثمّ إذا ما وقع آمنتم به؟ وهل ينفعكم الإيمان يومئذ؟ فيقال لكم: آلآن وقد كنتم به تستعجلون؟ ثم قيل للذين ظلموا أنفسهم بالشرك: ذوقوا تهكّماً عذاب الخلد الذي لا يفنى، هل تُجزون إلا بما كنتم تكسبون؟ ويستنبئونك: أحق ما تعدنا به من العذاب؟ قل: إي وربي إنه لحق، وما أنتم بمعجزين لله ولا فائتيه.", "h": ["لا يملك أحد من الخلق لنفسه فضلاً عن غيره ضراً يدفعه ولا نفعاً يجلبه إلا بإذن الله ومشيئته، وخاب الذين يعوّلون على الأولياء في جلب النفع لهم ودفع الشر عنهم.", "الآجال محدودة لا تتقدّم ولا تتأخّر، فلذا لا معنى للجبن من العبد.", "لا ينفع الإيمان ولا التوبة عند معاينة العذاب أو ملك الموت.", "جواز الحلف بالله إذا أُريد تأكيد الخبر.", "«إي» حرف إجابة، ويقترن دائماً بالقسم، نحو: إي والله، إي وربي."], "k": "«قل لا أملك لنفسي ضراً ولا نفعاً إلا ما شاء الله»… فممّن أرجو النفع، وممّن أخاف الضر؟"}, {"lbl": "الآيات ٥٤ – ٥٨", "q": "وَلَوۡ أَنَّ لِكُلِّ نَفۡسٖ ظَلَمَتۡ مَا فِي ٱلۡأَرۡضِ لَٱفۡتَدَتۡ بِهِۦۗ وَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۖ وَقُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ ﴿٥٤﴾ أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ أَلَآ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٥٥﴾ هُوَ يُحۡيِۦ وَيُمِيتُ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٥٦﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةٞ مِّن رَّبِّكُمۡ وَشِفَآءٞ لِّمَا فِي ٱلصُّدُورِ وَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ﴿٥٧﴾ قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ هُوَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ ﴿٥٨﴾", "w": [["لافتدت به", "لقدّمته فداءً لها."], ["وأسرّوا الندامة", "أخفوها في أنفسهم على ترك الإيمان والعمل الصالح."], ["وقُضي بينهم بالقسط", "حكم الله بينهم بالعدل."], ["وعد الله حق", "ما يعدهم الله به كائن حقاً."], ["موعظة من ربكم", "وصية من ربكم بالحق والخير، وباجتناب الشرك والشر."], ["وهدى", "بيان لطريق الحق والخير من طريق الباطل والشر."], ["بفضل الله وبرحمته", "ما هداهم إليه من الإيمان والعمل الصالح واجتناب الشرك والمعاصي."], ["فبذلك فليفرحوا", "فبالإيمان والعمل الصالح بعد العلم والتقوى فليُسرّوا."]], "m": "ما زال السياق في أن العذاب آتٍ لا محالة، وأنه لا يطاق: ولو أن لكل نفس ظلمت بالشرك والمعاصي ما في الأرض لافتدت به لشدة العذاب، وأسرّوا الندامة في صدورهم لما رأوا العذاب، ندماً شديداً على عدم إيمانهم، وقُضي بينهم بالعدل وهم لا يُظلمون. ألا إن لله ما في السماوات والأرض ملكاً حقيقياً يتصرّف فيه كما يشاء، ألا إن وعد الله حق، ولكن أكثرهم لا يعلمون، ولو علموا ما كفروا، هو يحيي ويميت وإليه تُرجعون. وبعد تقرير قضايا العقيدة الثلاث نادى الناس عرباً وعجماً: يا أيها الناس قد جاءتكم موعظة من ربكم بالأمر والنهي ترغيباً وترهيباً، وشفاء لما في الصدور من الشرك والكفر، وهدى ورحمة للمؤمنين، قد حواها القرآن، ففيكم الجاهل والفاسق والمريض بالشرك، فآمنوا به وتداووا به واهتدوا بنوره تُشفوا وتكملوا وتسعدوا في الحياتين. قل بفضل الله وبرحمته، الإسلام وشرائعه والقرآن وعلومه، فبذلك فليفرحوا، هو خير مما يجمعون من حطام الدنيا الفاني.", "h": ["عظم عذاب يوم القيامة، حتى إن الكافر ليودّ أن يفتدي منه بما في الأرض جميعاً.", "تقرير ربوبية الله تعالى لسائر المخلوقات في العالمين العلوي والسفلي.", "الإشادة بفضل القرآن وعظمته لما يحمله من المواعظ والهدى والرحمة والشفاء.", "يُستحب الفرح بالدين، ويُكره الفرح بالدنيا."], "k": "«قل بفضل الله وبرحمته فبذلك فليفرحوا»… بماذا فرحت اليوم: بدنيا جمعتها، أم بطاعة وُفّقت لها؟"}, {"lbl": "الآيات ٥٩ – ٦١", "q": "قُلۡ أَرَءَيۡتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقٖ فَجَعَلۡتُم مِّنۡهُ حَرَامٗا وَحَلَٰلٗا قُلۡ ءَآللَّهُ أَذِنَ لَكُمۡۖ أَمۡ عَلَى ٱللَّهِ تَفۡتَرُونَ ﴿٥٩﴾ وَمَا ظَنُّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ يَوۡمَ ٱلۡقِيَٰمَةِۗ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ ﴿٦٠﴾ وَمَا تَكُونُ فِي شَأۡنٖ وَمَا تَتۡلُواْ مِنۡهُ مِن قُرۡءَانٖ وَلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُنَّا عَلَيۡكُمۡ شُهُودًا إِذۡ تُفِيضُونَ فِيهِۚ وَمَا يَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ وَلَآ أَصۡغَرَ مِن ذَٰلِكَ وَلَآ أَكۡبَرَ إِلَّا فِي كِتَٰبٖ مُّبِينٍ ﴿٦١﴾", "w": [["أرأيتم", "أخبروني."], ["ما أنزل الله لكم من رزق", "الذي خلق لكم من رزق، كلحوم الأنعام والحرث."], ["تفيضون فيه", "تأخذون فيه وتشرعون."], ["وما يعزب عن ربك", "وما يغيب."], ["من مثقال ذرة", "وزن ذرة، والذرة أصغر نملة."]], "m": "سياق الآيات في تقرير الوحي وإلزام منكريه بالدليل العقلي: قل لهؤلاء المشركين: أخبروني عما أنزل الله لكم من رزق، من نبات وطعام وحرث، فجعلتم منه حراماً كالبحيرة والسائبة والحرث الذي جعلتموه لآلهتكم، وحلالاً كالميتة، آلله أذن لكم بوحي منه، أم على الله تفترون؟ فإن قلتم أذن لنا بوحي فلِمَ تنكرون الوحي؟ وإن قلتم لا وحي، فقد افتريتم على الله الكذب. وما ظن الذين يفترون على الله الكذب يوم القيامة إذا وقفوا بين يديه، أيُغفر لهم؟ لا، بل يُلعنون وفي النار هم خالدون. إن الله لذو فضل على الناس إذ لا يعجّل لهم العقوبة وهم يكذبون عليه، ولكن أكثرهم لا يشكرون لجهلهم وسوء تربيتهم. وما تكون يا رسولنا في شأن من أمورك، وما تتلو منه من قرآن، ولا تعملون من عمل، إلا كنا عليكم شهوداً حاضرين إذ تفيضون فيه، وما يعزب عن ربك من وزن ذرة، أصغر نملة، في الأرض ولا في السماء، ولا أصغر من ذلك ولا أكبر إلا في كتاب مبين، اللوح المحفوظ، فلهذا العلم والقدرة والرحمة استوجب العبادة دون خلقه.", "h": ["تقرير الوحي وإثباته للنبي ﷺ.", "التحريم والتحليل من حق الله تعالى دون سائر خلقه.", "حرمة الكذب على الله، وأن صاحبه مستوجب للعذاب.", "ما أعظم نعم الله تعالى على العباد، ومع هذا فهم لا يشكرون إلا القليل منهم.", "وجوب مراقبة الله تعالى، وحرمة الغفلة في ذلك.", "إثبات اللوح المحفوظ وتقريره كما صرّحت به الآيات والأحاديث."], "k": "«إلا كنا عليكم شهوداً إذ تفيضون فيه»… ما أعمله الآن، ربي شاهد عليه؛ فهل أُحسنه؟"}, {"lbl": "الآيات ٦٢ – ٦٤", "q": "أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٦٢﴾ ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ ﴿٦٣﴾ لَهُمُ ٱلۡبُشۡرَىٰ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ لَا تَبۡدِيلَ لِكَلِمَٰتِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٦٤﴾", "w": [["ألا", "أداة استفتاح وتنبيه."], ["إن أولياء الله", "جمع ولي، وهو المؤمن التقي، بشرط أن يكون إيمانه وتقواه على نور من الكتاب والسنة."], ["لا خوف عليهم", "لا يخافون عند الموت ولا بعده، ولا هم يحزنون على ما تركوا وراءهم."], ["آمنوا", "صدّقوا بالله وبما جاء عن الله، وبرسول الله وبما أخبر به رسول الله."], ["يتقون", "ما يسخط الله تعالى من ترك واجب أو فعل حرام."], ["لهم البشرى", "بالجنة في القرآن الكريم، وعند الموت، وبالرؤيا الصالحة يراها أو تُرى له."], ["لا تبديل لكلمات الله", "لوعده الذي يعده عباده الصالحين، لأن الوعد بالكلمة، وكلمة الله لا تتبدّل."], ["الفوز", "النجاة من النار ودخول الجنة."]], "m": "يخبر الله، مؤكّداً بأداة التنبيه «ألا» وأداة التوكيد «إن»: ألا إن أولياء الله لا خوف عليهم عند الموت ولا في البرزخ ولا يوم القيامة، ولا هم يحزنون على ما يتركون وراءهم، وعرّف بهم: الذين آمنوا بالله ورسوله وبكل ما جاء به، وكانوا يتقون طوال حياتهم سخط الله، فلا يتركون واجباً يقدرون عليه، ولا يغشون محرّماً لم يُكرهوا عليه. لهم البشرى في الحياة الدنيا: في كتاب ربهم برضوانه والجنة، وعند الاحتضار تبشّرهم الملائكة، وفي الآخرة عند قيامهم من قبورهم تتلقّاهم الملائكة بالبشرى، لا تبديل لكلمات الله، فوعده لا يتخلّف، ذلك هو الفوز العظيم.", "h": ["ولاية الله تعالى تكون بطاعته وموافقته في محابّه ومكارهه، فمن آمن إيماناً يرضاه الله، واتقى الله في أداء الفرائض واجتناب المناهي، فقد صار ولي الله والله وليه.", "البشرى هي ما يكرم الله به، كرؤيا صالحة يراها الولي أو تُرى له.", "الأولياء هم أهل الإيمان والتقوى، فالكافر والفاجر لا يكون ولياً أبداً، إلا إذا آمن الكافر، وبرّ الفاجر بفعل الصالحات وترك المنهيات.", "صدق إخبار الله تعالى وعدالة أحكامه، وسر ولايته أنها تدور على موافقة الرب تعالى فيما يحب وفيما يكره، فمن وافق ربه فقد والاه، ومن خالفه فقد عاداه."], "k": "«الذين آمنوا وكانوا يتقون»… الولاية ليست كرامات تُرى، بل إيمان وتقوى؛ فهل أسير في طريقها؟"}, {"lbl": "الآيات ٦٥ – ٦٧", "q": "وَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعًاۚ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٦٥﴾ أَلَآ إِنَّ لِلَّهِ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ ﴿٦٦﴾ هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ ﴿٦٧﴾", "w": [["إلا الظن", "الظن أضعف الشك."], ["يخرصون", "يحزرون ويكذبون."], ["لتسكنوا فيه", "تخلدوا فيه إلى الراحة والسكون عن الحركة."], ["مبصراً", "مضيئاً تُرى فيه الأشياء كلها."], ["في ذلك", "في جعله تعالى الليل سكناً والنهار مبصراً."], ["يسمعون", "سماع إجابة وقبول."]], "m": "ما زال السياق في تقرير التوحيد والنبوة والبعث: ولا يحزنك قول المشركين: لست مرسلاً، وإنك شاعر مجنون، فقولهم لا ينتج لهم إلا سوء العاقبة، إن العزة لله جميعاً، فربك القوي سيهزمهم وينصرك، هو السميع لأقوالهم العليم بأحوالهم. ألا إن لله من في السماوات ومن في الأرض خلقاً وملكاً وتصرّفاً، فكيف تبالي بهم؟ وما يتبع الذين يدعون من دون الله شركاء تستحق العبادة، إن يتبعون إلا الظن، وإن هم إلا يخرصون ويكذبون. هو الإله الحق الذي جعل لكم الليل مظلماً لتسكنوا فيه فتستريحوا من عناء العمل، والنهار مبصراً لتتمكّنوا من العمل فيه، إن في ذلك لآيات على أنه لا إله إلا هو، لقوم يسمعون سماع قبول واستجابة، لا من يسمع الصوت ولا يتدبّر معانيه.", "h": ["على المؤمن الداعي إلى الله تعالى ألّا تحزنه أقوال أهل الباطل وأكاذيبهم حتى لا ينقطع عن دعوته، وليعلم أن العزة لله جميعاً وسوف يعزّه بها ويذلّ أعداءه.", "ما يُعبد من دون الله لم يُقم عليه عابدوه أي دليل، ولا يملكون له حجة، وإنما هم مقلّدون يتبعون الظنون والأوهام.", "مظاهر قدرة الله تعالى في الخلق والتدبير كافية في إثبات العبادة له ونفيها عما سواه."], "k": "«ولا يحزنك قولهم إن العزة لله جميعاً»… كلمة جارحة قيلت فيّ؛ هل أطلب العزة من ربي لا من ردّي عليها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 136;
insert into public.tdb_cards(topic, i, body) select 136, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٩ – ٥٣", "q": "قُل لَّآ أَمۡلِكُ لِنَفۡسِي ضَرّٗا وَلَا نَفۡعًا إِلَّا مَا شَآءَ ٱللَّهُۗ لِكُلِّ أُمَّةٍ أَجَلٌۚ إِذَا جَآءَ أَجَلُهُمۡ فَلَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ ﴿٤٩﴾ قُلۡ أَرَءَيۡتُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُهُۥ بَيَٰتًا أَوۡ نَهَارٗا مَّاذَا يَسۡتَعۡجِلُ مِنۡهُ ٱلۡمُجۡرِمُونَ ﴿٥٠﴾ أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓۚ ءَآلۡـَٰٔنَ وَقَدۡ كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ ﴿٥١﴾ ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ٱلۡخُلۡدِ هَلۡ تُجۡزَوۡنَ إِلَّا بِمَا كُنتُمۡ تَكۡسِبُونَ ﴿٥٢﴾ ۞وَيَسۡتَنۢبِـُٔونَكَ أَحَقٌّ هُوَۖ قُلۡ إِي وَرَبِّيٓ إِنَّهُۥ لَحَقّٞۖ وَمَآ أَنتُم بِمُعۡجِزِينَ ﴿٥٣﴾", "w": [["لنفسي ضراً", "لا أقدر على دفع الضر إذا لم يدفعه الله تعالى."], ["ولا نفعاً", "لا أقدر أن أجلب لنفسي نفعاً إذا لم يُرده الله تعالى لي."], ["ولا يستقدمون", "أي عليه ساعة."], ["قل أرأيتم", "قل لهم: أخبروني."], ["بياتاً", "ليلاً."], ["أثمّ إذا ما وقع", "أي حلّ العذاب."], ["عذاب الخلد", "الذي يخلدون فيه فلا يخرجون منه."], ["ويستنبئونك", "ويستخبرونك."]], "m": "طالب المشركون بالعذاب فقالوا: متى هذا الوعد؟ فأمر الله رسوله أن يقول: لا أملك لنفسي ضراً أدفعه ولا نفعاً أجلبه إلا ما شاء الله، فكيف أعلم الغيب وأعرف متى يأتيكم العذاب، أو أقدر على تعجيله؟ لكل أمة أجل محدّد لهلاكها، إذا جاء أجلهم فلا يستأخرون ساعة ولا يستقدمون، فلا معنى لمطالبتكم بالعذاب. قل: أخبروني إن أتاكم عذابه بياتاً أو نهاراً، أتطيقونه؟ ماذا يستعجل منه المجرمون؟ إنكم تستعجلون أمراً عظيماً. أثمّ إذا ما وقع آمنتم به؟ وهل ينفعكم الإيمان يومئذ؟ فيقال لكم: آلآن وقد كنتم به تستعجلون؟ ثم قيل للذين ظلموا أنفسهم بالشرك: ذوقوا تهكّماً عذاب الخلد الذي لا يفنى، هل تُجزون إلا بما كنتم تكسبون؟ ويستنبئونك: أحق ما تعدنا به من العذاب؟ قل: إي وربي إنه لحق، وما أنتم بمعجزين لله ولا فائتيه.", "h": ["لا يملك أحد من الخلق لنفسه فضلاً عن غيره ضراً يدفعه ولا نفعاً يجلبه إلا بإذن الله ومشيئته، وخاب الذين يعوّلون على الأولياء في جلب النفع لهم ودفع الشر عنهم.", "الآجال محدودة لا تتقدّم ولا تتأخّر، فلذا لا معنى للجبن من العبد.", "لا ينفع الإيمان ولا التوبة عند معاينة العذاب أو ملك الموت.", "جواز الحلف بالله إذا أُريد تأكيد الخبر.", "«إي» حرف إجابة، ويقترن دائماً بالقسم، نحو: إي والله، إي وربي."], "k": "«قل لا أملك لنفسي ضراً ولا نفعاً إلا ما شاء الله»… فممّن أرجو النفع، وممّن أخاف الضر؟"}, {"lbl": "الآيات ٥٤ – ٥٨", "q": "وَلَوۡ أَنَّ لِكُلِّ نَفۡسٖ ظَلَمَتۡ مَا فِي ٱلۡأَرۡضِ لَٱفۡتَدَتۡ بِهِۦۗ وَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۖ وَقُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ ﴿٥٤﴾ أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ أَلَآ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٥٥﴾ هُوَ يُحۡيِۦ وَيُمِيتُ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٥٦﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةٞ مِّن رَّبِّكُمۡ وَشِفَآءٞ لِّمَا فِي ٱلصُّدُورِ وَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ﴿٥٧﴾ قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ هُوَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ ﴿٥٨﴾", "w": [["لافتدت به", "لقدّمته فداءً لها."], ["وأسرّوا الندامة", "أخفوها في أنفسهم على ترك الإيمان والعمل الصالح."], ["وقُضي بينهم بالقسط", "حكم الله بينهم بالعدل."], ["وعد الله حق", "ما يعدهم الله به كائن حقاً."], ["موعظة من ربكم", "وصية من ربكم بالحق والخير، وباجتناب الشرك والشر."], ["وهدى", "بيان لطريق الحق والخير من طريق الباطل والشر."], ["بفضل الله وبرحمته", "ما هداهم إليه من الإيمان والعمل الصالح واجتناب الشرك والمعاصي."], ["فبذلك فليفرحوا", "فبالإيمان والعمل الصالح بعد العلم والتقوى فليُسرّوا."]], "m": "ما زال السياق في أن العذاب آتٍ لا محالة، وأنه لا يطاق: ولو أن لكل نفس ظلمت بالشرك والمعاصي ما في الأرض لافتدت به لشدة العذاب، وأسرّوا الندامة في صدورهم لما رأوا العذاب، ندماً شديداً على عدم إيمانهم، وقُضي بينهم بالعدل وهم لا يُظلمون. ألا إن لله ما في السماوات والأرض ملكاً حقيقياً يتصرّف فيه كما يشاء، ألا إن وعد الله حق، ولكن أكثرهم لا يعلمون، ولو علموا ما كفروا، هو يحيي ويميت وإليه تُرجعون. وبعد تقرير قضايا العقيدة الثلاث نادى الناس عرباً وعجماً: يا أيها الناس قد جاءتكم موعظة من ربكم بالأمر والنهي ترغيباً وترهيباً، وشفاء لما في الصدور من الشرك والكفر، وهدى ورحمة للمؤمنين، قد حواها القرآن، ففيكم الجاهل والفاسق والمريض بالشرك، فآمنوا به وتداووا به واهتدوا بنوره تُشفوا وتكملوا وتسعدوا في الحياتين. قل بفضل الله وبرحمته، الإسلام وشرائعه والقرآن وعلومه، فبذلك فليفرحوا، هو خير مما يجمعون من حطام الدنيا الفاني.", "h": ["عظم عذاب يوم القيامة، حتى إن الكافر ليودّ أن يفتدي منه بما في الأرض جميعاً.", "تقرير ربوبية الله تعالى لسائر المخلوقات في العالمين العلوي والسفلي.", "الإشادة بفضل القرآن وعظمته لما يحمله من المواعظ والهدى والرحمة والشفاء.", "يُستحب الفرح بالدين، ويُكره الفرح بالدنيا."], "k": "«قل بفضل الله وبرحمته فبذلك فليفرحوا»… بماذا فرحت اليوم: بدنيا جمعتها، أم بطاعة وُفّقت لها؟"}, {"lbl": "الآيات ٥٩ – ٦١", "q": "قُلۡ أَرَءَيۡتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقٖ فَجَعَلۡتُم مِّنۡهُ حَرَامٗا وَحَلَٰلٗا قُلۡ ءَآللَّهُ أَذِنَ لَكُمۡۖ أَمۡ عَلَى ٱللَّهِ تَفۡتَرُونَ ﴿٥٩﴾ وَمَا ظَنُّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ يَوۡمَ ٱلۡقِيَٰمَةِۗ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ ﴿٦٠﴾ وَمَا تَكُونُ فِي شَأۡنٖ وَمَا تَتۡلُواْ مِنۡهُ مِن قُرۡءَانٖ وَلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُنَّا عَلَيۡكُمۡ شُهُودًا إِذۡ تُفِيضُونَ فِيهِۚ وَمَا يَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ وَلَآ أَصۡغَرَ مِن ذَٰلِكَ وَلَآ أَكۡبَرَ إِلَّا فِي كِتَٰبٖ مُّبِينٍ ﴿٦١﴾", "w": [["أرأيتم", "أخبروني."], ["ما أنزل الله لكم من رزق", "الذي خلق لكم من رزق، كلحوم الأنعام والحرث."], ["تفيضون فيه", "تأخذون فيه وتشرعون."], ["وما يعزب عن ربك", "وما يغيب."], ["من مثقال ذرة", "وزن ذرة، والذرة أصغر نملة."]], "m": "سياق الآيات في تقرير الوحي وإلزام منكريه بالدليل العقلي: قل لهؤلاء المشركين: أخبروني عما أنزل الله لكم من رزق، من نبات وطعام وحرث، فجعلتم منه حراماً كالبحيرة والسائبة والحرث الذي جعلتموه لآلهتكم، وحلالاً كالميتة، آلله أذن لكم بوحي منه، أم على الله تفترون؟ فإن قلتم أذن لنا بوحي فلِمَ تنكرون الوحي؟ وإن قلتم لا وحي، فقد افتريتم على الله الكذب. وما ظن الذين يفترون على الله الكذب يوم القيامة إذا وقفوا بين يديه، أيُغفر لهم؟ لا، بل يُلعنون وفي النار هم خالدون. إن الله لذو فضل على الناس إذ لا يعجّل لهم العقوبة وهم يكذبون عليه، ولكن أكثرهم لا يشكرون لجهلهم وسوء تربيتهم. وما تكون يا رسولنا في شأن من أمورك، وما تتلو منه من قرآن، ولا تعملون من عمل، إلا كنا عليكم شهوداً حاضرين إذ تفيضون فيه، وما يعزب عن ربك من وزن ذرة، أصغر نملة، في الأرض ولا في السماء، ولا أصغر من ذلك ولا أكبر إلا في كتاب مبين، اللوح المحفوظ، فلهذا العلم والقدرة والرحمة استوجب العبادة دون خلقه.", "h": ["تقرير الوحي وإثباته للنبي ﷺ.", "التحريم والتحليل من حق الله تعالى دون سائر خلقه.", "حرمة الكذب على الله، وأن صاحبه مستوجب للعذاب.", "ما أعظم نعم الله تعالى على العباد، ومع هذا فهم لا يشكرون إلا القليل منهم.", "وجوب مراقبة الله تعالى، وحرمة الغفلة في ذلك.", "إثبات اللوح المحفوظ وتقريره كما صرّحت به الآيات والأحاديث."], "k": "«إلا كنا عليكم شهوداً إذ تفيضون فيه»… ما أعمله الآن، ربي شاهد عليه؛ فهل أُحسنه؟"}, {"lbl": "الآيات ٦٢ – ٦٤", "q": "أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٦٢﴾ ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ ﴿٦٣﴾ لَهُمُ ٱلۡبُشۡرَىٰ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ لَا تَبۡدِيلَ لِكَلِمَٰتِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٦٤﴾", "w": [["ألا", "أداة استفتاح وتنبيه."], ["إن أولياء الله", "جمع ولي، وهو المؤمن التقي، بشرط أن يكون إيمانه وتقواه على نور من الكتاب والسنة."], ["لا خوف عليهم", "لا يخافون عند الموت ولا بعده، ولا هم يحزنون على ما تركوا وراءهم."], ["آمنوا", "صدّقوا بالله وبما جاء عن الله، وبرسول الله وبما أخبر به رسول الله."], ["يتقون", "ما يسخط الله تعالى من ترك واجب أو فعل حرام."], ["لهم البشرى", "بالجنة في القرآن الكريم، وعند الموت، وبالرؤيا الصالحة يراها أو تُرى له."], ["لا تبديل لكلمات الله", "لوعده الذي يعده عباده الصالحين، لأن الوعد بالكلمة، وكلمة الله لا تتبدّل."], ["الفوز", "النجاة من النار ودخول الجنة."]], "m": "يخبر الله، مؤكّداً بأداة التنبيه «ألا» وأداة التوكيد «إن»: ألا إن أولياء الله لا خوف عليهم عند الموت ولا في البرزخ ولا يوم القيامة، ولا هم يحزنون على ما يتركون وراءهم، وعرّف بهم: الذين آمنوا بالله ورسوله وبكل ما جاء به، وكانوا يتقون طوال حياتهم سخط الله، فلا يتركون واجباً يقدرون عليه، ولا يغشون محرّماً لم يُكرهوا عليه. لهم البشرى في الحياة الدنيا: في كتاب ربهم برضوانه والجنة، وعند الاحتضار تبشّرهم الملائكة، وفي الآخرة عند قيامهم من قبورهم تتلقّاهم الملائكة بالبشرى، لا تبديل لكلمات الله، فوعده لا يتخلّف، ذلك هو الفوز العظيم.", "h": ["ولاية الله تعالى تكون بطاعته وموافقته في محابّه ومكارهه، فمن آمن إيماناً يرضاه الله، واتقى الله في أداء الفرائض واجتناب المناهي، فقد صار ولي الله والله وليه.", "البشرى هي ما يكرم الله به، كرؤيا صالحة يراها الولي أو تُرى له.", "الأولياء هم أهل الإيمان والتقوى، فالكافر والفاجر لا يكون ولياً أبداً، إلا إذا آمن الكافر، وبرّ الفاجر بفعل الصالحات وترك المنهيات.", "صدق إخبار الله تعالى وعدالة أحكامه، وسر ولايته أنها تدور على موافقة الرب تعالى فيما يحب وفيما يكره، فمن وافق ربه فقد والاه، ومن خالفه فقد عاداه."], "k": "«الذين آمنوا وكانوا يتقون»… الولاية ليست كرامات تُرى، بل إيمان وتقوى؛ فهل أسير في طريقها؟"}, {"lbl": "الآيات ٦٥ – ٦٧", "q": "وَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعًاۚ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٦٥﴾ أَلَآ إِنَّ لِلَّهِ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ ﴿٦٦﴾ هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ ﴿٦٧﴾", "w": [["إلا الظن", "الظن أضعف الشك."], ["يخرصون", "يحزرون ويكذبون."], ["لتسكنوا فيه", "تخلدوا فيه إلى الراحة والسكون عن الحركة."], ["مبصراً", "مضيئاً تُرى فيه الأشياء كلها."], ["في ذلك", "في جعله تعالى الليل سكناً والنهار مبصراً."], ["يسمعون", "سماع إجابة وقبول."]], "m": "ما زال السياق في تقرير التوحيد والنبوة والبعث: ولا يحزنك قول المشركين: لست مرسلاً، وإنك شاعر مجنون، فقولهم لا ينتج لهم إلا سوء العاقبة، إن العزة لله جميعاً، فربك القوي سيهزمهم وينصرك، هو السميع لأقوالهم العليم بأحوالهم. ألا إن لله من في السماوات ومن في الأرض خلقاً وملكاً وتصرّفاً، فكيف تبالي بهم؟ وما يتبع الذين يدعون من دون الله شركاء تستحق العبادة، إن يتبعون إلا الظن، وإن هم إلا يخرصون ويكذبون. هو الإله الحق الذي جعل لكم الليل مظلماً لتسكنوا فيه فتستريحوا من عناء العمل، والنهار مبصراً لتتمكّنوا من العمل فيه، إن في ذلك لآيات على أنه لا إله إلا هو، لقوم يسمعون سماع قبول واستجابة، لا من يسمع الصوت ولا يتدبّر معانيه.", "h": ["على المؤمن الداعي إلى الله تعالى ألّا تحزنه أقوال أهل الباطل وأكاذيبهم حتى لا ينقطع عن دعوته، وليعلم أن العزة لله جميعاً وسوف يعزّه بها ويذلّ أعداءه.", "ما يُعبد من دون الله لم يُقم عليه عابدوه أي دليل، ولا يملكون له حجة، وإنما هم مقلّدون يتبعون الظنون والأوهام.", "مظاهر قدرة الله تعالى في الخلق والتدبير كافية في إثبات العبادة له ونفيها عما سواه."], "k": "«ولا يحزنك قولهم إن العزة لله جميعاً»… كلمة جارحة قيلت فيّ؛ هل أطلب العزة من ربي لا من ردّي عليها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (137, 10, 68, 82, 'سورة يونس ٦٨ – ٨٢', '«قالوا اتخذ الله ولداً سبحانه هو الغني»، ونبأ نوح، وموسى ﵇ مع السحرة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 137) = $j$[{"lbl": "الآيات ٦٨ – ٧٠", "q": "قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ هُوَ ٱلۡغَنِيُّۖ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ إِنۡ عِندَكُم مِّن سُلۡطَٰنِۭ بِهَٰذَآۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٦٨﴾ قُلۡ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ ﴿٦٩﴾ مَتَٰعٞ فِي ٱلدُّنۡيَا ثُمَّ إِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ نُذِيقُهُمُ ٱلۡعَذَابَ ٱلشَّدِيدَ بِمَا كَانُواْ يَكۡفُرُونَ ﴿٧٠﴾", "w": [["سبحانه", "أي تنزّه عن النقص وتعالى أن يكون له ولد."], ["الغني", "الغني المطلق بحيث لا يفتقر إلى شيء."], ["إن عندكم من سلطان", "ما عندكم من حجة ولا برهان."], ["بهذا", "أي الذي تقولونه، وهو نسبة الولد إليه تعالى."], ["متاع في الدنيا", "ما هم فيه اليوم متاع لا غير، وسوف يموتون ويخسرون كل شيء."], ["بما كانوا يكفرون", "بنسبة الولد إلى الله تعالى، وبعبادتهم غير الله سبحانه."]], "m": "ما زال السياق في تقرير التوحيد بإبطال الشرك وشبهه: قال المشركون: إن الملائكة بنات الله، فنزّه الله نفسه عن هذا الكذب، وأقام الحجة على بطلانه بأنه هو الغني الذي لا يفتقر إلى غيره، فكيف يحتاج إلى ولد؟ وبرهان آخر: أن له ما في السماوات وما في الأرض خلقاً وملكاً، فهل يُعقل أن يتخذ المالك عبداً من عبيده ولداً له؟ ثم: هل عندكم حجة على ما تقولون؟ لا، أتقولون على الله ما لا تعلمون؟ قل: إن الذين يفترون على الله الكذب لا يفلحون. وإن قيل: كيف لا يفلحون وهم يتمتعون بالأموال والأولاد والجاه؟ فالجواب: ذلك متاع في الدنيا إلى نهاية أعمارهم، ثم إلينا مرجعهم، ثم نذيقهم العذاب الشديد الذي ينسون معه كل ما تمتعوا به، بما كانوا يكفرون، أي يجحدون كمال الله وغناه فينسبون إليه الولد والشريك.", "h": ["كفر من ينسب إلى الله تعالى أي نقص، كالولد والشريك أو العجز مطلقاً.", "كل دعوى لا يقيم لها صاحبها برهاناً قاطعاً وحجة واضحة فلا قيمة لها ولا يُحفل بها.", "أهل الكذب على الله، كالدجالين والسحرة وأهل البدع والخرافات، لا يفلحون، ونهايتهم الخسران.", "لا ينبغي للمؤمن أن يغتر بما يرى عليه أهل الباطل والشر من المتع وسعة الرزق وصحة البدن، فإن ذلك متاع الحياة الدنيا، ثم يؤول أمرهم إلى خسران دائم."], "k": "«متاع في الدنيا ثم إلينا مرجعهم»… ما أراه في يد غيري من متاع، هل أقيسه بميزان الآخرة؟"}, {"lbl": "الآيات ٧١ – ٧٣", "q": "۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِهِۦ يَٰقَوۡمِ إِن كَانَ كَبُرَ عَلَيۡكُم مَّقَامِي وَتَذۡكِيرِي بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلۡتُ فَأَجۡمِعُوٓاْ أَمۡرَكُمۡ وَشُرَكَآءَكُمۡ ثُمَّ لَا يَكُنۡ أَمۡرُكُمۡ عَلَيۡكُمۡ غُمَّةٗ ثُمَّ ٱقۡضُوٓاْ إِلَيَّ وَلَا تُنظِرُونِ ﴿٧١﴾ فَإِن تَوَلَّيۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ ﴿٧٢﴾ فَكَذَّبُوهُ فَنَجَّيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ وَجَعَلۡنَٰهُمۡ خَلَـٰٓئِفَ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ ﴿٧٣﴾", "w": [["واتل عليهم نبأ نوح", "اقرأ على المشركين خبر نوح العظيم الخطير."], ["كبر عليكم مقامي", "عظم عليكم مقامي بينكم أدعو إلى ربي."], ["فأجمعوا أمركم", "اعزموا عزماً أكيداً."], ["غمة", "خفاءً ولبساً لا تهتدون منه إلى ما تريدون."], ["ثم اقضوا إلي", "أنفذوا أمركم."], ["ولا تُنظرون", "ولا تمهلوني رحمةً بي أو شفقةً عليّ."], ["فإن توليتم", "أعرضتم عما أدعوكم إليه من التوحيد."], ["في الفلك", "في السفينة."], ["خلائف", "يخلف الآخِر الأول جيلاً بعد جيل."]], "m": "يأمر الله رسوله ﷺ أن يقرأ على المشركين طرفاً من قصة نوح ﵇ مع قومه، وكانت حالهم كحال مشركي العرب سواءً بسواء، وفي ذلك فائدتان: تسلية الرسول ﷺ وحمله على الصبر، وتنبيه المشركين إلى خطئهم. قال نوح: يا قوم، إن كان عظم عليكم مقامي بينكم أدعوكم إلى الله وأذكّركم بآياته، فإني توكلت على الله، فاعزموا أمركم وادعوا شركاءكم، ثم لا يكن أمركم عليكم خفياً ملتبساً فتترددوا، ثم أنفذوا ما تريدون من قتلي أو نفيي ولا تؤخروني. فإن أعرضتم عن دعوتي فما سألتكم عليه من أجر حتى تتولّوا، إن أجري إلا على الله الذي أرسلني، وأُمرت أن أكون من المسلمين له. فكذّبوه بعد دعوة زمناً غير قصير، فنجّيناه ومن معه في السفينة، وجعلناهم خلائف يخلف بعضهم بعضاً، وأغرقنا الذين كذّبوا بآياتنا، فانظر يا رسولنا كيف كان عاقبة المنذَرين الذين لم يقبلوا النصح: إغراق في الطوفان، ونار في جهنم، وخسران.", "h": ["تسلية الدعاة بمثل موقف نوح العظيم، إذ قال لقومه: أجمعوا أمركم ونفّذوا ما تريدون، إني توكلت على الله.", "ثمرة التوكل شجاعة واطمئنان نفس، وصبر وتحمّل مع مضاء عزيمة.", "دعوة الله لا ينبغي أن يأخذ الداعي عليها أجراً إلا للضرورة.", "بيان سوء عاقبة المكذبين بعد إنذارهم وتحذيرهم."], "k": "«فعلى الله توكلت»… قالها نوح وحده أمام قومه جميعاً؛ فما الذي أخافه أنا وربي حسبي؟"}, {"lbl": "الآيات ٧٤ – ٧٨", "q": "ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِۦ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ بِهِۦ مِن قَبۡلُۚ كَذَٰلِكَ نَطۡبَعُ عَلَىٰ قُلُوبِ ٱلۡمُعۡتَدِينَ ﴿٧٤﴾ ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ بِـَٔايَٰتِنَا فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ ﴿٧٥﴾ فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوٓاْ إِنَّ هَٰذَا لَسِحۡرٞ مُّبِينٞ ﴿٧٦﴾ قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلۡحَقِّ لَمَّا جَآءَكُمۡۖ أَسِحۡرٌ هَٰذَا وَلَا يُفۡلِحُ ٱلسَّـٰحِرُونَ ﴿٧٧﴾ قَالُوٓاْ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلۡكِبۡرِيَآءُ فِي ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِينَ ﴿٧٨﴾", "w": [["بالبينات", "بالحجج الواضحات على صدق دعوتهم، وما يدعون إليه من توحيد الله تعالى."], ["نطبع", "الطبع على القلب عبارة عن تراكم الذنوب عليه حتى لا يجد الإيمان إليه طريقاً."], ["المعتدين", "الذين تجاوزوا الحد في الظلم والاعتداء على حدود الشرع."], ["الحق", "الآيات التي جاء بها موسى ﵇، وهي تسع."], ["الكبرياء", "العلو والسيادة والملك على الناس."]], "m": "لما ذكر تعالى طرفاً من قصة نوح ﵇ وأبرز فيها مظهر التوكل ونصرة الله لأوليائه، ذكر سنة من سننه: ثم بعثنا من بعد نوح رسلاً إلى قومهم، كهود وصالح وإبراهيم ولوط وشعيب، فجاؤوهم بالحجج على صدقهم، فما كانوا ليؤمنوا بما كذّب به من سبقهم. كذلك نطبع على قلوب المعتدين: إذا أذنب العبد وواصل الذنب بلا توبة صار الذنب طبعاً من طباعه لا يمكنه التخلي عنه، فيُختم على قلبه، فلا يقبل الإيمان ولا يعرف معروفاً ولا ينكر منكراً. ثم بعثنا من بعدهم موسى وهارون إلى فرعون وملئه بآياتنا الدالّة على صحة مطلبهما: توحيد الله وإرسال بني إسرائيل معهما، فاستكبروا وكانوا قوماً مجرمين أفسدوا القلوب والعقول وسفكوا الدماء وعذّبوا الضعفاء. فلما بهرتهم المعجزات قالوا: إن هذا لسحر مبين، تخلّصاً من الهزيمة، فوبّخهم موسى: أتقولون للحق لما جاءكم سحر؟ لو كان سحراً فكيف أفلحتُ في إبطال سحركم، ولا يفلح الساحرون؟ فلما أفحمهم بالحجة قالوا مراوغين: أجئتنا لتصرفنا عما وجدنا عليه آباءنا، وتكون لكما السيادة والملك في الأرض؟ وما نحن لكما بمؤمنين.", "h": ["بيان سنة الله في البشر، وهي أن التوغّل في الشر والفساد والظلم يوجب الختم على القلوب، فيُحرم العبد الإيمان والهداية.", "ذم الاستكبار، وأنه سبب كثير من الإجرام.", "تقرير أن الساحر لا يفلح أبداً، ولا يفوز بمطلوب ولا ينجو من مرهوب.", "الاتهامات الكاذبة من شأن أهل الباطل والظلم والفساد."], "k": "«كذلك نطبع على قلوب المعتدين»… ذنب أواظب عليه بلا توبة؛ هل أنتبه قبل أن يصير طبعاً؟"}, {"lbl": "الآيات ٧٩ – ٨٢", "q": "وَقَالَ فِرۡعَوۡنُ ٱئۡتُونِي بِكُلِّ سَٰحِرٍ عَلِيمٖ ﴿٧٩﴾ فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ ﴿٨٠﴾ فَلَمَّآ أَلۡقَوۡاْ قَالَ مُوسَىٰ مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَيُبۡطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِينَ ﴿٨١﴾ وَيُحِقُّ ٱللَّهُ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ ﴿٨٢﴾", "w": [["ساحر عليم", "ذو سحر حقيقي له تأثير، عليم بالفن."], ["ألقوا", "ارموا في الميدان ما تريدون إلقاءه من ضروب السحر."], ["إن الله سيبطله", "يُظهر بطلانه أمام الناظرين من الناس."], ["ويحق الله الحق", "يقرّر الحق ويثبته."], ["بكلماته", "بأمره، إذ يقول للشيء: كن فيكون."], ["المجرمون", "أهل الإجرام على أنفسهم وعلى غيرهم، وهم الظلمة المفسدون."]], "m": "لما غلب موسى فرعونَ وملأه بالحجة، اتّهم فرعون موسى وهارون بأنهما يريدان الملك والسيادة، وكذب في ذلك، ثم أمر رجال دولته أن يحضروا له كل ساحر عليم ليباري موسى، فلما جاء السحرة قال لهم موسى: ألقوا ما أنتم ملقون، فألقوا حبالهم وعصيّهم، فقال موسى: ما جئتم به هو السحر، إن الله سيبطله، إن الله لا يصلح عمل المفسدين، ويحق الله الحق بكلماته ولو كره المجرمون. وألقى عصاه فإذا هي تلقف ما يأفكون، فوقع الحق وبطل ما كانوا يعملون.", "h": ["للسحر طرق يُتعلّم بها، وله علماء به، وتعلّمه حرام واستعماله حرام.", "حد الساحر القتل، لأنه إفساد في الأرض.", "جواز المبارزة للعدو والمباراة له إظهاراً للحق وإبطالاً للباطل.", "عاقبة الفساد وعمل أصحابه الخراب والدمار.", "متى قاوم الحقُّ الباطلَ انهزم الباطل وانتصر الحق بأمر الله تعالى ووعده الصادق."], "k": "«إن الله لا يصلح عمل المفسدين»… مهما بدا الباطل مبهراً، فهل أثق أن عاقبته البطلان؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 137;
insert into public.tdb_cards(topic, i, body) select 137, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٨ – ٧٠", "q": "قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ هُوَ ٱلۡغَنِيُّۖ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ إِنۡ عِندَكُم مِّن سُلۡطَٰنِۭ بِهَٰذَآۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٦٨﴾ قُلۡ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ ﴿٦٩﴾ مَتَٰعٞ فِي ٱلدُّنۡيَا ثُمَّ إِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ نُذِيقُهُمُ ٱلۡعَذَابَ ٱلشَّدِيدَ بِمَا كَانُواْ يَكۡفُرُونَ ﴿٧٠﴾", "w": [["سبحانه", "أي تنزّه عن النقص وتعالى أن يكون له ولد."], ["الغني", "الغني المطلق بحيث لا يفتقر إلى شيء."], ["إن عندكم من سلطان", "ما عندكم من حجة ولا برهان."], ["بهذا", "أي الذي تقولونه، وهو نسبة الولد إليه تعالى."], ["متاع في الدنيا", "ما هم فيه اليوم متاع لا غير، وسوف يموتون ويخسرون كل شيء."], ["بما كانوا يكفرون", "بنسبة الولد إلى الله تعالى، وبعبادتهم غير الله سبحانه."]], "m": "ما زال السياق في تقرير التوحيد بإبطال الشرك وشبهه: قال المشركون: إن الملائكة بنات الله، فنزّه الله نفسه عن هذا الكذب، وأقام الحجة على بطلانه بأنه هو الغني الذي لا يفتقر إلى غيره، فكيف يحتاج إلى ولد؟ وبرهان آخر: أن له ما في السماوات وما في الأرض خلقاً وملكاً، فهل يُعقل أن يتخذ المالك عبداً من عبيده ولداً له؟ ثم: هل عندكم حجة على ما تقولون؟ لا، أتقولون على الله ما لا تعلمون؟ قل: إن الذين يفترون على الله الكذب لا يفلحون. وإن قيل: كيف لا يفلحون وهم يتمتعون بالأموال والأولاد والجاه؟ فالجواب: ذلك متاع في الدنيا إلى نهاية أعمارهم، ثم إلينا مرجعهم، ثم نذيقهم العذاب الشديد الذي ينسون معه كل ما تمتعوا به، بما كانوا يكفرون، أي يجحدون كمال الله وغناه فينسبون إليه الولد والشريك.", "h": ["كفر من ينسب إلى الله تعالى أي نقص، كالولد والشريك أو العجز مطلقاً.", "كل دعوى لا يقيم لها صاحبها برهاناً قاطعاً وحجة واضحة فلا قيمة لها ولا يُحفل بها.", "أهل الكذب على الله، كالدجالين والسحرة وأهل البدع والخرافات، لا يفلحون، ونهايتهم الخسران.", "لا ينبغي للمؤمن أن يغتر بما يرى عليه أهل الباطل والشر من المتع وسعة الرزق وصحة البدن، فإن ذلك متاع الحياة الدنيا، ثم يؤول أمرهم إلى خسران دائم."], "k": "«متاع في الدنيا ثم إلينا مرجعهم»… ما أراه في يد غيري من متاع، هل أقيسه بميزان الآخرة؟"}, {"lbl": "الآيات ٧١ – ٧٣", "q": "۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِهِۦ يَٰقَوۡمِ إِن كَانَ كَبُرَ عَلَيۡكُم مَّقَامِي وَتَذۡكِيرِي بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلۡتُ فَأَجۡمِعُوٓاْ أَمۡرَكُمۡ وَشُرَكَآءَكُمۡ ثُمَّ لَا يَكُنۡ أَمۡرُكُمۡ عَلَيۡكُمۡ غُمَّةٗ ثُمَّ ٱقۡضُوٓاْ إِلَيَّ وَلَا تُنظِرُونِ ﴿٧١﴾ فَإِن تَوَلَّيۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ ﴿٧٢﴾ فَكَذَّبُوهُ فَنَجَّيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ وَجَعَلۡنَٰهُمۡ خَلَـٰٓئِفَ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ ﴿٧٣﴾", "w": [["واتل عليهم نبأ نوح", "اقرأ على المشركين خبر نوح العظيم الخطير."], ["كبر عليكم مقامي", "عظم عليكم مقامي بينكم أدعو إلى ربي."], ["فأجمعوا أمركم", "اعزموا عزماً أكيداً."], ["غمة", "خفاءً ولبساً لا تهتدون منه إلى ما تريدون."], ["ثم اقضوا إلي", "أنفذوا أمركم."], ["ولا تُنظرون", "ولا تمهلوني رحمةً بي أو شفقةً عليّ."], ["فإن توليتم", "أعرضتم عما أدعوكم إليه من التوحيد."], ["في الفلك", "في السفينة."], ["خلائف", "يخلف الآخِر الأول جيلاً بعد جيل."]], "m": "يأمر الله رسوله ﷺ أن يقرأ على المشركين طرفاً من قصة نوح ﵇ مع قومه، وكانت حالهم كحال مشركي العرب سواءً بسواء، وفي ذلك فائدتان: تسلية الرسول ﷺ وحمله على الصبر، وتنبيه المشركين إلى خطئهم. قال نوح: يا قوم، إن كان عظم عليكم مقامي بينكم أدعوكم إلى الله وأذكّركم بآياته، فإني توكلت على الله، فاعزموا أمركم وادعوا شركاءكم، ثم لا يكن أمركم عليكم خفياً ملتبساً فتترددوا، ثم أنفذوا ما تريدون من قتلي أو نفيي ولا تؤخروني. فإن أعرضتم عن دعوتي فما سألتكم عليه من أجر حتى تتولّوا، إن أجري إلا على الله الذي أرسلني، وأُمرت أن أكون من المسلمين له. فكذّبوه بعد دعوة زمناً غير قصير، فنجّيناه ومن معه في السفينة، وجعلناهم خلائف يخلف بعضهم بعضاً، وأغرقنا الذين كذّبوا بآياتنا، فانظر يا رسولنا كيف كان عاقبة المنذَرين الذين لم يقبلوا النصح: إغراق في الطوفان، ونار في جهنم، وخسران.", "h": ["تسلية الدعاة بمثل موقف نوح العظيم، إذ قال لقومه: أجمعوا أمركم ونفّذوا ما تريدون، إني توكلت على الله.", "ثمرة التوكل شجاعة واطمئنان نفس، وصبر وتحمّل مع مضاء عزيمة.", "دعوة الله لا ينبغي أن يأخذ الداعي عليها أجراً إلا للضرورة.", "بيان سوء عاقبة المكذبين بعد إنذارهم وتحذيرهم."], "k": "«فعلى الله توكلت»… قالها نوح وحده أمام قومه جميعاً؛ فما الذي أخافه أنا وربي حسبي؟"}, {"lbl": "الآيات ٧٤ – ٧٨", "q": "ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِۦ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ بِهِۦ مِن قَبۡلُۚ كَذَٰلِكَ نَطۡبَعُ عَلَىٰ قُلُوبِ ٱلۡمُعۡتَدِينَ ﴿٧٤﴾ ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ بِـَٔايَٰتِنَا فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ ﴿٧٥﴾ فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوٓاْ إِنَّ هَٰذَا لَسِحۡرٞ مُّبِينٞ ﴿٧٦﴾ قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلۡحَقِّ لَمَّا جَآءَكُمۡۖ أَسِحۡرٌ هَٰذَا وَلَا يُفۡلِحُ ٱلسَّـٰحِرُونَ ﴿٧٧﴾ قَالُوٓاْ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلۡكِبۡرِيَآءُ فِي ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِينَ ﴿٧٨﴾", "w": [["بالبينات", "بالحجج الواضحات على صدق دعوتهم، وما يدعون إليه من توحيد الله تعالى."], ["نطبع", "الطبع على القلب عبارة عن تراكم الذنوب عليه حتى لا يجد الإيمان إليه طريقاً."], ["المعتدين", "الذين تجاوزوا الحد في الظلم والاعتداء على حدود الشرع."], ["الحق", "الآيات التي جاء بها موسى ﵇، وهي تسع."], ["الكبرياء", "العلو والسيادة والملك على الناس."]], "m": "لما ذكر تعالى طرفاً من قصة نوح ﵇ وأبرز فيها مظهر التوكل ونصرة الله لأوليائه، ذكر سنة من سننه: ثم بعثنا من بعد نوح رسلاً إلى قومهم، كهود وصالح وإبراهيم ولوط وشعيب، فجاؤوهم بالحجج على صدقهم، فما كانوا ليؤمنوا بما كذّب به من سبقهم. كذلك نطبع على قلوب المعتدين: إذا أذنب العبد وواصل الذنب بلا توبة صار الذنب طبعاً من طباعه لا يمكنه التخلي عنه، فيُختم على قلبه، فلا يقبل الإيمان ولا يعرف معروفاً ولا ينكر منكراً. ثم بعثنا من بعدهم موسى وهارون إلى فرعون وملئه بآياتنا الدالّة على صحة مطلبهما: توحيد الله وإرسال بني إسرائيل معهما، فاستكبروا وكانوا قوماً مجرمين أفسدوا القلوب والعقول وسفكوا الدماء وعذّبوا الضعفاء. فلما بهرتهم المعجزات قالوا: إن هذا لسحر مبين، تخلّصاً من الهزيمة، فوبّخهم موسى: أتقولون للحق لما جاءكم سحر؟ لو كان سحراً فكيف أفلحتُ في إبطال سحركم، ولا يفلح الساحرون؟ فلما أفحمهم بالحجة قالوا مراوغين: أجئتنا لتصرفنا عما وجدنا عليه آباءنا، وتكون لكما السيادة والملك في الأرض؟ وما نحن لكما بمؤمنين.", "h": ["بيان سنة الله في البشر، وهي أن التوغّل في الشر والفساد والظلم يوجب الختم على القلوب، فيُحرم العبد الإيمان والهداية.", "ذم الاستكبار، وأنه سبب كثير من الإجرام.", "تقرير أن الساحر لا يفلح أبداً، ولا يفوز بمطلوب ولا ينجو من مرهوب.", "الاتهامات الكاذبة من شأن أهل الباطل والظلم والفساد."], "k": "«كذلك نطبع على قلوب المعتدين»… ذنب أواظب عليه بلا توبة؛ هل أنتبه قبل أن يصير طبعاً؟"}, {"lbl": "الآيات ٧٩ – ٨٢", "q": "وَقَالَ فِرۡعَوۡنُ ٱئۡتُونِي بِكُلِّ سَٰحِرٍ عَلِيمٖ ﴿٧٩﴾ فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ ﴿٨٠﴾ فَلَمَّآ أَلۡقَوۡاْ قَالَ مُوسَىٰ مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَيُبۡطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِينَ ﴿٨١﴾ وَيُحِقُّ ٱللَّهُ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ ﴿٨٢﴾", "w": [["ساحر عليم", "ذو سحر حقيقي له تأثير، عليم بالفن."], ["ألقوا", "ارموا في الميدان ما تريدون إلقاءه من ضروب السحر."], ["إن الله سيبطله", "يُظهر بطلانه أمام الناظرين من الناس."], ["ويحق الله الحق", "يقرّر الحق ويثبته."], ["بكلماته", "بأمره، إذ يقول للشيء: كن فيكون."], ["المجرمون", "أهل الإجرام على أنفسهم وعلى غيرهم، وهم الظلمة المفسدون."]], "m": "لما غلب موسى فرعونَ وملأه بالحجة، اتّهم فرعون موسى وهارون بأنهما يريدان الملك والسيادة، وكذب في ذلك، ثم أمر رجال دولته أن يحضروا له كل ساحر عليم ليباري موسى، فلما جاء السحرة قال لهم موسى: ألقوا ما أنتم ملقون، فألقوا حبالهم وعصيّهم، فقال موسى: ما جئتم به هو السحر، إن الله سيبطله، إن الله لا يصلح عمل المفسدين، ويحق الله الحق بكلماته ولو كره المجرمون. وألقى عصاه فإذا هي تلقف ما يأفكون، فوقع الحق وبطل ما كانوا يعملون.", "h": ["للسحر طرق يُتعلّم بها، وله علماء به، وتعلّمه حرام واستعماله حرام.", "حد الساحر القتل، لأنه إفساد في الأرض.", "جواز المبارزة للعدو والمباراة له إظهاراً للحق وإبطالاً للباطل.", "عاقبة الفساد وعمل أصحابه الخراب والدمار.", "متى قاوم الحقُّ الباطلَ انهزم الباطل وانتصر الحق بأمر الله تعالى ووعده الصادق."], "k": "«إن الله لا يصلح عمل المفسدين»… مهما بدا الباطل مبهراً، فهل أثق أن عاقبته البطلان؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (138, 10, 83, 93, 'سورة يونس ٨٣ – ٩٣', '«ربنا لا تجعلنا فتنة للقوم الظالمين»، وغرق فرعون: «آلآن وقد عصيت قبل»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 138) = $j$[{"lbl": "الآيات ٨٣ – ٨٧", "q": "فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٞ مِّن قَوۡمِهِۦ عَلَىٰ خَوۡفٖ مِّن فِرۡعَوۡنَ وَمَلَإِيْهِمۡ أَن يَفۡتِنَهُمۡۚ وَإِنَّ فِرۡعَوۡنَ لَعَالٖ فِي ٱلۡأَرۡضِ وَإِنَّهُۥ لَمِنَ ٱلۡمُسۡرِفِينَ ﴿٨٣﴾ وَقَالَ مُوسَىٰ يَٰقَوۡمِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ فَعَلَيۡهِ تَوَكَّلُوٓاْ إِن كُنتُم مُّسۡلِمِينَ ﴿٨٤﴾ فَقَالُواْ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٨٥﴾ وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿٨٦﴾ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُيُوتٗا وَٱجۡعَلُواْ بُيُوتَكُمۡ قِبۡلَةٗ وَأَقِيمُواْ ٱلصَّلَوٰةَۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ ﴿٨٧﴾", "w": [["فما آمن لموسى", "لم ينقد له ويتبعه."], ["إلا ذرية", "طائفة قليلة من أولاد بني إسرائيل."], ["وملئهم", "أشرافهم ورؤسائهم."], ["أن يفتنهم", "أن يضطهدهم ويعذبهم."], ["لعال في الأرض", "قاهر مستبد."], ["مسلمين", "مذعنين منقادين لأمره ونهيه."], ["فتنة للقوم الظالمين", "لا تفتنهم بنا بأن تنصرهم علينا فيروا أنهم خير منا فيزدادوا كفراً."], ["أن تبوّءا", "اتخذا لقومكما بمصر بيوتاً تبوؤون إليها وترجعون."], ["قبلة", "مساجد تصلّون فيها."]], "m": "بعد ذلك الانتصار الباهر لموسى على السحرة لم يؤمن له ويتابعه إلا ذرية من بني إسرائيل، وعدد قليل من آل فرعون كامرأته ومؤمن آل فرعون والماشطة، على خوف من فرعون ومن رؤسائهم أن يفتنوهم، وإن فرعون لقاهر متسلط مستبد ظالم، وإنه لمن المسرفين في الظلم. ولما ظهر الخوف على بني إسرائيل قال لهم موسى: يا قوم إن كنتم آمنتم بالله فعليه توكلوا، ففوّضوا أمركم إليه إن كنتم حقاً منقادين لأمره ونهيه. فقالوا: على الله توكلنا، ربنا لا تجعلنا فتنة للقوم الظالمين، فلا تنصرهم علينا فيزدادوا كفراً وظلماً، ولا تسلّطهم علينا فيفتنونا في ديننا، ونجّنا برحمتك من القوم الكافرين، وهذا حسن توسّل منهم برحمة الله. وأوحى الله إلى موسى وأخيه أن اتخذا لقومكما بمصر بيوتاً، واجعلوها متقابلة مساجد تصلّون فيها، إذ أخذوا ينحازون عن مجتمع فرعون استعداداً للخروج، وقد مُنعوا المساجد ظلماً، وأقيموا الصلاة على الوجه المشروع، وبشّر المؤمنين بحسن العاقبة: كرامة الدنيا وسعادة الآخرة.", "h": ["تسلية الرسول ﷺ، حيث أراه كيف انتصر موسى بالمعجزات ومع ذلك لم يتابعه إلا القليل من قومه.", "التنديد بالعلو في الأرض والإسراف في الشر والفساد وبأهلهما.", "وجوب التوكل على الله تعالى لتحمّل عبء الدعوة إلى الله تعالى والقيام بطاعته.", "مشروعية الدعاء والتوسل إلى الله تعالى بأسمائه وصفاته.", "اتخاذ المساجد في المنازل للصلاة فيها عند الخوف.", "وجوب إقام الصلاة.", "بشرى الله تعالى للمؤمنين والمقيمين للصلاة بحسن العاقبة في الدارين."], "k": "«إن كنتم آمنتم بالله فعليه توكلوا»… في الخوف الذي أعيشه الآن، هل فوّضت أمري إلى الله حقاً؟"}, {"lbl": "الآيتان ٨٨ – ٨٩", "q": "وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيۡتَ فِرۡعَوۡنَ وَمَلَأَهُۥ زِينَةٗ وَأَمۡوَٰلٗا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا رَبَّنَا لِيُضِلُّواْ عَن سَبِيلِكَۖ رَبَّنَا ٱطۡمِسۡ عَلَىٰٓ أَمۡوَٰلِهِمۡ وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ فَلَا يُؤۡمِنُواْ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ ﴿٨٨﴾ قَالَ قَدۡ أُجِيبَت دَّعۡوَتُكُمَا فَٱسۡتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعۡلَمُونَ ﴿٨٩﴾", "w": [["زينة", "حلياً وحللاً ورياشاً ومتاعاً."], ["أموالاً", "كثيرة من الذهب والفضة والأنعام والحرث."], ["اطمس", "أزل أثرها من بينهم بإذهابها."], ["أجيبت دعوتكما", "استجابها الله تعالى."], ["فاستقيما", "على طاعة الله بأداء رسالته والدعوة إليه والصبر على الأذى فيه."], ["سبيل الذين لا يعلمون", "طريق الجهلة الذين لا يعرفون محابّ الله ومساخطه، ولا يعلمون شرائعه التي أنزل لعباده."]], "m": "بعد أن لجّ فرعون في العناد والمكابرة بعد هزيمته، سأل موسى ربه قائلاً: ربنا إنك آتيت فرعون وملأه زينة، من الملابس والفرش والأثاث وأنواع الحلي، وأموالاً من الذهب والفضة والأنعام والحرث في الحياة الدنيا، ربنا ليضلّوا عن سبيلك، فيسبّب ذلك لهم الضلال. ربنا اطمس على أموالهم، أذهب أثرها واجعلها غير صالحة للانتفاع بها، واشدد على قلوبهم، اطبع عليها، فلا يؤمنوا حتى يروا العذاب الأليم. قال تعالى: قد أجيبت دعوتكما، فاستقيما على طاعتنا بالدعوة إلينا، وأداء عبادتنا، والنصح لعبادنا، والعمل على إنقاذهم من ظلم الظالمين، ولا تتّبعان سبيل الذين لا يعلمون فتستعجلا وقوع العذاب، فإن الذين لا يعلمون ما لله من حِكَم وتدابير يستعجلون وعده، بل انتظرا واصبرا حتى يأتي وعد الله، وما الله بمخلف وعده.", "h": ["مشروعية الدعاء بالهلاك على أهل الظلم.", "كثرة المال وأنواع الزينة، والانغماس في ذلك والتلهّي به، يسبب الضلال لصاحبه.", "الذين بلغوا حداً من الشر والفساد فطُبع على قلوبهم لا يموتون إلا على الكفر فيخسرون.", "المؤمّن داعٍ، فهو شريك في الدعاء، فلذا أهل المسجد يؤمّنون على دعاء الإمام في الخطبة فتحصل الإجابة للجميع.", "حرمة اتباع طرق أهل الضلال، وتقليد الجهال والسير وراءهم."], "k": "«قد أجيبت دعوتكما فاستقيما»… لم يُقل لهما: انتظرا النتيجة، بل: استقيما؛ فهل أستقيم وأنا أنتظر الإجابة؟"}, {"lbl": "الآيات ٩٠ – ٩٢", "q": "۞وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيٗا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَـٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ ﴿٩٠﴾ ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِينَ ﴿٩١﴾ فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ ﴿٩٢﴾", "w": [["وجاوزنا ببني إسرائيل", "قطعنا بهم البحر حتى تجاوزوه."], ["البحر", "بحر القلزم."], ["بغياً وعدواً", "بغياً على موسى وهارون واعتداءً عليهما."], ["آلآن", "أفي هذا الوقت تقرّ بالوحدانية وتعترف له بالذلّة؟!"], ["ببدنك", "بجسدك لا روح فيه."], ["آية", "علامة على أنك عبد وليس برب، فيعتبروا بذلك."]], "m": "كانت بداية استجابة الله دعوة موسى وهارون أن جاوز ببني إسرائيل البحر: أمر موسى أن يضرب بعصاه البحر فانفلق، فكان كل فِرق كالطود العظيم، ويبست الأرض، فدخل موسى مع بني إسرائيل حتى تجاوزوا البحر، وأتبعهم فرعون وجنوده بغياً وعدواً، فلما توسّطوا البحر أطبقه الله عليهم فغرقوا أجمعين. فلما أدرك فرعونَ الغرقُ أعلن توبته: آمنت أنه لا إله إلا الذي آمنت به بنو إسرائيل، ولكبريائه لم يقل: لا إله إلا الله، وهو يعرف أنه الله، وأنا من المسلمين، مبالغةً في طلب النجاة. فردّ الله تعالى: آلآن، وقد عصيت قبل وتمرّدت على الله وشرعه، وكنت من المفسدين للبلاد والعباد؟ فاليوم ننجّيك ببدنك، نجعلك على مرتفع من الأرض بجسمك دون روحك، لتكون لمن بعدك من الناس آية على أنك عبد مربوب لا رب معبود، وعبرة فلا يطغى أحد طغيانك فيهلك كما هلكت، وإن كثيراً من الناس عن آياتنا لغافلون، ومنهم كفار قريش الذين سيق هذا القصص لهدايتهم.", "h": ["لا تُقبل التوبة عند معاينة العذاب، وفي الحديث: «تُقبل توبة العبد ما لم يغرغر».", "أكمل الأديان وأفضلها الإسلام، ولهذا أهل اليقين يسألون الله تعالى أن يتوفّاهم مسلمين، ولما أيقن فرعون بالهلاك زعم أنه من المسلمين.", "فضل لا إله إلا الله، فقد ورد أن جبريل كان يحول بين فرعون وبين أن يقولها فينجو، فلم يقلها فغرق وكان من الهالكين.", "تقرير حقيقة، وهي أن أكثر الناس في هذه الحياة غافلون عما يُراد بهم ولهم، ولم ينتبهوا حتى يهلكوا."], "k": "«آلآن وقد عصيت قبل»… التوبة لها وقت ينتهي؛ فماذا أؤجّل منها إلى غدٍ لا أضمنه؟"}, {"lbl": "الآية ٩٣", "q": "وَلَقَدۡ بَوَّأۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ مُبَوَّأَ صِدۡقٖ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿٩٣﴾", "w": [["مبوّأ صدق", "أنزلناهم منزلاً صالحاً طيباً مرضياً."], ["من الطيبات", "من أنواع الأرزاق الطيبة الحلال."], ["حتى جاءهم العلم", "وهو معرفتهم أن محمداً ﷺ هو النبي المنتظر، وأنه المنجي."], ["يقضي بينهم", "يحكم بينهم."], ["فيما كانوا فيه يختلفون", "في الذي اختلفوا فيه من الحق، فيُدخل المؤمنين الجنة والكافرين النار."]], "m": "هذه خاتمة الحديث عن موسى وبني إسرائيل بعد أن نجّاهم الله من عدوهم: ولقد أنزلناهم منزلاً صالحاً طيباً، وهو بلاد فلسطين من أرض الشام المباركة، وذلك بعد نجاتهم من التيه ودخولهم فلسطين بصحبة نبي الله يوشع بن نون ﵇، ورزقناهم من الطيبات، إذ أرض الشام أرض العسل والسمن والحبوب والثمار واللحم، وذكر هذا إظهار لنعم الله ليشكروها. فما اختلفوا حتى جاءهم العلم: كانوا قبل مبعث النبي ﷺ متفقين منتظرين النبي المبشَّر به في التوراة الذي سينقذهم، فلما جاءهم وهو العلم، ومعه القرآن، اختلفوا فيه. إن ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون من أمر الإيمان بك واتباع ما جئت به، فيُدخل المؤمنين الجنة والكافرين النار.", "h": ["بيان إكرام الله تعالى لبني إسرائيل.", "الرزق الطيب هو ما كان حلالاً، لا ما كان حراماً.", "إذا أراد الله هلاك أمة اختلفت بسبب العلم الذي هو في الأصل سبب الوحدة والوئام.", "حرمة الاختلاف في الدين إذا كان يؤدي إلى الانقسام والتعادي والتحارب.", "يوم القيامة هو يوم الفصل الذي يقضي الله تعالى فيه بين المختلفين بحكمه العادل."], "k": "«فما اختلفوا حتى جاءهم العلم»… العلم نعمة تجمع؛ فهل أجعل ما تعلّمته سبباً للوئام أم للخصام؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 138;
insert into public.tdb_cards(topic, i, body) select 138, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٣ – ٨٧", "q": "فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٞ مِّن قَوۡمِهِۦ عَلَىٰ خَوۡفٖ مِّن فِرۡعَوۡنَ وَمَلَإِيْهِمۡ أَن يَفۡتِنَهُمۡۚ وَإِنَّ فِرۡعَوۡنَ لَعَالٖ فِي ٱلۡأَرۡضِ وَإِنَّهُۥ لَمِنَ ٱلۡمُسۡرِفِينَ ﴿٨٣﴾ وَقَالَ مُوسَىٰ يَٰقَوۡمِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ فَعَلَيۡهِ تَوَكَّلُوٓاْ إِن كُنتُم مُّسۡلِمِينَ ﴿٨٤﴾ فَقَالُواْ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٨٥﴾ وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿٨٦﴾ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُيُوتٗا وَٱجۡعَلُواْ بُيُوتَكُمۡ قِبۡلَةٗ وَأَقِيمُواْ ٱلصَّلَوٰةَۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ ﴿٨٧﴾", "w": [["فما آمن لموسى", "لم ينقد له ويتبعه."], ["إلا ذرية", "طائفة قليلة من أولاد بني إسرائيل."], ["وملئهم", "أشرافهم ورؤسائهم."], ["أن يفتنهم", "أن يضطهدهم ويعذبهم."], ["لعال في الأرض", "قاهر مستبد."], ["مسلمين", "مذعنين منقادين لأمره ونهيه."], ["فتنة للقوم الظالمين", "لا تفتنهم بنا بأن تنصرهم علينا فيروا أنهم خير منا فيزدادوا كفراً."], ["أن تبوّءا", "اتخذا لقومكما بمصر بيوتاً تبوؤون إليها وترجعون."], ["قبلة", "مساجد تصلّون فيها."]], "m": "بعد ذلك الانتصار الباهر لموسى على السحرة لم يؤمن له ويتابعه إلا ذرية من بني إسرائيل، وعدد قليل من آل فرعون كامرأته ومؤمن آل فرعون والماشطة، على خوف من فرعون ومن رؤسائهم أن يفتنوهم، وإن فرعون لقاهر متسلط مستبد ظالم، وإنه لمن المسرفين في الظلم. ولما ظهر الخوف على بني إسرائيل قال لهم موسى: يا قوم إن كنتم آمنتم بالله فعليه توكلوا، ففوّضوا أمركم إليه إن كنتم حقاً منقادين لأمره ونهيه. فقالوا: على الله توكلنا، ربنا لا تجعلنا فتنة للقوم الظالمين، فلا تنصرهم علينا فيزدادوا كفراً وظلماً، ولا تسلّطهم علينا فيفتنونا في ديننا، ونجّنا برحمتك من القوم الكافرين، وهذا حسن توسّل منهم برحمة الله. وأوحى الله إلى موسى وأخيه أن اتخذا لقومكما بمصر بيوتاً، واجعلوها متقابلة مساجد تصلّون فيها، إذ أخذوا ينحازون عن مجتمع فرعون استعداداً للخروج، وقد مُنعوا المساجد ظلماً، وأقيموا الصلاة على الوجه المشروع، وبشّر المؤمنين بحسن العاقبة: كرامة الدنيا وسعادة الآخرة.", "h": ["تسلية الرسول ﷺ، حيث أراه كيف انتصر موسى بالمعجزات ومع ذلك لم يتابعه إلا القليل من قومه.", "التنديد بالعلو في الأرض والإسراف في الشر والفساد وبأهلهما.", "وجوب التوكل على الله تعالى لتحمّل عبء الدعوة إلى الله تعالى والقيام بطاعته.", "مشروعية الدعاء والتوسل إلى الله تعالى بأسمائه وصفاته.", "اتخاذ المساجد في المنازل للصلاة فيها عند الخوف.", "وجوب إقام الصلاة.", "بشرى الله تعالى للمؤمنين والمقيمين للصلاة بحسن العاقبة في الدارين."], "k": "«إن كنتم آمنتم بالله فعليه توكلوا»… في الخوف الذي أعيشه الآن، هل فوّضت أمري إلى الله حقاً؟"}, {"lbl": "الآيتان ٨٨ – ٨٩", "q": "وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيۡتَ فِرۡعَوۡنَ وَمَلَأَهُۥ زِينَةٗ وَأَمۡوَٰلٗا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا رَبَّنَا لِيُضِلُّواْ عَن سَبِيلِكَۖ رَبَّنَا ٱطۡمِسۡ عَلَىٰٓ أَمۡوَٰلِهِمۡ وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ فَلَا يُؤۡمِنُواْ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ ﴿٨٨﴾ قَالَ قَدۡ أُجِيبَت دَّعۡوَتُكُمَا فَٱسۡتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعۡلَمُونَ ﴿٨٩﴾", "w": [["زينة", "حلياً وحللاً ورياشاً ومتاعاً."], ["أموالاً", "كثيرة من الذهب والفضة والأنعام والحرث."], ["اطمس", "أزل أثرها من بينهم بإذهابها."], ["أجيبت دعوتكما", "استجابها الله تعالى."], ["فاستقيما", "على طاعة الله بأداء رسالته والدعوة إليه والصبر على الأذى فيه."], ["سبيل الذين لا يعلمون", "طريق الجهلة الذين لا يعرفون محابّ الله ومساخطه، ولا يعلمون شرائعه التي أنزل لعباده."]], "m": "بعد أن لجّ فرعون في العناد والمكابرة بعد هزيمته، سأل موسى ربه قائلاً: ربنا إنك آتيت فرعون وملأه زينة، من الملابس والفرش والأثاث وأنواع الحلي، وأموالاً من الذهب والفضة والأنعام والحرث في الحياة الدنيا، ربنا ليضلّوا عن سبيلك، فيسبّب ذلك لهم الضلال. ربنا اطمس على أموالهم، أذهب أثرها واجعلها غير صالحة للانتفاع بها، واشدد على قلوبهم، اطبع عليها، فلا يؤمنوا حتى يروا العذاب الأليم. قال تعالى: قد أجيبت دعوتكما، فاستقيما على طاعتنا بالدعوة إلينا، وأداء عبادتنا، والنصح لعبادنا، والعمل على إنقاذهم من ظلم الظالمين، ولا تتّبعان سبيل الذين لا يعلمون فتستعجلا وقوع العذاب، فإن الذين لا يعلمون ما لله من حِكَم وتدابير يستعجلون وعده، بل انتظرا واصبرا حتى يأتي وعد الله، وما الله بمخلف وعده.", "h": ["مشروعية الدعاء بالهلاك على أهل الظلم.", "كثرة المال وأنواع الزينة، والانغماس في ذلك والتلهّي به، يسبب الضلال لصاحبه.", "الذين بلغوا حداً من الشر والفساد فطُبع على قلوبهم لا يموتون إلا على الكفر فيخسرون.", "المؤمّن داعٍ، فهو شريك في الدعاء، فلذا أهل المسجد يؤمّنون على دعاء الإمام في الخطبة فتحصل الإجابة للجميع.", "حرمة اتباع طرق أهل الضلال، وتقليد الجهال والسير وراءهم."], "k": "«قد أجيبت دعوتكما فاستقيما»… لم يُقل لهما: انتظرا النتيجة، بل: استقيما؛ فهل أستقيم وأنا أنتظر الإجابة؟"}, {"lbl": "الآيات ٩٠ – ٩٢", "q": "۞وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيٗا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَـٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ ﴿٩٠﴾ ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِينَ ﴿٩١﴾ فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ ﴿٩٢﴾", "w": [["وجاوزنا ببني إسرائيل", "قطعنا بهم البحر حتى تجاوزوه."], ["البحر", "بحر القلزم."], ["بغياً وعدواً", "بغياً على موسى وهارون واعتداءً عليهما."], ["آلآن", "أفي هذا الوقت تقرّ بالوحدانية وتعترف له بالذلّة؟!"], ["ببدنك", "بجسدك لا روح فيه."], ["آية", "علامة على أنك عبد وليس برب، فيعتبروا بذلك."]], "m": "كانت بداية استجابة الله دعوة موسى وهارون أن جاوز ببني إسرائيل البحر: أمر موسى أن يضرب بعصاه البحر فانفلق، فكان كل فِرق كالطود العظيم، ويبست الأرض، فدخل موسى مع بني إسرائيل حتى تجاوزوا البحر، وأتبعهم فرعون وجنوده بغياً وعدواً، فلما توسّطوا البحر أطبقه الله عليهم فغرقوا أجمعين. فلما أدرك فرعونَ الغرقُ أعلن توبته: آمنت أنه لا إله إلا الذي آمنت به بنو إسرائيل، ولكبريائه لم يقل: لا إله إلا الله، وهو يعرف أنه الله، وأنا من المسلمين، مبالغةً في طلب النجاة. فردّ الله تعالى: آلآن، وقد عصيت قبل وتمرّدت على الله وشرعه، وكنت من المفسدين للبلاد والعباد؟ فاليوم ننجّيك ببدنك، نجعلك على مرتفع من الأرض بجسمك دون روحك، لتكون لمن بعدك من الناس آية على أنك عبد مربوب لا رب معبود، وعبرة فلا يطغى أحد طغيانك فيهلك كما هلكت، وإن كثيراً من الناس عن آياتنا لغافلون، ومنهم كفار قريش الذين سيق هذا القصص لهدايتهم.", "h": ["لا تُقبل التوبة عند معاينة العذاب، وفي الحديث: «تُقبل توبة العبد ما لم يغرغر».", "أكمل الأديان وأفضلها الإسلام، ولهذا أهل اليقين يسألون الله تعالى أن يتوفّاهم مسلمين، ولما أيقن فرعون بالهلاك زعم أنه من المسلمين.", "فضل لا إله إلا الله، فقد ورد أن جبريل كان يحول بين فرعون وبين أن يقولها فينجو، فلم يقلها فغرق وكان من الهالكين.", "تقرير حقيقة، وهي أن أكثر الناس في هذه الحياة غافلون عما يُراد بهم ولهم، ولم ينتبهوا حتى يهلكوا."], "k": "«آلآن وقد عصيت قبل»… التوبة لها وقت ينتهي؛ فماذا أؤجّل منها إلى غدٍ لا أضمنه؟"}, {"lbl": "الآية ٩٣", "q": "وَلَقَدۡ بَوَّأۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ مُبَوَّأَ صِدۡقٖ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿٩٣﴾", "w": [["مبوّأ صدق", "أنزلناهم منزلاً صالحاً طيباً مرضياً."], ["من الطيبات", "من أنواع الأرزاق الطيبة الحلال."], ["حتى جاءهم العلم", "وهو معرفتهم أن محمداً ﷺ هو النبي المنتظر، وأنه المنجي."], ["يقضي بينهم", "يحكم بينهم."], ["فيما كانوا فيه يختلفون", "في الذي اختلفوا فيه من الحق، فيُدخل المؤمنين الجنة والكافرين النار."]], "m": "هذه خاتمة الحديث عن موسى وبني إسرائيل بعد أن نجّاهم الله من عدوهم: ولقد أنزلناهم منزلاً صالحاً طيباً، وهو بلاد فلسطين من أرض الشام المباركة، وذلك بعد نجاتهم من التيه ودخولهم فلسطين بصحبة نبي الله يوشع بن نون ﵇، ورزقناهم من الطيبات، إذ أرض الشام أرض العسل والسمن والحبوب والثمار واللحم، وذكر هذا إظهار لنعم الله ليشكروها. فما اختلفوا حتى جاءهم العلم: كانوا قبل مبعث النبي ﷺ متفقين منتظرين النبي المبشَّر به في التوراة الذي سينقذهم، فلما جاءهم وهو العلم، ومعه القرآن، اختلفوا فيه. إن ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون من أمر الإيمان بك واتباع ما جئت به، فيُدخل المؤمنين الجنة والكافرين النار.", "h": ["بيان إكرام الله تعالى لبني إسرائيل.", "الرزق الطيب هو ما كان حلالاً، لا ما كان حراماً.", "إذا أراد الله هلاك أمة اختلفت بسبب العلم الذي هو في الأصل سبب الوحدة والوئام.", "حرمة الاختلاف في الدين إذا كان يؤدي إلى الانقسام والتعادي والتحارب.", "يوم القيامة هو يوم الفصل الذي يقضي الله تعالى فيه بين المختلفين بحكمه العادل."], "k": "«فما اختلفوا حتى جاءهم العلم»… العلم نعمة تجمع؛ فهل أجعل ما تعلّمته سبباً للوئام أم للخصام؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (139, 10, 94, 103, 'سورة يونس ٩٤ – ١٠٣', '«فلولا كانت قرية آمنت فنفعها إيمانها إلا قوم يونس»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 139) = $j$[{"lbl": "الآيات ٩٤ – ٩٧", "q": "فَإِن كُنتَ فِي شَكّٖ مِّمَّآ أَنزَلۡنَآ إِلَيۡكَ فَسۡـَٔلِ ٱلَّذِينَ يَقۡرَءُونَ ٱلۡكِتَٰبَ مِن قَبۡلِكَۚ لَقَدۡ جَآءَكَ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ ﴿٩٤﴾ وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلۡخَٰسِرِينَ ﴿٩٥﴾ إِنَّ ٱلَّذِينَ حَقَّتۡ عَلَيۡهِمۡ كَلِمَتُ رَبِّكَ لَا يُؤۡمِنُونَ ﴿٩٦﴾ وَلَوۡ جَآءَتۡهُمۡ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ ﴿٩٧﴾", "w": [["شك", "ما قابل التصديق، فالشاكّ غير المصدّق."], ["مما أنزلنا إليك", "في أن بني إسرائيل لم يختلفوا إلا من بعد ما جاءهم العلم."], ["الكتاب", "التوراة والإنجيل."], ["فلا تكونن من الممترين", "لا تكونن من الشاكّين."], ["حقت عليهم", "وجبت لهم النار بحكم الله بذلك في اللوح المحفوظ."], ["حتى يروا العذاب", "يستمرون على تكذيبهم حتى يروا العذاب فيؤمنوا حيث لا ينفع الإيمان."]], "m": "يقرر تعالى نبوة رسوله ﷺ: فإن كنت في شك مما أنزلنا إليك فاسأل الذين يقرؤون الكتاب من قبلك، أحبار اليهود ورهبان النصارى، فإنهم يعرفون نعوتك وصفاتك في التوراة والإنجيل، وهذا من باب الفرض وتهييجاً للغير ليؤمن، وإلا فهو ﷺ قد قال: «لا أشك ولا أسأل». لقد جاءك الحق من ربك فلا تكونن من الشاكّين في صحة الإسلام، ولا تكونن من الذين كذّبوا بآيات الله فتكون من الخاسرين، وهذا كله من باب «إياكِ أعني واسمعي يا جارة»، وإلا فمن غير الجائز أن يشك الرسول أو يكذّب بما أُنزل عليه. إن الذين حقّت عليهم كلمة ربك، فكُتب عذابهم في كتاب المقادير، لا يؤمنون أبداً مهما بُذل في سبيل إيمانهم، ولو جاءتهم كل آية، حتى يروا العذاب الأليم فيؤمنوا كما آمن فرعون عندما أدركه الغرق فلم ينفعه، وفي هذا تسلية لرسول الله ﷺ.", "h": ["تقرير نبوة الرسول ﷺ.", "سؤال من لا يعلم من يعلم.", "التكذيب بآيات الله كفر، وصاحبه من الخاسرين.", "الشك والافتراء في أصول الدين وفروعه كفر.", "تقرير عقيدة القضاء والقدر، وأن الشقي من شقي في كتاب المقادير، والسعيد من سعد فيه.", "عدم قبول توبة من عاين العذاب: في الدنيا بأن رأى ملك الموت، وفي الآخرة بعد أن يُبعث ويشاهد أهوال القيامة."], "k": "«لقد جاءك الحق من ربك»… إذا عرضت لي شبهة، هل أسأل أهل العلم أم أتركها تكبر في صدري؟"}, {"lbl": "الآيات ٩٨ – ١٠٠", "q": "فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوۡمَ يُونُسَ لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ ﴿٩٨﴾ وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ كُلُّهُمۡ جَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ ﴿٩٩﴾ وَمَا كَانَ لِنَفۡسٍ أَن تُؤۡمِنَ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَجۡعَلُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يَعۡقِلُونَ ﴿١٠٠﴾", "w": [["فلولا", "أداة تحضيض بمعنى «هلّا»، وفيها معنى التوبيخ والنفي."], ["قرية آمنت", "أهل قرية آمنوا."], ["يونس", "هو يونس بن متّى، نبي الله ورسوله."], ["إلى حين", "إلى وقت انقضاء آجالهم."], ["أفأنت تكره الناس", "إنك لا تستطيع ذلك."], ["إلا بإذن الله", "بإرادته وقضائه."], ["الرجس", "العذاب."]], "m": "بعد أن ذكر تعالى أن الخسران لازم لمن كذّب بآياته، ذكر هنا ما يحضّ به أهل مكة على الإيمان: فهلّا كانت قرية آمنت فانتفعت بإيمانها فنجت من العذاب؟ وهذا توبيخ لهم: لِمَ لا يؤمنون؟ إلا قوم يونس لما آمنوا كشفنا عنهم عذاب الخزي في الحياة الدنيا، فلم نهلكهم، لأنهم لما رأوا أمارات العذاب بادروا إلى التوبة قبل نزوله، ومتّعناهم إلى حين انقضاء آجالهم، فما لأهل أم القرى لا يتوبون كما تاب أهل نينوى من أرض الموصل؟ ولو شاء ربك لآمن من في الأرض كلهم جميعاً، فعرضه الإيمان عليهم وحضّهم عليه ليس عجزاً، وفيه تسلية للرسول ﷺ، ولكنه التكليف المترتب عليه الجزاء، يُعرض الإيمان عرضاً لا إجبار معه، أفأنت تُكره الناس حتى يكونوا مؤمنين؟ ليس هذا لك ولا كُلّفت به. وما كان لنفس أن تؤمن إلا بإرادة الله وقضائه، ويجعل العذاب محيطاً بالذين لا يعقلون، إذ لو عقلوا ما كذّبوا ربهم وهو خالقهم ومالك أمرهم.", "h": ["من مظاهر رحمة الله تعالى بعباده دعوته إياهم إلى الإيمان به وحضّهم عليه.", "قبول التوبة قبل معاينة العذاب، ورؤية العلامات لا تمنع من التوبة.", "إرادة الله الكونية التي يكوّن بها الأشياء لا تتخلّف أبداً، وإرادته الشرعية التكليفية جائزة التخلّف.", "لا إيمان إلا بإذن الله وقضائه، فلذا لا ينبغي للداعي أن يحزن على عدم إيمان الناس إذا دعاهم ولم يؤمنوا."], "k": "«فلما آمنوا كشفنا عنهم عذاب الخزي»… باب التوبة مفتوح ما دامت الروح في الجسد؛ فلماذا أتأخّر؟"}, {"lbl": "الآيات ١٠١ – ١٠٣", "q": "قُلِ ٱنظُرُواْ مَاذَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَا تُغۡنِي ٱلۡأٓيَٰتُ وَٱلنُّذُرُ عَن قَوۡمٖ لَّا يُؤۡمِنُونَ ﴿١٠١﴾ فَهَلۡ يَنتَظِرُونَ إِلَّا مِثۡلَ أَيَّامِ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِهِمۡۚ قُلۡ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ ﴿١٠٢﴾ ثُمَّ نُنَجِّي رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ حَقًّا عَلَيۡنَا نُنجِ ٱلۡمُؤۡمِنِينَ ﴿١٠٣﴾", "w": [["ماذا في السماوات والأرض", "من عجائب المخلوقات وباهر الآيات."], ["وما تغني الآيات والنذر", "ما تغني أيّ إغناء إذا كان القوم لا يؤمنون."], ["فهل ينتظرون", "ما ينتظرون."], ["خلوا من قبلهم", "مضوا من قبلهم من الأمم السابقة."], ["قل فانتظروا", "أي العذاب."], ["ثم ننجي رسلنا والذين آمنوا", "من العذاب المنتظر."], ["كذلك", "كذلك الإنجاء ننجي المؤمنين."]], "m": "ما زال السياق في دعوة قريش إلى الإيمان: قل انظروا ماذا في السماوات والأرض من عجائب الصنعة ومظاهر الحكمة والرحمة والقدرة، فإنها تدعو إلى الإيمان بالله رباً وإلهاً، وتفنّد ألوهية الأصنام والأحجار. وما تغني الآيات والرسل عن قوم قضى الله أزلاً أنهم لا يؤمنون، ولكن لما كان علم ذلك إلى الله فعلى النذر أن تدعو وتبلّغ جهدها. فهل ينتظرون إلا مثل أيام الذين خلوا من قبلهم من قوم نوح وعاد وثمود، دعتهم رسلهم فأعرضوا فأخذهم الله؟ قل: فانتظروا ما كُتب عليكم من العذاب إن لم تتوبوا، إني معكم من المنتظرين. وسنة الله أن يهلك الظالمين المكذّبين وينجّي رسله والمؤمنين، كذلك حقاً علينا ننجِ المؤمنين.", "h": ["لا تنفع الموعظة، مهما بولغ فيها، عبداً كُتب أزلاً أنه من أهل النار.", "ما ينتظر الظلمة في كل زمان ومكان إلا ما حلّ بمن ظلم قبلهم من الخزي والعذاب.", "وعد الله تعالى ثابت لأوليائه بإنجائهم من الهلاك عند إهلاكه الظلمة المشركين."], "k": "«قل انظروا ماذا في السماوات والأرض»… متى نظرت آخر مرة في السماء نظرة تفكّر، لا نظرة عابرة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 139;
insert into public.tdb_cards(topic, i, body) select 139, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩٤ – ٩٧", "q": "فَإِن كُنتَ فِي شَكّٖ مِّمَّآ أَنزَلۡنَآ إِلَيۡكَ فَسۡـَٔلِ ٱلَّذِينَ يَقۡرَءُونَ ٱلۡكِتَٰبَ مِن قَبۡلِكَۚ لَقَدۡ جَآءَكَ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ ﴿٩٤﴾ وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلۡخَٰسِرِينَ ﴿٩٥﴾ إِنَّ ٱلَّذِينَ حَقَّتۡ عَلَيۡهِمۡ كَلِمَتُ رَبِّكَ لَا يُؤۡمِنُونَ ﴿٩٦﴾ وَلَوۡ جَآءَتۡهُمۡ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ ﴿٩٧﴾", "w": [["شك", "ما قابل التصديق، فالشاكّ غير المصدّق."], ["مما أنزلنا إليك", "في أن بني إسرائيل لم يختلفوا إلا من بعد ما جاءهم العلم."], ["الكتاب", "التوراة والإنجيل."], ["فلا تكونن من الممترين", "لا تكونن من الشاكّين."], ["حقت عليهم", "وجبت لهم النار بحكم الله بذلك في اللوح المحفوظ."], ["حتى يروا العذاب", "يستمرون على تكذيبهم حتى يروا العذاب فيؤمنوا حيث لا ينفع الإيمان."]], "m": "يقرر تعالى نبوة رسوله ﷺ: فإن كنت في شك مما أنزلنا إليك فاسأل الذين يقرؤون الكتاب من قبلك، أحبار اليهود ورهبان النصارى، فإنهم يعرفون نعوتك وصفاتك في التوراة والإنجيل، وهذا من باب الفرض وتهييجاً للغير ليؤمن، وإلا فهو ﷺ قد قال: «لا أشك ولا أسأل». لقد جاءك الحق من ربك فلا تكونن من الشاكّين في صحة الإسلام، ولا تكونن من الذين كذّبوا بآيات الله فتكون من الخاسرين، وهذا كله من باب «إياكِ أعني واسمعي يا جارة»، وإلا فمن غير الجائز أن يشك الرسول أو يكذّب بما أُنزل عليه. إن الذين حقّت عليهم كلمة ربك، فكُتب عذابهم في كتاب المقادير، لا يؤمنون أبداً مهما بُذل في سبيل إيمانهم، ولو جاءتهم كل آية، حتى يروا العذاب الأليم فيؤمنوا كما آمن فرعون عندما أدركه الغرق فلم ينفعه، وفي هذا تسلية لرسول الله ﷺ.", "h": ["تقرير نبوة الرسول ﷺ.", "سؤال من لا يعلم من يعلم.", "التكذيب بآيات الله كفر، وصاحبه من الخاسرين.", "الشك والافتراء في أصول الدين وفروعه كفر.", "تقرير عقيدة القضاء والقدر، وأن الشقي من شقي في كتاب المقادير، والسعيد من سعد فيه.", "عدم قبول توبة من عاين العذاب: في الدنيا بأن رأى ملك الموت، وفي الآخرة بعد أن يُبعث ويشاهد أهوال القيامة."], "k": "«لقد جاءك الحق من ربك»… إذا عرضت لي شبهة، هل أسأل أهل العلم أم أتركها تكبر في صدري؟"}, {"lbl": "الآيات ٩٨ – ١٠٠", "q": "فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوۡمَ يُونُسَ لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ ﴿٩٨﴾ وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ كُلُّهُمۡ جَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ ﴿٩٩﴾ وَمَا كَانَ لِنَفۡسٍ أَن تُؤۡمِنَ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَجۡعَلُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يَعۡقِلُونَ ﴿١٠٠﴾", "w": [["فلولا", "أداة تحضيض بمعنى «هلّا»، وفيها معنى التوبيخ والنفي."], ["قرية آمنت", "أهل قرية آمنوا."], ["يونس", "هو يونس بن متّى، نبي الله ورسوله."], ["إلى حين", "إلى وقت انقضاء آجالهم."], ["أفأنت تكره الناس", "إنك لا تستطيع ذلك."], ["إلا بإذن الله", "بإرادته وقضائه."], ["الرجس", "العذاب."]], "m": "بعد أن ذكر تعالى أن الخسران لازم لمن كذّب بآياته، ذكر هنا ما يحضّ به أهل مكة على الإيمان: فهلّا كانت قرية آمنت فانتفعت بإيمانها فنجت من العذاب؟ وهذا توبيخ لهم: لِمَ لا يؤمنون؟ إلا قوم يونس لما آمنوا كشفنا عنهم عذاب الخزي في الحياة الدنيا، فلم نهلكهم، لأنهم لما رأوا أمارات العذاب بادروا إلى التوبة قبل نزوله، ومتّعناهم إلى حين انقضاء آجالهم، فما لأهل أم القرى لا يتوبون كما تاب أهل نينوى من أرض الموصل؟ ولو شاء ربك لآمن من في الأرض كلهم جميعاً، فعرضه الإيمان عليهم وحضّهم عليه ليس عجزاً، وفيه تسلية للرسول ﷺ، ولكنه التكليف المترتب عليه الجزاء، يُعرض الإيمان عرضاً لا إجبار معه، أفأنت تُكره الناس حتى يكونوا مؤمنين؟ ليس هذا لك ولا كُلّفت به. وما كان لنفس أن تؤمن إلا بإرادة الله وقضائه، ويجعل العذاب محيطاً بالذين لا يعقلون، إذ لو عقلوا ما كذّبوا ربهم وهو خالقهم ومالك أمرهم.", "h": ["من مظاهر رحمة الله تعالى بعباده دعوته إياهم إلى الإيمان به وحضّهم عليه.", "قبول التوبة قبل معاينة العذاب، ورؤية العلامات لا تمنع من التوبة.", "إرادة الله الكونية التي يكوّن بها الأشياء لا تتخلّف أبداً، وإرادته الشرعية التكليفية جائزة التخلّف.", "لا إيمان إلا بإذن الله وقضائه، فلذا لا ينبغي للداعي أن يحزن على عدم إيمان الناس إذا دعاهم ولم يؤمنوا."], "k": "«فلما آمنوا كشفنا عنهم عذاب الخزي»… باب التوبة مفتوح ما دامت الروح في الجسد؛ فلماذا أتأخّر؟"}, {"lbl": "الآيات ١٠١ – ١٠٣", "q": "قُلِ ٱنظُرُواْ مَاذَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَا تُغۡنِي ٱلۡأٓيَٰتُ وَٱلنُّذُرُ عَن قَوۡمٖ لَّا يُؤۡمِنُونَ ﴿١٠١﴾ فَهَلۡ يَنتَظِرُونَ إِلَّا مِثۡلَ أَيَّامِ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِهِمۡۚ قُلۡ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ ﴿١٠٢﴾ ثُمَّ نُنَجِّي رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ حَقًّا عَلَيۡنَا نُنجِ ٱلۡمُؤۡمِنِينَ ﴿١٠٣﴾", "w": [["ماذا في السماوات والأرض", "من عجائب المخلوقات وباهر الآيات."], ["وما تغني الآيات والنذر", "ما تغني أيّ إغناء إذا كان القوم لا يؤمنون."], ["فهل ينتظرون", "ما ينتظرون."], ["خلوا من قبلهم", "مضوا من قبلهم من الأمم السابقة."], ["قل فانتظروا", "أي العذاب."], ["ثم ننجي رسلنا والذين آمنوا", "من العذاب المنتظر."], ["كذلك", "كذلك الإنجاء ننجي المؤمنين."]], "m": "ما زال السياق في دعوة قريش إلى الإيمان: قل انظروا ماذا في السماوات والأرض من عجائب الصنعة ومظاهر الحكمة والرحمة والقدرة، فإنها تدعو إلى الإيمان بالله رباً وإلهاً، وتفنّد ألوهية الأصنام والأحجار. وما تغني الآيات والرسل عن قوم قضى الله أزلاً أنهم لا يؤمنون، ولكن لما كان علم ذلك إلى الله فعلى النذر أن تدعو وتبلّغ جهدها. فهل ينتظرون إلا مثل أيام الذين خلوا من قبلهم من قوم نوح وعاد وثمود، دعتهم رسلهم فأعرضوا فأخذهم الله؟ قل: فانتظروا ما كُتب عليكم من العذاب إن لم تتوبوا، إني معكم من المنتظرين. وسنة الله أن يهلك الظالمين المكذّبين وينجّي رسله والمؤمنين، كذلك حقاً علينا ننجِ المؤمنين.", "h": ["لا تنفع الموعظة، مهما بولغ فيها، عبداً كُتب أزلاً أنه من أهل النار.", "ما ينتظر الظلمة في كل زمان ومكان إلا ما حلّ بمن ظلم قبلهم من الخزي والعذاب.", "وعد الله تعالى ثابت لأوليائه بإنجائهم من الهلاك عند إهلاكه الظلمة المشركين."], "k": "«قل انظروا ماذا في السماوات والأرض»… متى نظرت آخر مرة في السماء نظرة تفكّر، لا نظرة عابرة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (140, 10, 104, 109, 'سورة يونس ١٠٤ – ١٠٩', '«وإن يمسسك الله بضر فلا كاشف له إلا هو»، «واتبع ما يوحى إليك واصبر»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 140) = $j$[{"lbl": "الآيات ١٠٤ – ١٠٧", "q": "قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي شَكّٖ مِّن دِينِي فَلَآ أَعۡبُدُ ٱلَّذِينَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنۡ أَعۡبُدُ ٱللَّهَ ٱلَّذِي يَتَوَفَّىٰكُمۡۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿١٠٤﴾ وَأَنۡ أَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗا وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٠٥﴾ وَلَا تَدۡعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَۖ فَإِن فَعَلۡتَ فَإِنَّكَ إِذٗا مِّنَ ٱلظَّـٰلِمِينَ ﴿١٠٦﴾ وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يُرِدۡكَ بِخَيۡرٖ فَلَا رَآدَّ لِفَضۡلِهِۦۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿١٠٧﴾", "w": [["في شك من ديني", "في الإسلام، في أنه حق."], ["يتوفاكم", "يقبض أرواحكم فيميتكم."], ["وأن أقم وجهك للدين حنيفاً", "أمرني ربي أن أقيم وجهي للدين الإسلامي مائلاً عن كل الأديان إليه دون غيره."], ["ما لا ينفعك ولا يضرك", "آلهة لا تنفع ولا تضر، وهي أصنام المشركين وأوثانهم."], ["إنك إذاً من الظالمين", "إنك إذا دعوتها من المشركين الظالمين لأنفسهم."], ["فلا كاشف له إلا هو", "لا مزيل للضر ومبعده عمّن أصابه إلا هو عز وجل."], ["يصيب به", "بالفضل والرحمة."], ["وهو الغفور الرحيم", "الغفور لذنوب عباده التائبين، الرحيم بعباده المؤمنين."]], "m": "بعد أن بيّن تعالى طريق الهدى وطريق الضلال، أمر رسوله أن يواجه المشركين: يا أيها الناس، إن كنتم في شك من صحة ديني الإسلام، فشكّكم لا يجعلني أعبد أوثاناً لا تنفع ولا تضر، ولكن أعبد الله الذي يحيي ويميت، الذي يتوفّاكم بقبض أرواحكم، فهو الذي يجب أن يُعبد ويُخاف، وأُمرت أن أكون من المؤمنين. وأوحى إليّ أن أقيم وجهي لدين الحق فلا ألتفت إلى غيره من الأديان الباطلة، ونهاني أن أكون من المشركين. ولا تدعُ من دون الله ما لا يجلب لك نفعاً ولا يدفع عنك ضراً، فإن فعلت فإنك إذاً من الظالمين، ولما كان دعاء النبي غير الله ممتنعاً فالكلام تعريض بالمشركين وتحذير للمؤمنين. وإن يمسسك الله بضر فلا كاشف له عنك إلا هو، وإن يردك بخير من عافية وصحة ورخاء ونصر فلا رادّ لفضله، يصيب به من يشاء من عباده، وهو الغفور لذنوب التائبين مهما عظمت، الرحيم بعباده المؤمنين مهما كثروا، وبهذا استوجب العبادة بالمحبة والتعظيم والطاعة والتسليم.", "h": ["على المؤمن ألّا يترك الحق مهما شكّ وشكّك فيه الناس.", "تحريم الشرك ووجوب تركه وترك أهله.", "دعاء غير الله، مهما كان المدعو، شرك محرّم فلا يحل أبداً، وإن سمّوه توسّلاً.", "لا يؤمن عبد حتى يوقن أن ما أراده الله له من خير أو شر لا يستطيع أحد دفعه ولا تحويله بحال من الأحوال، وهو معنى حديث: «ما أصابك لم يكن ليخطئك، وما أخطأك لم يكن ليصيبك»."], "k": "«وإن يردك بخير فلا راد لفضله»… فلماذا أقلق من حسد الناس أو كيدهم، وفضل ربي لا يردّه أحد؟"}, {"lbl": "الآيتان ١٠٨ – ١٠٩", "q": "قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنَا۠ عَلَيۡكُم بِوَكِيلٖ ﴿١٠٨﴾ وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ وَٱصۡبِرۡ حَتَّىٰ يَحۡكُمَ ٱللَّهُۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ ﴿١٠٩﴾", "w": [["يا أيها الناس", "يا أهل مكة."], ["قد جاءكم الحق", "الرسول يتلو القرآن ويبيّن الدين الحق."], ["من اهتدى", "آمن بالله ورسوله وعبد الله تعالى موحّداً له."], ["ومن ضل", "أبى إلا الإصرار على الشرك والتكذيب والعصيان."], ["فعليها", "وبال الضلال على نفس الضال، كما أن ثواب الهداية لنفس المهتدي."], ["وما أنا عليكم بوكيل", "بمجبر لكم على الهداية، وإنما أنا مبلّغ ونذير."], ["واصبر حتى يحكم الله", "أي في المشركين بأمره."], ["خير الحاكمين", "رحمةً وعدلاً وإنفاذاً لما يحكم به لعظيم قدرته."]], "m": "هذا الإعلان الأخير في السورة: يا أيها الناس، وهو نداء عام للبشرية وإن أريد به ابتداءً أهل مكة، قد جاءكم الحق من ربكم، القرآن يتلوه رسول الله ﷺ، وفيه بيان الدين الحق الذي لا كمال للإنسان إلا بالإيمان به. فمن اهتدى فإنما ثواب هدايته لنفسه، إذ هي التي تزكو وتطهر وتتأهّل لسعادة الدارين، ومن ضلّ فإنما جزاء ضلاله عائد على نفسه، إذ هي التي تتدسّى وتخبث وتتأهّل لمقت الله وعقابه، وما أنا عليكم بمجبر على الهداية. واتبع ما يوحى إليك من الأوامر والنواهي ولا تفرّط في شيء منه، ولا تتبع ما لا يوحى إليك، واصبر على الثبات على الدعوة وتحمّل الأذى حتى يحكم الله فيهم، وقد حكم فأمره بقتالهم في بدر وواصل حتى دانوا لله بالإسلام، وهو خير الحاكمين وأعدل من يقضي لكمال علمه وحكمته وعظيم قدرته وواسع رحمته.", "h": ["تقرير أن القرآن والرسول حق، والإسلام حق.", "تقرير مبدأ أن المرء يشقى ويسعد بكسبه لا بكسب غيره.", "وجوب اتباع الوحي الإلهي الذي تضمّنه القرآن والسنة الصحيحة."], "k": "«فمن اهتدى فإنما يهتدي لنفسه»… كل طاعة أعملها لي أنا أولاً؛ فهل أعمل وكأني أتفضّل بها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 140;
