insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (141, 11, 1, 5, 'سورة هود ١ – ٥', '«كتاب أحكمت آياته ثم فصلت»، «وأن استغفروا ربكم ثم توبوا إليه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 141) = $j$[{"lbl": "الآيات ١ – ٥", "q": "الٓرۚ كِتَٰبٌ أُحۡكِمَتۡ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتۡ مِن لَّدُنۡ حَكِيمٍ خَبِيرٍ ﴿١﴾ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۚ إِنَّنِي لَكُم مِّنۡهُ نَذِيرٞ وَبَشِيرٞ ﴿٢﴾ وَأَنِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُمَتِّعۡكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَيُؤۡتِ كُلَّ ذِي فَضۡلٖ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡاْ فَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ كَبِيرٍ ﴿٣﴾ إِلَى ٱللَّهِ مَرۡجِعُكُمۡۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٤﴾ أَلَآ إِنَّهُمۡ يَثۡنُونَ صُدُورَهُمۡ لِيَسۡتَخۡفُواْ مِنۡهُۚ أَلَا حِينَ يَسۡتَغۡشُونَ ثِيَابَهُمۡ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٥﴾", "w": [["أحكمت", "نُظمت نظماً متقناً ورُصفت ترصيفاً لا خلل فيه."], ["فصلت", "ببيان الأحكام والقصص والمواعظ وأنواع الهدايات."], ["من لدن", "من عند حكيم خبير، وهو الله جل جلاله."], ["متاعاً حسناً", "بطيب العيش وسعة الرزق."], ["إلى أجل مسمى", "موت الإنسان بأجله الذي كُتب له."], ["ويؤت كل ذي فضل", "ويعطِ كل ذي عمل صالح فاضل جزاءه الفاضل."], ["عذاب يوم كبير", "هو عذاب يوم القيامة."], ["يثنون صدورهم", "يطأطئون رؤوسهم فوق صدورهم ليستتروا عن الله."], ["يستغشون ثيابهم", "يغطّون رؤوسهم ووجوههم حتى لا يراهم الله في نظرهم الباطل."]], "m": "«الر»: الله أعلم بمراده بذلك، وقد أفادت أن القرآن الذي تحدّاهم الله بمثله مؤلَّف من مثل هذه الحروف، فإن عجزوا فهو كتاب الله، وأنها جاءت على خلاف ما ألفوه فاضطرتهم إلى سماعه. هذا كتاب أُحكمت آياته فلا خلل فيها ولا في تركيبها ولا معانيها، ثم فُصّلت ببيان ما تحمله من أحكام وشرائع ومواعظ وعقائد وآداب بما لا نظير له، من لدن حكيم في تدبيره وشرعه، خبير بأحوال عباده. أُنزل بألّا تعبدوا إلا الله، إنني لكم منه نذير من عذاب شديد إن لم تتوبوا، وبشير بالجنة لمن آمن ووحّد وعمل صالحاً. وأن استغفروا ربكم معترفين بخطئكم، ثم توبوا إليه بالإيمان والطاعة، يمتّعكم في هذه الحياة متاعاً حسناً بالنعم الوفيرة إلى آجالكم، ويؤت كل صاحب فضل في الدنيا من بر وصدقة وإحسان فضله يوم القيامة في الجنة، وإن تعرضوا فإني أخاف عليكم عذاب يوم القيامة، إلى الله مرجعكم وهو على كل شيء قدير. ألا إنهم يثنون صدورهم ليستخفوا منه، كان بعضهم يطأطئ رأسه حتى لا يراه الرسول ﷺ بغضاً له، وبعضهم ظنّاً أنه يخفي نفسه عن الله، وهذا نهاية الجهل، ألا حين يتغطّون بثيابهم يعلم ما يسرّون وما يعلنون، إنه عليم بذات الصدور.", "h": ["مظهر من مظاهر إعجاز القرآن، وهو أنه مؤلَّف من الحروف المقطعة ولم تستطع العرب الإتيان بسورة مثله.", "بيان العلة في إنزال الكتاب وإحكام آياته وتفصيلها، وهي أن يُعبد الله تعالى وحده، وأن يستغفره المشركون ثم يتوبوا إليه ليكملوا ويسعدوا في الدنيا والآخرة.", "وجوب التخلّي عن الشرك أولاً، ثم العبادة الخالصة ثانياً.", "المعروف لا يضيع عند الله تعالى إذا كان صاحبه من أهل التوحيد: «ويؤت كل ذي فضل فضله».", "بيان جهل المشركين الذين كانوا يستترون عن الله برؤوسهم وثيابهم.", "مرجع الناس إلى ربهم شاؤوا أم أبوا، والجزاء عادل، ولا يهلك على الله إلا هالك."], "k": "«يمتعكم متاعاً حسناً»… الاستغفار والتوبة مفتاح طيب العيش؛ فكم مرة استغفرت اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 141;
insert into public.tdb_cards(topic, i, body) select 141, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "الٓرۚ كِتَٰبٌ أُحۡكِمَتۡ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتۡ مِن لَّدُنۡ حَكِيمٍ خَبِيرٍ ﴿١﴾ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۚ إِنَّنِي لَكُم مِّنۡهُ نَذِيرٞ وَبَشِيرٞ ﴿٢﴾ وَأَنِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُمَتِّعۡكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَيُؤۡتِ كُلَّ ذِي فَضۡلٖ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡاْ فَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ كَبِيرٍ ﴿٣﴾ إِلَى ٱللَّهِ مَرۡجِعُكُمۡۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٤﴾ أَلَآ إِنَّهُمۡ يَثۡنُونَ صُدُورَهُمۡ لِيَسۡتَخۡفُواْ مِنۡهُۚ أَلَا حِينَ يَسۡتَغۡشُونَ ثِيَابَهُمۡ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٥﴾", "w": [["أحكمت", "نُظمت نظماً متقناً ورُصفت ترصيفاً لا خلل فيه."], ["فصلت", "ببيان الأحكام والقصص والمواعظ وأنواع الهدايات."], ["من لدن", "من عند حكيم خبير، وهو الله جل جلاله."], ["متاعاً حسناً", "بطيب العيش وسعة الرزق."], ["إلى أجل مسمى", "موت الإنسان بأجله الذي كُتب له."], ["ويؤت كل ذي فضل", "ويعطِ كل ذي عمل صالح فاضل جزاءه الفاضل."], ["عذاب يوم كبير", "هو عذاب يوم القيامة."], ["يثنون صدورهم", "يطأطئون رؤوسهم فوق صدورهم ليستتروا عن الله."], ["يستغشون ثيابهم", "يغطّون رؤوسهم ووجوههم حتى لا يراهم الله في نظرهم الباطل."]], "m": "«الر»: الله أعلم بمراده بذلك، وقد أفادت أن القرآن الذي تحدّاهم الله بمثله مؤلَّف من مثل هذه الحروف، فإن عجزوا فهو كتاب الله، وأنها جاءت على خلاف ما ألفوه فاضطرتهم إلى سماعه. هذا كتاب أُحكمت آياته فلا خلل فيها ولا في تركيبها ولا معانيها، ثم فُصّلت ببيان ما تحمله من أحكام وشرائع ومواعظ وعقائد وآداب بما لا نظير له، من لدن حكيم في تدبيره وشرعه، خبير بأحوال عباده. أُنزل بألّا تعبدوا إلا الله، إنني لكم منه نذير من عذاب شديد إن لم تتوبوا، وبشير بالجنة لمن آمن ووحّد وعمل صالحاً. وأن استغفروا ربكم معترفين بخطئكم، ثم توبوا إليه بالإيمان والطاعة، يمتّعكم في هذه الحياة متاعاً حسناً بالنعم الوفيرة إلى آجالكم، ويؤت كل صاحب فضل في الدنيا من بر وصدقة وإحسان فضله يوم القيامة في الجنة، وإن تعرضوا فإني أخاف عليكم عذاب يوم القيامة، إلى الله مرجعكم وهو على كل شيء قدير. ألا إنهم يثنون صدورهم ليستخفوا منه، كان بعضهم يطأطئ رأسه حتى لا يراه الرسول ﷺ بغضاً له، وبعضهم ظنّاً أنه يخفي نفسه عن الله، وهذا نهاية الجهل، ألا حين يتغطّون بثيابهم يعلم ما يسرّون وما يعلنون، إنه عليم بذات الصدور.", "h": ["مظهر من مظاهر إعجاز القرآن، وهو أنه مؤلَّف من الحروف المقطعة ولم تستطع العرب الإتيان بسورة مثله.", "بيان العلة في إنزال الكتاب وإحكام آياته وتفصيلها، وهي أن يُعبد الله تعالى وحده، وأن يستغفره المشركون ثم يتوبوا إليه ليكملوا ويسعدوا في الدنيا والآخرة.", "وجوب التخلّي عن الشرك أولاً، ثم العبادة الخالصة ثانياً.", "المعروف لا يضيع عند الله تعالى إذا كان صاحبه من أهل التوحيد: «ويؤت كل ذي فضل فضله».", "بيان جهل المشركين الذين كانوا يستترون عن الله برؤوسهم وثيابهم.", "مرجع الناس إلى ربهم شاؤوا أم أبوا، والجزاء عادل، ولا يهلك على الله إلا هالك."], "k": "«يمتعكم متاعاً حسناً»… الاستغفار والتوبة مفتاح طيب العيش؛ فكم مرة استغفرت اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;